ref_content:
Save this as `index.html` and open it in a modern browser. It uses only the Three.js core ES module from cdnjs, with custom camera controls and no addons.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Bamboo Box Kite</title>

  <style>
    :root {
      --ink: #173b46;
      --cream: #fff9e9;
      --coral: #ef604f;
      --teal: #24a7a9;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: linear-gradient(#82cfe9, #eaf7e8);
      color: var(--ink);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    #app,
    #app canvas {
      position: fixed;
      inset: 0;
      width: 100%;
      height: 100%;
      display: block;
    }

    #app canvas {
      touch-action: none;
      cursor: grab;
      outline: none;
    }

    #app canvas:active {
      cursor: grabbing;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 42%, transparent 48%, rgba(20, 62, 73, 0.12) 100%);
    }

    .hud {
      position: fixed;
      inset: 0;
      pointer-events: none;
    }

    .title-card {
      position: absolute;
      top: clamp(18px, 4vw, 38px);
      left: clamp(18px, 4vw, 42px);
      max-width: min(430px, calc(100vw - 36px));
      padding: 18px 20px 17px;
      border: 1px solid rgba(255, 255, 255, 0.65);
      border-radius: 18px;
      background: rgba(255, 249, 233, 0.78);
      box-shadow: 0 16px 45px rgba(28, 74, 81, 0.13);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 7px;
      color: #34727a;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      width: 24px;
      height: 2px;
      border-radius: 2px;
      background: var(--coral);
      content: "";
    }

    h1 {
      margin: 0;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(30px, 5vw, 48px);
      font-weight: 500;
      line-height: 0.98;
      letter-spacing: -0.035em;
    }

    .subtitle {
      max-width: 340px;
      margin: 11px 0 0;
      color: rgba(23, 59, 70, 0.72);
      font-size: 13px;
      line-height: 1.55;
    }

    .tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-top: 14px;
    }

    .tag {
      padding: 5px 9px;
      border-radius: 999px;
      background: rgba(36, 167, 169, 0.11);
      color: #26757b;
      font-size: 10px;
      font-weight: 750;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }

    .controls {
      position: absolute;
      right: clamp(18px, 4vw, 42px);
      bottom: clamp(18px, 4vw, 36px);
      display: flex;
      gap: 8px;
      pointer-events: auto;
    }

    button {
      border: 1px solid rgba(255, 255, 255, 0.72);
      border-radius: 999px;
      padding: 10px 14px;
      background: rgba(255, 249, 233, 0.86);
      box-shadow: 0 8px 25px rgba(24, 66, 73, 0.12);
      color: var(--ink);
      cursor: pointer;
      font: inherit;
      font-size: 12px;
      font-weight: 750;
      backdrop-filter: blur(10px);
      transition: transform 160ms ease, background 160ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      background: #fffaf0;
    }

    button:focus-visible {
      outline: 3px solid rgba(36, 167, 169, 0.35);
      outline-offset: 3px;
    }

    .hint {
      position: absolute;
      left: clamp(18px, 4vw, 42px);
      bottom: clamp(20px, 4vw, 38px);
      display: flex;
      align-items: center;
      gap: 9px;
      color: rgba(23, 59, 70, 0.68);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.04em;
    }

    .mouse {
      position: relative;
      width: 17px;
      height: 25px;
      border: 2px solid currentColor;
      border-radius: 9px;
    }

    .mouse::after {
      position: absolute;
      top: 4px;
      left: 50%;
      width: 2px;
      height: 5px;
      border-radius: 2px;
      background: currentColor;
      content: "";
      transform: translateX(-50%);
    }

    #loading {
      position: fixed;
      inset: 0;
      z-index: 10;
      display: grid;
      place-items: center;
      background: linear-gradient(#82cfe9, #eaf7e8);
      color: var(--ink);
      font-size: 12px;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      transition: opacity 500ms ease;
    }

    #loading.hidden {
      opacity: 0;
      pointer-events: none;
    }

    @media (max-width: 620px) {
      .title-card {
        padding: 14px 16px;
      }

      .subtitle {
        display: none;
      }

      .tags {
        margin-top: 10px;
      }

      .hint {
        bottom: 72px;
      }
    }
  </style>
</head>

<body>
  <div id="app"></div>
  <div class="vignette"></div>

  <div class="hud">
    <section class="title-card" aria-label="Scene title">
      <div class="eyebrow">Handcrafted in the breeze</div>
      <h1>Bamboo<br>Box Kite</h1>
      <p class="subtitle">
        Two hand-cut bamboo frames, bright woven sails, and a fluttering ribbon tail
        floating above the summer meadow.
      </p>
      <div class="tags">
        <span class="tag">Bamboo frame</span>
        <span class="tag">Box kite</span>
        <span class="tag">Summer wind</span>
      </div>
    </section>

    <div class="hint">
      <span class="mouse"></span>
      <span>Drag to orbit · Scroll or pinch to zoom</span>
    </div>

    <div class="controls">
      <button id="motionButton" type="button">Pause motion</button>
      <button id="resetButton" type="button">Reset view</button>
    </div>
  </div>

  <div id="loading">Preparing the breeze…</div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // ------------------------------------------------------------
    // Renderer and scene
    // ------------------------------------------------------------

    const app = document.getElementById("app");
    const loading = document.getElementById("loading");
    const motionButton = document.getElementById("motionButton");
    const resetButton = document.getElementById("resetButton");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.setAttribute("aria-label", "Interactive 3D bamboo box kite scene");
    app.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x9bd8ec);
    scene.fog = new THREE.Fog(0xb8dfdc, 17, 42);

    const camera = new THREE.PerspectiveCamera(
      42,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const cameraTarget = new THREE.Vector3(0, 2.65, 0);
    const defaultView = {
      azimuth: 0.64,
      polar: 1.47,
      radius: 9.3
    };

    const view = {
      azimuth: defaultView.azimuth,
      polar: defaultView.polar,
      radius: defaultView.radius,
      targetAzimuth: defaultView.azimuth,
      targetPolar: defaultView.polar,
      targetRadius: defaultView.radius
    };

    function updateCamera() {
      const sinPolar = Math.sin(view.polar);
      camera.position.set(
        cameraTarget.x + view.radius * sinPolar * Math.sin(view.azimuth),
        cameraTarget.y + view.radius * Math.cos(view.polar),
        cameraTarget.z + view.radius * sinPolar * Math.cos(view.azimuth)
      );
      camera.lookAt(cameraTarget);
    }

    updateCamera();

    // ------------------------------------------------------------
    // Lighting
    // ------------------------------------------------------------

    const hemisphere = new THREE.HemisphereLight(0xe7f8ff, 0x657b38, 2.15);
    scene.add(hemisphere);

    const sunlight = new THREE.DirectionalLight(0xfff0ce, 3.15);
    sunlight.position.set(-7, 13, 7);
    sunlight.castShadow = true;
    sunlight.shadow.mapSize.set(2048, 2048);
    sunlight.shadow.camera.left = -10;
    sunlight.shadow.camera.right = 10;
    sunlight.shadow.camera.top = 12;
    sunlight.shadow.camera.bottom = -7;
    sunlight.shadow.camera.near = 0.5;
    sunlight.shadow.camera.far = 35;
    sunlight.shadow.bias = -0.00015;
    sunlight.target.position.set(0, 2.4, 0);
    scene.add(sunlight, sunlight.target);

    const fillLight = new THREE.DirectionalLight(0x9de5ff, 0.65);
    fillLight.position.set(8, 5, -9);
    scene.add(fillLight);

    // ------------------------------------------------------------
    // Gradient sky dome
    // ------------------------------------------------------------

    const sky = new THREE.Mesh(
      new THREE.SphereGeometry(44, 32, 18),
      new THREE.ShaderMaterial({
        side: THREE.BackSide,
        depthWrite: false,
        fog: false,
        uniforms: {
          topColor: { value: new THREE.Color(0x62bde3) },
          horizonColor: { value: new THREE.Color(0xdff2df) },
          lowColor: { value: new THREE.Color(0xf8e9c6) }
        },
        vertexShader: `
          varying vec3 vWorldPosition;

          void main() {
            vec4 worldPosition = modelMatrix * vec4(position, 1.0);
            vWorldPosition = worldPosition.xyz;
            gl_Position = projectionMatrix * viewMatrix * worldPosition;
          }
        `,
        fragmentShader: `
          uniform vec3 topColor;
          uniform vec3 horizonColor;
          uniform vec3 lowColor;
          varying vec3 vWorldPosition;

          void main() {
            float height = normalize(vWorldPosition).y;
            float upperMix = smoothstep(-0.02, 0.72, height);
            vec3 lower = mix(lowColor, horizonColor, smoothstep(-0.38, 0.04, height));
            vec3 color = mix(lower, topColor, upperMix);
            gl_FragColor = vec4(color, 1.0);
          }
        `
      })
    );
    sky.renderOrder = -10;
    scene.add(sky);

    // Sun and soft glow
    const sun = new THREE.Mesh(
      new THREE.SphereGeometry(0.72, 24, 16),
      new THREE.MeshBasicMaterial({ color: 0xffd66b, fog: false })
    );
    sun.position.set(-13, 12, -19);
    scene.add(sun);

    const sunGlow = new THREE.Mesh(
      new THREE.SphereGeometry(1.55, 24, 16),
      new THREE.MeshBasicMaterial({
        color: 0xffec9f,
        transparent: true,
        opacity: 0.16,
        depthWrite: false,
        fog: false
      })
    );
    sunGlow.position.copy(sun.position);
    scene.add(sunGlow);

    // ------------------------------------------------------------
    // Meadow and distant hills
    // ------------------------------------------------------------

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(100, 100),
      new THREE.MeshStandardMaterial({
        color: 0x7ea65b,
        roughness: 0.98,
        metalness: 0
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.12;
    ground.receiveShadow = true;
    scene.add(ground);

    const hillMaterial = new THREE.MeshStandardMaterial({
      color: 0x86a965,
      roughness: 1
    });

    const hills = [
      { position: [-15, -0.1, -19], scale: [10, 2.1, 6] },
      { position: [14, -0.5, -23], scale: [12, 2.5, 7] },
      { position: [0, -1.2, -29], scale: [17, 3.1, 8] },
      { position: [-20, -0.8, 3], scale: [8, 1.6, 5] }
    ];

    hills.forEach((hill) => {
      const mesh = new THREE.Mesh(new THREE.SphereGeometry(1, 28, 16), hillMaterial);
      mesh.position.set(...hill.position);
      mesh.scale.set(...hill.scale);
      mesh.receiveShadow = true;
      scene.add(mesh);
    });

    // Instanced grass blades
    const grassGeometry = new THREE.ConeGeometry(0.022, 0.31, 3);
    grassGeometry.translate(0, 0.145, 0);
    const grassMaterial = new THREE.MeshStandardMaterial({
      color: 0x527b3e,
      roughness: 1
    });

    const grassCount = 150;
    const grass = new THREE.InstancedMesh(grassGeometry, grassMaterial, grassCount);
    const dummy = new THREE.Object3D();

    let seed = 9137;
    function random() {
      seed = (seed * 16807) % 2147483647;
      return (seed - 1) / 2147483646;
    }

    for (let i = 0; i < grassCount; i++) {
      const x = (random() - 0.5) * 25;
      const z = (random() - 0.5) * 19;
      const scale = 0.65 + random() * 1.25;

      dummy.position.set(x, -0.1, z);
      dummy.rotation.set(
        (random() - 0.5) * 0.25,
        random() * Math.PI,
        (random() - 0.5) * 0.3
      );
      dummy.scale.set(scale, scale, scale);
      dummy.updateMatrix();
      grass.setMatrixAt(i, dummy.matrix);
    }

    grass.receiveShadow = true;
    scene.add(grass);

    // A handful of simple flowers
    const flowerColors = [0xffe4a3, 0xff8b78, 0xfaf2d1, 0xb9d8ff];

    function addFlower(x, z, color) {
      const flower = new THREE.Group();
      flower.position.set(x, 0, z);

      const stem = new THREE.Mesh(
        new THREE.CylinderGeometry(0.012, 0.016, 0.34, 5),
        new THREE.MeshStandardMaterial({ color: 0x477846, roughness: 1 })
      );
      stem.position.y = 0.17;
      flower.add(stem);

      const petalGeometry = new THREE.SphereGeometry(0.055, 8, 6);
      const petalMaterial = new THREE.MeshStandardMaterial({
        color,
        roughness: 0.85
      });

      for (let i = 0; i < 5; i++) {
        const angle = (i / 5) * Math.PI * 2;
        const petal = new THREE.Mesh(petalGeometry, petalMaterial);
        petal.position.set(
          Math.cos(angle) * 0.065,
          0.35,
          Math.sin(angle) * 0.065
        );
        petal.scale.set(1.3, 0.55, 0.8);
        petal.rotation.y = -angle;
        flower.add(petal);
      }

      const center = new THREE.Mesh(
        new THREE.SphereGeometry(0.04, 8, 6),
        new THREE.MeshStandardMaterial({ color: 0xe8a93e, roughness: 0.8 })
      );
      center.position.y = 0.38;
      flower.add(center);

      scene.add(flower);
    }

    for (let i = 0; i < 15; i++) {
      addFlower(
        (random() - 0.5) * 18,
        (random() - 0.5) * 13,
        flowerColors[i % flowerColors.length]
      );
    }

    // ------------------------------------------------------------
    // Clouds
    // ------------------------------------------------------------

    const cloudMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 1,
      transparent: true,
      opacity: 0.93
    });

    const cloudGeometry = new THREE.SphereGeometry(1, 14, 10);
    const clouds = [];

    function addCloud(x, y, z, scale, phase) {
      const cloud = new THREE.Group();
      const pieces = [
        [-1.05, 0.0, 0, 0.85],
        [-0.35, 0.25, 0.05, 1.15],
        [0.45, 0.12, 0, 0.95],
        [1.05, -0.05, 0.05, 0.72],
        [0.05, -0.12, 0.18, 1.2]
      ];

      pieces.forEach(([px, py, pz, ps]) => {
        const puff = new THREE.Mesh(cloudGeometry, cloudMaterial);
        puff.position.set(px, py, pz);
        puff.scale.set(ps * 1.25, ps * 0.66, ps * 0.75);
        cloud.add(puff);
      });

      cloud.position.set(x, y, z);
      cloud.scale.setScalar(scale);
      cloud.userData.baseX = x;
      cloud.userData.phase = phase;
      scene.add(cloud);
      clouds.push(cloud);
    }

    addCloud(-10, 9.5, -16, 1.25, 0.2);
    addCloud(9, 11.5, -21, 1.05, 1.7);
    addCloud(-2, 13.5, -25, 0.72, 3.1);
    addCloud(15, 7.8, -11, 0.8, 4.4);

    // Distant birds
    function makeBird() {
      const geometry = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(-0.24, 0, 0),
        new THREE.Vector3(0, -0.08, 0),
        new THREE.Vector3(0.24, 0, 0)
      ]);

      return new THREE.Line(
        geometry,
        new THREE.LineBasicMaterial({ color: 0x42636a, transparent: true, opacity: 0.72 })
      );
    }

    const bird1 = makeBird();
    bird1.position.set(-6.5, 8.3, -10);
    bird1.rotation.y = -0.4;

    const bird2 = makeBird();
    bird2.position.set(-5.6, 8.6, -10);
    bird2.scale.setScalar(0.72);
    bird2.rotation.y = -0.4;

    scene.add(bird1, bird2);

    // ------------------------------------------------------------
    // Kite
    // ------------------------------------------------------------

    const kite = new THREE.Group();
    kite.position.set(0, 4.55, 0);
    kite.rotation.set(0.03, -0.45, -0.08);
    scene.add(kite);

    const KITE_WIDTH = 1.92;
    const KITE_HEIGHT = 2.7;
    const halfWidth = KITE_WIDTH / 2;
    const halfHeight = KITE_HEIGHT / 2;

    const v = (x, y, z) => new THREE.Vector3(x, y, z);

    // Procedural woven sail texture
    function createSailTexture(colorA, colorB) {
      const canvas = document.createElement("canvas");
      canvas.width = 512;
      canvas.height = 768;
      const context = canvas.getContext("2d");

      const colors = [colorA, colorB, colorB, colorA];
      const rectangles = [
        [0, 0, 256, 384],
        [256, 0, 256, 384],
        [0, 384, 256, 384],
        [256, 384, 256, 384]
      ];

      rectangles.forEach((rect, index) => {
        context.fillStyle = colors[index];
        context.fillRect(...rect);
      });

      // Soft vertical and horizontal weave.
      context.globalAlpha = 0.09;
      context.strokeStyle = "#ffffff";
      context.lineWidth = 1;

      for (let x = 0; x <= 512; x += 8) {
        context.beginPath();
        context.moveTo(x, 0);
        context.lineTo(x, 768);
        context.stroke();
      }

      for (let y = 0; y <= 768; y += 8) {
        context.beginPath();
        context.moveTo(0, y);
        context.lineTo(512, y);
        context.stroke();
      }

      // Panel seams.
      context.globalAlpha = 0.32;
      context.strokeStyle = "#6a4937";
      context.lineWidth = 5;
      context.beginPath();
      context.moveTo(256, 0);
      context.lineTo(256, 768);
      context.moveTo(0, 384);
      context.lineTo(512, 384);
      context.stroke();

      // Cream fabric border.
      context.globalAlpha = 1;
      context.strokeStyle = "#fff0c9";
      context.lineWidth = 24;
      context.strokeRect(12, 12, 488, 744);

      // Stitching.
      context.strokeStyle = "#8b694e";
      context.lineWidth = 2;
      context.setLineDash([9, 10]);
      context.strokeRect(29, 29, 454, 710);
      context.setLineDash([]);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function createSailGeometry(width, height) {
      const geometry = new THREE.PlaneGeometry(width, height, 10, 14);
      const positions = geometry.attributes.position;

      for (let i = 0; i < positions.count; i++) {
        const x = positions.getX(i);
        const y = positions.getY(i);
        const u = x / width + 0.5;
        const w = y / height + 0.5;
        const bulge = Math.sin(u * Math.PI) * Math.sin(w * Math.PI) * 0.055;
        positions.setZ(i, bulge);
      }

      geometry.computeVertexNormals();
      return geometry;
    }

    const sailMaterialA = new THREE.MeshStandardMaterial({
      map: createSailTexture("#ef604f", "#f2b84b"),
      side: THREE.DoubleSide,
      roughness: 0.82,
      metalness: 0
    });

    const sailMaterialB = new THREE.MeshStandardMaterial({
      map: createSailTexture("#269fa8", "#f4df9e"),
      side: THREE.DoubleSide,
      roughness: 0.82,
      metalness: 0
    });

    const sailA = new THREE.Mesh(createSailGeometry(KITE_WIDTH, KITE_HEIGHT), sailMaterialA);
    sailA.castShadow = true;
    sailA.receiveShadow = true;
    kite.add(sailA);

    const sailB = new THREE.Mesh(createSailGeometry(KITE_WIDTH, KITE_HEIGHT), sailMaterialB);
    sailB.rotation.y = Math.PI / 2;
    sailB.castShadow = true;
    sailB.receiveShadow = true;
    kite.add(sailB);

    // ------------------------------------------------------------
    // Bamboo frame with raised nodes
    // ------------------------------------------------------------

    const bambooMaterial = new THREE.MeshStandardMaterial({
      color: 0xc79642,
      roughness: 0.64,
      metalness: 0
    });

    const bambooNodeMaterial = new THREE.MeshStandardMaterial({
      color: 0x79552c,
      roughness: 0.78
    });

    const upAxis = new THREE.Vector3(0, 1, 0);

    function addBambooRod(parent, start, end, radius = 0.028) {
      const direction = new THREE.Vector3().subVectors(end, start);
      const length = direction.length();
      const midpoint = new THREE.Vector3().addVectors(start, end).multiplyScalar(0.5);
      const quaternion = new THREE.Quaternion().setFromUnitVectors(
        upAxis,
        direction.clone().normalize()
      );

      const rod = new THREE.Mesh(
        new THREE.CylinderGeometry(radius * 0.88, radius, length, 10),
        bambooMaterial
      );
      rod.position.copy(midpoint);
      rod.quaternion.copy(quaternion);
      rod.castShadow = true;
      rod.receiveShadow = true;
      parent.add(rod);

      const nodeCount = Math.max(2, Math.floor(length / 0.38));

      for (let i = 1; i < nodeCount; i++) {
        const t = i / nodeCount;
        const node = new THREE.Mesh(
          new THREE.CylinderGeometry(radius * 1.12, radius * 1.12, 0.036, 10),
          bambooNodeMaterial
        );
        node.position.lerpVectors(start, end, t);
        node.quaternion.copy(quaternion);
        node.castShadow = true;
        parent.add(node);
      }
    }

    // First crossed rectangular frame.
    addBambooRod(kite, v(-halfWidth, -halfHeight, 0), v(-halfWidth, halfHeight, 0));
    addBambooRod(kite, v(-halfWidth, halfHeight, 0), v(halfWidth, halfHeight, 0));
    addBambooRod(kite, v(halfWidth, halfHeight, 0), v(halfWidth, -halfHeight, 0));
    addBambooRod(kite, v(halfWidth, -halfHeight, 0), v(-halfWidth, -halfHeight, 0));

    // Second crossed rectangular frame.
    addBambooRod(kite, v(0, -halfHeight, -halfWidth), v(0, -halfHeight, halfWidth));
    addBambooRod(kite, v(0, -halfHeight, halfWidth), v(0, halfHeight, halfWidth));
    addBambooRod(kite, v(0, halfHeight, halfWidth), v(0, halfHeight, -halfWidth));
    addBambooRod(kite, v(0, halfHeight, -halfWidth), v(0, -halfHeight, -halfWidth));

    // Center spars.
    addBambooRod(kite, v(0, -halfHeight, 0), v(0, halfHeight, 0), 0.032);
    addBambooRod(kite, v(-halfWidth, 0, 0), v(halfWidth, 0, 0), 0.024);
    addBambooRod(kite, v(0, 0, -halfWidth), v(0, 0, halfWidth), 0.024);

    // Binding knots at frame intersections.
    const cornerPositions = [
      v(-halfWidth, -halfHeight, 0),
      v(-halfWidth, halfHeight, 0),
      v(halfWidth, halfHeight, 0),
      v(halfWidth, -halfHeight, 0),
      v(0, -halfHeight, -halfWidth),
      v(0, -halfHeight, halfWidth),
      v(0, halfHeight, halfWidth),
      v(0, halfHeight, -halfWidth),
      v(0, 0, 0)
    ];

    cornerPositions.forEach((position) => {
      const knot = new THREE.Mesh(
        new THREE.SphereGeometry(0.047, 9, 7),
        bambooNodeMaterial
      );
      knot.position.copy(position);
      knot.castShadow = true;
      kite.add(knot);
    });

    // ------------------------------------------------------------
    // Bridle and flying line
    // ------------------------------------------------------------

    const ropeMaterial = new THREE.LineBasicMaterial({
      color: 0xf5e2ad,
      transparent: true,
      opacity: 0.92
    });

    const bridle = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([
        v(0, 0.62, 0),
        v(0, 0, 0.9),
        v(0, -0.62, 0)
      ]),
      ropeMaterial
    );
    kite.add(bridle);

    const bridleNose = new THREE.Object3D();
    bridleNose.position.set(0, 0, 0.9);
    kite.add(bridleNose);

    const groundAnchor = new THREE.Vector3(3.15, 0.28, 1.35);
    const flyingPositions = new Float32Array(6);
    const flyingGeometry = new THREE.BufferGeometry();
    flyingGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(flyingPositions, 3).setUsage(THREE.DynamicDrawUsage)
    );

    const flyingLine = new THREE.Line(
      flyingGeometry,
      new THREE.LineBasicMaterial({
        color: 0xffedbf,
        transparent: true,
        opacity: 0.8
      })
    );
    flyingLine.frustumCulled = false;
    scene.add(flyingLine);

    // Small wooden line spool.
    const spool = new THREE.Group();
    spool.position.copy(groundAnchor);
    spool.position.y = 0.09;

    const spoolWood = new THREE.MeshStandardMaterial({
      color: 0x9b6737,
      roughness: 0.76
    });

    const spoolCore = new THREE.Mesh(
      new THREE.CylinderGeometry(0.12, 0.12, 0.22, 18),
      spoolWood
    );
    spoolCore.castShadow = true;
    spool.add(spoolCore);

    [0.115, -0.115].forEach((y) => {
      const flange = new THREE.Mesh(
        new THREE.CylinderGeometry(0.2, 0.2, 0.035, 20),
        spoolWood
      );
      flange.position.y = y;
      flange.castShadow = true;
      spool.add(flange);
    });

    scene.add(spool);

    // ------------------------------------------------------------
    // Animated ribbon tail and bows
    // ------------------------------------------------------------

    const tailRig = new THREE.Group();
    kite.add(tailRig);

    const tailPointCount = 65;
    const tailPositions = new Float32Array(tailPointCount * 3);
    const tailGeometry = new THREE.BufferGeometry();
    tailGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(tailPositions, 3).setUsage(THREE.DynamicDrawUsage)
    );

    const tailLine = new THREE.Line(
      tailGeometry,
      new THREE.LineBasicMaterial({ color: 0xfff4d3 })
    );
    tailLine.frustumCulled = false;
    tailRig.add(tailLine);

    const bowGeometry = new THREE.BufferGeometry();
    bowGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute([
        0, 0, 0,
        -0.29, 0.085, 0,
        -0.07, -0.055, 0,
        0, 0, 0,
        0.29, 0.085, 0,
        0.07, -0.055, 0
      ], 3)
    );
    bowGeometry.computeVertexNormals();

    const bowColors = [0xef604f, 0xf5bd49, 0x29a7aa, 0xf7e8bd];
    const bows = [];

    for (let i = 0; i < 8; i++) {
      const bow = new THREE.Group();
      const material = new THREE.MeshStandardMaterial({
        color: bowColors[i % bowColors.length],
        side: THREE.DoubleSide,
        roughness: 0.75
      });

      const left = new THREE.Mesh(bowGeometry, material);
      const right = new THREE.Mesh(bowGeometry, material);
      bow.add(left, right);

      const knot = new THREE.Mesh(
        new THREE.SphereGeometry(0.035, 8, 6),
        material
      );
      bow.add(knot);

      tailRig.add(bow);
      bows.push(bow);
    }

    const xAxis = new THREE.Vector3(1, 0, 0);
    const alignmentQuaternion = new THREE.Quaternion();

    function updateTail(time) {
      const flutter = time * 1.45;

      const points = [
        v(0, -halfHeight, 0),
        v(0.08 + Math.sin(flutter) * 0.08, -halfHeight - 0.38, 0.02),
        v(0.32 + Math.sin(flutter + 0.8) * 0.12, -halfHeight - 0.76, 0.08),
        v(0.22 + Math.sin(flutter + 1.6) * 0.16, -halfHeight - 1.17, -0.1),
        v(-0.24 + Math.sin(flutter + 2.4) * 0.18, -halfHeight - 1.59, 0.12),
        v(-0.62 + Math.sin(flutter + 3.2) * 0.16, -halfHeight - 2.03, -0.06),
        v(-0.43 + Math.sin(flutter + 4.1) * 0.2, -halfHeight - 2.46, 0.08),
        v(-0.88 + Math.sin(flutter + 5.0) * 0.18, -halfHeight - 2.92, -0.04)
      ];

      const curve = new THREE.CatmullRomCurve3(points, false, "catmullrom", 0.45);
      curve.arcLengthDivisions = 140;
      curve.updateArcLengths();

      const sampled = curve.getPoints(tailPointCount - 1);

      for (let i = 0; i < tailPointCount; i++) {
        tailPositions[i * 3] = sampled[i].x;
        tailPositions[i * 3 + 1] = sampled[i].y;
        tailPositions[i * 3 + 2] = sampled[i].z;
      }

      tailGeometry.attributes.position.needsUpdate = true;

      bows.forEach((bow, index) => {
        const t = (index + 1) / (bows.length + 1);
        const position = curve.getPointAt(t);
        const tangent = curve.getTangentAt(t).normalize();

        alignmentQuaternion.setFromUnitVectors(xAxis, tangent);
        bow.position.copy(position);
        bow.quaternion.copy(alignmentQuaternion);
        bow.rotateY(Math.sin(time * 2.2 + index * 1.3) * 0.7);
        bow.rotateZ(Math.sin(time * 1.8 + index) * 0.22);
      });
    }

    // ------------------------------------------------------------
    // Custom pointer camera controls
    // ------------------------------------------------------------

    const pointers = new Map();
    let lastSingleX = 0;
    let lastSingleY = 0;
    let lastPinchDistance = 0;

    function pointerDistance() {
      const values = [...pointers.values()];
      if (values.length < 2) return 0;
      return Math.hypot(values[0].x - values[1].x, values[0].y - values[1].y);
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
      renderer.domElement.setPointerCapture(event.pointerId);

      if (pointers.size === 1) {
        lastSingleX = event.clientX;
        lastSingleY = event.clientY;
      } else if (pointers.size === 2) {
        lastPinchDistance = pointerDistance();
      }
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

      if (pointers.size === 1) {
        const dx = event.clientX - lastSingleX;
        const dy = event.clientY - lastSingleY;

        view.targetAzimuth -= dx * 0.0052;
        view.targetPolar = THREE.MathUtils.clamp(
          view.targetPolar - dy * 0.0048,
          0.45,
          1.72
        );

        lastSingleX = event.clientX;
        lastSingleY = event.clientY;
      } else if (pointers.size === 2) {
        const distance = pointerDistance();

        if (lastPinchDistance > 0 && distance > 0) {
          view.targetRadius = THREE.MathUtils.clamp(
            view.targetRadius * (lastPinchDistance / distance),
            5.2,
            16
          );
        }

        lastPinchDistance = distance;
      }
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);
      lastPinchDistance = pointers.size === 2 ? pointerDistance() : 0;
    }

    renderer.domElement.addEventListener("pointerup", releasePointer);
    renderer.domElement.addEventListener("pointercancel", releasePointer);
    renderer.domElement.addEventListener("lostpointercapture", releasePointer);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        view.targetRadius = THREE.MathUtils.clamp(
          view.targetRadius * Math.exp(event.deltaY * 0.001),
          5.2,
          16
        );
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetView);

    function resetView() {
      view.targetAzimuth = defaultView.azimuth;
      view.targetPolar = defaultView.polar;
      view.targetRadius = defaultView.radius;
    }

    resetButton.addEventListener("click", resetView);

    // ------------------------------------------------------------
    // Motion toggle and resize
    // ------------------------------------------------------------

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let motionEnabled = !reducedMotion;

    function updateMotionButton() {
      motionButton.textContent = motionEnabled ? "Pause motion" : "Resume motion";
    }

    updateMotionButton();

    motionButton.addEventListener("click", () => {
      motionEnabled = !motionEnabled;
      updateMotionButton();
    });

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // ------------------------------------------------------------
    // Animation
    // ------------------------------------------------------------

    const clock = new THREE.Clock();
    const worldNosePosition = new THREE.Vector3();

    function animate() {
      const time = clock.getElapsedTime();
      const motionTime = motionEnabled ? time : 0;

      // Kite motion.
      kite.position.y = 4.55 + Math.sin(motionTime * 0.82) * 0.13;
      kite.position.x = Math.sin(motionTime * 0.43) * 0.08;
      kite.rotation.y = -0.45 + Math.sin(motionTime * 0.37) * 0.12;
      kite.rotation.z = -0.08 + Math.sin(motionTime * 0.71) * 0.035;
      kite.rotation.x = 0.03 + Math.cos(motionTime * 0.51) * 0.018;

      // Tail.
      updateTail(motionTime);

      // Flying line.
      kite.updateMatrixWorld(true);
      bridleNose.getWorldPosition(worldNosePosition);

      flyingPositions[0] = worldNosePosition.x;
      flyingPositions[1] = worldNosePosition.y;
      flyingPositions[2] = worldNosePosition.z;
      flyingPositions[3] = groundAnchor.x;
      flyingPositions[4] = groundAnchor.y;
      flyingPositions[5] = groundAnchor.z;
      flyingGeometry.attributes.position.needsUpdate = true;

      // Clouds drift gently.
      clouds.forEach((cloud) => {
        cloud.position.x =
          cloud.userData.baseX + Math.sin(motionTime * 0.045 + cloud.userData.phase) * 1.25;
      });

      // Birds drift across the distance.
      bird1.position.x = -6.5 + ((motionTime * 0.13) % 5);
      bird2.position.x = bird1.position.x + 0.85;
      bird1.position.y = 8.3 + Math.sin(motionTime * 1.7) * 0.08;
      bird2.position.y = 8.6 + Math.sin(motionTime * 1.7 + 0.6) * 0.08;

      // Smooth custom camera controls.
      view.azimuth += (view.targetAzimuth - view.azimuth) * 0.085;
      view.polar += (view.targetPolar - view.polar) * 0.085;
      view.radius += (view.targetRadius - view.radius) * 0.085;
      updateCamera();

      renderer.render(scene, camera);
    }

    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
      setTimeout(() => loading.remove(), 600);
    });
  </script>
</body>
</html>
