<body>
  <section class="info">
    <div class="eyebrow">Ground-Mounted PV</div>
    <h1>Adjustable photovoltaic module</h1>
    <p>
      A 60-cell module on twin aluminum rails, four telescoping steel struts,
      and a pair of concrete footings. Use the rear view to inspect the
      junction box and cable.
    </p>
  </section>

  <section class="controls" aria-label="Scene controls">
    <div class="tilt-row">
      <label for="tilt">Module tilt</label>
      <output id="tiltValue" for="tilt">52°</output>
    </div>

    <input
      id="tilt"
      type="range"
      min="25"
      max="70"
      step="1"
      value="52"
      aria-label="Photovoltaic module tilt"
    >

    <div class="buttons">
      <button type="button" data-view="front">Front</button>
      <button type="button" data-view="rear">Rear / junction box</button>
      <button type="button" data-view="reset">3/4 view</button>
    </div>

    <div class="hint">
      Drag to orbit · Wheel or pinch to zoom · Right-drag / Shift-drag to pan
    </div>
  </section>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene and camera
    // -------------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xdce7e8);
    scene.fog = new THREE.Fog(0xdce7e8, 14, 32);

    const camera = new THREE.PerspectiveCamera(
      38,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const cameraTarget = new THREE.Vector3(0, 1.55, 0);
    const spherical = {
      radius: 9.5,
      theta: 0.68,
      phi: 1.16
    };

    const Y_AXIS = new THREE.Vector3(0, 1, 0);
    const X_AXIS = new THREE.Vector3(1, 0, 0);
    const Z_AXIS = new THREE.Vector3(0, 0, 1);

    function updateCamera() {
      const sinPhi = Math.sin(spherical.phi);

      camera.position.set(
        cameraTarget.x +
          spherical.radius * sinPhi * Math.sin(spherical.theta),
        cameraTarget.y + spherical.radius * Math.cos(spherical.phi),
        cameraTarget.z +
          spherical.radius * sinPhi * Math.cos(spherical.theta)
      );

      camera.lookAt(cameraTarget);
      camera.updateMatrixWorld();
    }

    updateCamera();

    // -------------------------------------------------------------------------
    // Lighting and ground
    // -------------------------------------------------------------------------

    const hemisphere = new THREE.HemisphereLight(
      0xe9f7ff,
      0x6d6559,
      2.15
    );
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xfff5df, 3.4);
    sun.position.set(-4.5, 9.5, 7.5);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -8;
    sun.shadow.camera.right = 8;
    sun.shadow.camera.top = 8;
    sun.shadow.camera.bottom = -8;
    sun.shadow.camera.near = 0.5;
    sun.shadow.camera.far = 25;
    sun.shadow.bias = -0.00035;
    sun.shadow.normalBias = 0.025;
    scene.add(sun);

    const fillLight = new THREE.DirectionalLight(0xbad8ef, 1.15);
    fillLight.position.set(7, 5, -6);
    scene.add(fillLight);

    const groundMaterial = new THREE.MeshStandardMaterial({
      color: 0xc4cbc6,
      roughness: 1,
      metalness: 0
    });

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(42, 42),
      groundMaterial
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    const grid = new THREE.GridHelper(32, 32, 0x75827e, 0x9da8a3);
    grid.position.y = 0.006;
    const gridMaterials = Array.isArray(grid.material)
      ? grid.material
      : [grid.material];

    gridMaterials.forEach((material) => {
      material.transparent = true;
      material.opacity = 0.16;
      material.depthWrite = false;
    });
    scene.add(grid);

    // -------------------------------------------------------------------------
    // Procedural textures
    // -------------------------------------------------------------------------

    function roundedRectPath(ctx, x, y, width, height, radius) {
      const r = Math.min(radius, width * 0.5, height * 0.5);
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + width - r, y);
      ctx.quadraticCurveTo(x + width, y, x + width, y + r);
      ctx.lineTo(x + width, y + height - r);
      ctx.quadraticCurveTo(
        x + width,
        y + height,
        x + width - r,
        y + height
      );
      ctx.lineTo(x + r, y + height);
      ctx.quadraticCurveTo(x, y + height, x, y + height - r);
      ctx.lineTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.closePath();
    }

    function makeSolarTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 1536;
      canvas.height = 832;

      const ctx = canvas.getContext("2d");
      const columns = 6;
      const rows = 10;
      const margin = 8;
      const gap = 6;
      const cellWidth = (canvas.width - margin * 2 - gap * (columns - 1)) / columns;
      const cellHeight = (canvas.height - margin * 2 - gap * (rows - 1)) / rows;

      ctx.fillStyle = "#050b16";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      for (let row = 0; row < rows; row++) {
        for (let column = 0; column < columns; column++) {
          const x = margin + column * (cellWidth + gap);
          const y = margin + row * (cellHeight + gap);

          const gradient = ctx.createLinearGradient(x, y, x + cellWidth, y + cellHeight);
          gradient.addColorStop(0, "#153761");
          gradient.addColorStop(0.48, "#0d274d");
          gradient.addColorStop(1, "#07182f");

          roundedRectPath(ctx, x, y, cellWidth, cellHeight, 5);
          ctx.fillStyle = gradient;
          ctx.fill();

          ctx.save();
          roundedRectPath(ctx, x, y, cellWidth, cellHeight, 5);
          ctx.clip();

          // Subtle crystalline texture.
          ctx.strokeStyle = "rgba(125, 166, 200, 0.055)";
          ctx.lineWidth = 2;

          for (let d = -cellHeight; d < cellWidth; d += 34) {
            ctx.beginPath();
            ctx.moveTo(x + d, y);
            ctx.lineTo(x + d + cellHeight, y + cellHeight);
            ctx.stroke();
          }

          // Fine horizontal cell fingers.
          ctx.strokeStyle = "rgba(172, 203, 222, 0.17)";
          ctx.lineWidth = 1;

          for (let fy = 7; fy < cellHeight; fy += 9) {
            ctx.beginPath();
            ctx.moveTo(x + 2, y + fy);
            ctx.lineTo(x + cellWidth - 2, y + fy);
            ctx.stroke();
          }

          // Vertical busbars.
          ctx.strokeStyle = "rgba(191, 213, 226, 0.55)";
          ctx.lineWidth = 2.4;

          [0.34, 0.67].forEach((fraction) => {
            const busX = x + cellWidth * fraction;
            ctx.beginPath();
            ctx.moveTo(busX, y + 2);
            ctx.lineTo(busX, y + cellHeight - 2);
            ctx.stroke();
          });

          ctx.restore();

          ctx.strokeStyle = "rgba(4, 10, 22, 0.9)";
          ctx.lineWidth = 2;
          roundedRectPath(ctx, x, y, cellWidth, cellHeight, 5);
          ctx.stroke();
        }
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );
      return texture;
    }

    function makeConcreteTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 256;

      const ctx = canvas.getContext("2d");
      let seed = 31891;

      const random = () => {
        seed = (seed * 1664525 + 1013904223) >>> 0;
        return seed / 4294967296;
      };

      ctx.fillStyle = "#91958e";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 2600; i++) {
        const shade = Math.floor(105 + random() * 80);
        const alpha = 0.08 + random() * 0.19;
        ctx.fillStyle = `rgba(${shade},${shade},${shade - 4},${alpha})`;
        ctx.fillRect(
          random() * 256,
          random() * 256,
          0.5 + random() * 1.8,
          0.5 + random() * 1.8
        );
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(2, 2);
      return texture;
    }

    function makeLabelTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 512;
      canvas.height = 224;

      const ctx = canvas.getContext("2d");
      ctx.fillStyle = "#e8ece8";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "#1c3036";
      ctx.font = "700 42px Arial";
      ctx.fillText("PV-60 / 400 W", 24, 58);

      ctx.font = "25px Arial";
      ctx.fillText("ISO 9001 · 1000 V DC", 25, 100);
      ctx.fillText("SN 24-A07-00382", 25, 140);

      for (let i = 0; i < 58; i++) {
        const width = 1 + (i % 4);
        ctx.fillRect(25 + i * 5, 170, width, 29);
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      return texture;
    }

    // -------------------------------------------------------------------------
    // Materials
    // -------------------------------------------------------------------------

    const frameMaterial = new THREE.MeshStandardMaterial({
      color: 0xc6ced1,
      metalness: 0.88,
      roughness: 0.24
    });

    const railMaterial = new THREE.MeshStandardMaterial({
      color: 0xaeb8bc,
      metalness: 0.82,
      roughness: 0.3
    });

    const darkMetalMaterial = new THREE.MeshStandardMaterial({
      color: 0x252d31,
      metalness: 0.72,
      roughness: 0.34
    });

    const galvanizedMaterial = new THREE.MeshStandardMaterial({
      color: 0x89969b,
      metalness: 0.78,
      roughness: 0.32
    });

    const polishedSteelMaterial = new THREE.MeshStandardMaterial({
      color: 0xd9dfe0,
      metalness: 0.96,
      roughness: 0.17
    });

    const rubberMaterial = new THREE.MeshStandardMaterial({
      color: 0x111719,
      roughness: 0.82,
      metalness: 0.08
    });

    const orangeMaterial = new THREE.MeshStandardMaterial({
      color: 0xec7c28,
      roughness: 0.42,
      metalness: 0.22
    });

    const concreteMaterial = new THREE.MeshStandardMaterial({
      color: 0xaaaDa7,
      map: makeConcreteTexture(),
      roughness: 0.98,
      metalness: 0
    });

    // -------------------------------------------------------------------------
    // Photovoltaic module
    // -------------------------------------------------------------------------

    const PANEL_WIDTH = 5.0;
    const PANEL_HEIGHT = 2.8;
    const FRAME_WIDTH = 0.09;
    const RAIL_Y = [-0.68, 0.68];
    const SUPPORT_X = [-1.65, 1.65];

    const panel = new THREE.Group();
    panel.position.set(0, 2.62, 0.12);
    panel.rotation.x = -THREE.MathUtils.degToRad(52);
    scene.add(panel);

    const backingMaterial = new THREE.MeshStandardMaterial({
      color: 0x111920,
      roughness: 0.72,
      metalness: 0.12
    });

    const backing = new THREE.Mesh(
      new THREE.BoxGeometry(
        PANEL_WIDTH - FRAME_WIDTH * 1.3,
        PANEL_HEIGHT - FRAME_WIDTH * 1.3,
        0.10
      ),
      backingMaterial
    );
    backing.position.z = -0.025;
    backing.castShadow = true;
    backing.receiveShadow = true;
    panel.add(backing);

    const cellMaterial = new THREE.MeshPhysicalMaterial({
      map: makeSolarTexture(),
      color: 0xffffff,
      roughness: 0.24,
      metalness: 0.2,
      clearcoat: 0.9,
      clearcoatRoughness: 0.12
    });

    const cellSurface = new THREE.Mesh(
      new THREE.PlaneGeometry(
        PANEL_WIDTH - FRAME_WIDTH * 2 - 0.035,
        PANEL_HEIGHT - FRAME_WIDTH * 2 - 0.035
      ),
      cellMaterial
    );
    cellSurface.position.z = 0.071;
    cellSurface.receiveShadow = true;
    panel.add(cellSurface);

    // Thin silver perimeter frame.
    const horizontalFrameGeometry = new THREE.BoxGeometry(
      PANEL_WIDTH,
