      );
      horizontal.castShadow = true;
      panel.add(horizontal);

      const vertical = new THREE.Mesh(
        verticalFrameGeometry,
        frameMaterial
      );
      vertical.position.set(
        side * (PANEL_WIDTH * 0.5 - FRAME_WIDTH * 0.5),
        0,
        0
      );
      vertical.castShadow = true;
      panel.add(vertical);
    });

    // Frame corner fasteners.
    const frameScrewGeometry = new THREE.CylinderGeometry(
      0.022,
      0.022,
      0.014,
