      rail.castShadow = true;
      rail.receiveShadow = true;
      panel.add(rail);

      const groove = new THREE.Mesh(
        new THREE.BoxGeometry(PANEL_WIDTH + 0.12, 0.035, 0.014),
        darkMetalMaterial
      );
      groove.position.set(0, railY, -0.316);
      panel.add(groove);
    });

    // Rail clamps at the four strut attachment points.
    SUPPORT_X.forEach((x) => {
      RAIL_Y.forEach((railY) => {
        const clamp = new THREE.Mesh(
          new THREE.BoxGeometry(0.3, 0.21, 0.14),
          darkMetalMaterial
        );
        clamp.position.set(x, railY, -0.37);
        clamp.castShadow = true;
        panel.add(clamp);
      });
    });

    // Junction box on the rear of the module.
    const junctionBox = new THREE.Mesh(
      new THREE.BoxGeometry(0.62, 0.46, 0.18),
