    );
    junctionBox.position.set(0.88, -0.08, -0.18);
    junctionBox.castShadow = true;
    panel.add(junctionBox);

    const junctionLid = new THREE.Mesh(
      new THREE.BoxGeometry(0.56, 0.40, 0.04),
      rubberMaterial
    );
    junctionLid.position.set(0.88, -0.08, -0.285);
    junctionLid.castShadow = true;
    panel.add(junctionLid);

    const lidScrewGeometry = new THREE.CylinderGeometry(
      0.022,
      0.022,
      0.018,
      12
    );

    [
      [-0.22, -0.14],
      [0.22, -0.14],
      [-0.22, 0.14],
      [0.22, 0.14]
    ].forEach(([x, y]) => {
      const screw = new THREE.Mesh(lidScrewGeometry, frameMaterial);
      screw.rotation.x = Math.PI / 2;
      screw.position.set(0.88 + x, -0.08 + y, -0.316);
      panel.add(screw);
    });

    const cableGland = new THREE.Mesh(
      new THREE.CylinderGeometry(0.055, 0.07, 0.15, 12),
      rubberMaterial
    );
    cableGland.position.set(1.05, -0.43, -0.18);
    panel.add(cableGland);

    const cableCurve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(1.05, -0.49, -0.18),
      new THREE.Vector3(1.18, -0.62, -0.22),
      new THREE.Vector3(1.05, -0.82, -0.30),
      new THREE.Vector3(0.75, -0.82, -0.37),
      new THREE.Vector3(0.57, -0.68, -0.38)
    ]);

    const cable = new THREE.Mesh(
      new THREE.TubeGeometry(cableCurve, 36, 0.024, 8, false),
      rubberMaterial
    );
    cable.castShadow = true;
    panel.add(cable);

    // Rear identification label.
    const label = new THREE.Mesh(
      new THREE.PlaneGeometry(0.62, 0.27),
      new THREE.MeshBasicMaterial({
        map: makeLabelTexture(),
        toneMapped: false
      })
    );
    label.position.set(-0.72, -0.06, -0.319);
    label.rotation.y = Math.PI;
    panel.add(label);

    // -------------------------------------------------------------------------
    // Concrete footing pair
    // -------------------------------------------------------------------------

    function createFooting(x) {
      const group = new THREE.Group();
      group.position.set(x, 0, 0.05);

      const slab = new THREE.Mesh(
        new THREE.BoxGeometry(1.18, 0.13, 2.12),
        concreteMaterial
      );
      slab.position.y = 0.065;
      slab.castShadow = true;
      slab.receiveShadow = true;
      group.add(slab);

      const block = new THREE.Mesh(
        new THREE.BoxGeometry(0.94, 0.36, 1.88),
        concreteMaterial
      );
      block.position.y = 0.31;
      block.castShadow = true;
      block.receiveShadow = true;
      group.add(block);

      const edgeMaterial = new THREE.LineBasicMaterial({
        color: 0x4f5c58,
        transparent: true,
        opacity: 0.16
      });

      const slabEdges = new THREE.LineSegments(
        new THREE.EdgesGeometry(slab.geometry),
        edgeMaterial
      );
      slabEdges.position.copy(slab.position);
      group.add(slabEdges);

      const blockEdges = new THREE.LineSegments(
        new THREE.EdgesGeometry(block.geometry),
        edgeMaterial
      );
      blockEdges.position.copy(block.position);
      group.add(blockEdges);

      scene.add(group);
    }

    SUPPORT_X.forEach(createFooting);

    // -------------------------------------------------------------------------
    // Telescoping adjustable struts
    // -------------------------------------------------------------------------

    function setCylinderBetween(mesh, start, end) {
      const direction = new THREE.Vector3().subVectors(end, start);
      const length = direction.length();

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.normalize());
      mesh.scale.set(1, length, 1);
    }

    function createStrut(x, railY) {
      const group = new THREE.Group();
      scene.add(group);

      const outerTube = new THREE.Mesh(
        new THREE.CylinderGeometry(0.072, 0.072, 1, 18),
        galvanizedMaterial
      );
      outerTube.castShadow = true;
      group.add(outerTube);

      const innerTube = new THREE.Mesh(
        new THREE.CylinderGeometry(0.043, 0.043, 1, 16),
        polishedSteelMaterial
      );
      innerTube.castShadow = true;
      group.add(innerTube);

      const collar = new THREE.Mesh(
        new THREE.CylinderGeometry(0.105, 0.105, 0.15, 18),
        darkMetalMaterial
      );
      collar.castShadow = true;
      group.add(collar);

      const adjustmentKnob = new THREE.Mesh(
        new THREE.CylinderGeometry(0.052, 0.052, 0.075, 12),
        orangeMaterial
      );
      adjustmentKnob.quaternion.setFromUnitVectors(Y_AXIS, X_AXIS);
      adjustmentKnob.castShadow = true;
      group.add(adjustmentKnob);

      const threadRings = [];
      const ringGeometry = new THREE.TorusGeometry(0.046, 0.007, 6, 20);

      for (let i = 0; i < 4; i++) {
        const ring = new THREE.Mesh(ringGeometry, darkMetalMaterial);
        group.add(ring);
        threadRings.push(ring);
      }

      const topPin = new THREE.Mesh(
        new THREE.CylinderGeometry(0.058, 0.058, 0.29, 12),
        darkMetalMaterial
      );
      topPin.quaternion.setFromUnitVectors(Y_AXIS, X_AXIS);
      topPin.castShadow = true;
      group.add(topPin);

      const footPin = new THREE.Mesh(
        new THREE.CylinderGeometry(0.058, 0.058, 0.29, 12),
        darkMetalMaterial
      );
      footPin.quaternion.setFromUnitVectors(Y_AXIS, X_AXIS);
      footPin.castShadow = true;
      group.add(footPin);

      // Slotted-looking anchor plate with four anchor bolts.
      const anchorPlate = new THREE.Group();
      scene.add(anchorPlate);

      const plate = new THREE.Mesh(
        new THREE.BoxGeometry(0.38, 0.05, 0.38),
        galvanizedMaterial
      );
      plate.castShadow = true;
      plate.receiveShadow = true;
      anchorPlate.add(plate);

      const boltGeometry = new THREE.CylinderGeometry(
        0.026,
        0.026,
        0.035,
        6
      );

      [
        [-0.13, -0.13],
        [0.13, -0.13],
        [-0.13, 0.13],
        [0.13, 0.13]
      ].forEach(([bx, bz]) => {
        const bolt = new THREE.Mesh(boltGeometry, darkMetalMaterial);
        bolt.position.set(bx, 0.042, bz);
        bolt.castShadow = true;
        anchorPlate.add(bolt);
      });

      return {
        x,
        railY,
        group,
        outerTube,
        innerTube,
        collar,
        adjustmentKnob,
        threadRings,
        topPin,
        footPin,
        anchorPlate
      };
    }

    const struts = [];

    RAIL_Y.forEach((railY) => {
      SUPPORT_X.forEach((x) => {
        struts.push(createStrut(x, railY));
      });
    });

    function updateStrut(strut) {
      panel.updateMatrixWorld(true);

      const top = panel.localToWorld(
        new THREE.Vector3(strut.x, strut.railY, -0.46)
      );
      const bottom = new THREE.Vector3(strut.x, 0.565, top.z);

      const direction = new THREE.Vector3().subVectors(top, bottom);
      const length = direction.length();
      direction.normalize();

      const pointAt = (t) =>
        bottom.clone().lerp(top, THREE.MathUtils.clamp(t, 0, 1));

      setCylinderBetween(strut.outerTube, bottom, pointAt(0.64));
      setCylinderBetween(strut.innerTube, pointAt(0.50), top);

      const collarPosition = pointAt(0.60);
      strut.collar.position.copy(collarPosition);
      strut.collar.quaternion.setFromUnitVectors(Y_AXIS, direction);

      strut.adjustmentKnob.position.copy(collarPosition);
      strut.adjustmentKnob.position.x += 0.115;

      strut.threadRings.forEach((ring, index) => {
        const t = 0.68 + index * 0.06;
        ring.position.copy(pointAt(t));
        ring.quaternion.setFromUnitVectors(Z_AXIS, direction);
      });

      strut.topPin.position.copy(top);
      strut.footPin.position.copy(bottom);

      strut.anchorPlate.position.set(strut.x, 0.515, top.z);

      // Keep the lower end visually attached to the anchor plate.
      strut.footPin.position.y = 0.565;
    }

    function setTilt(degrees) {
      panel.rotation.x = -THREE.MathUtils.degToRad(degrees);
      panel.updateMatrixWorld(true);
      struts.forEach(updateStrut);

      const output = document.getElementById("tiltValue");
      output.textContent = `${degrees}°`;

      const slider = document.getElementById("tilt");
      const percentage =
        ((degrees - Number(slider.min)) /
          (Number(slider.max) - Number(slider.min))) *
        100;

      slider.style.background = `linear-gradient(
        90deg,
        #1a91b7 0%,
        #1a91b7 ${percentage}%,
        #cbd5d7 ${percentage}%,
        #cbd5d7 100%
      )`;
    }

    document.getElementById("tilt").addEventListener("input", (event) => {
      setTilt(Number(event.target.value));
    });

    setTilt(52);

    // -------------------------------------------------------------------------
    // Direct camera controls: orbit, pan, zoom, keyboard and touch pinch
    // -------------------------------------------------------------------------

    let cameraTween = null;

    function shortestAngleDifference(from, to) {
      return Math.atan2(Math.sin(to - from), Math.cos(to - from));
    }

    function tweenCamera(destination, duration = 750) {
      cameraTween = {
        startTime: performance.now(),
        duration,
        from: {
          radius: spherical.radius,
          theta: spherical.theta,
          phi: spherical.phi,
          target: cameraTarget.clone()
        },
        to: {
          radius: destination.radius ?? spherical.radius,
          theta: destination.theta ?? spherical.theta,
          phi: destination.phi ?? spherical.phi,
          target: destination.target?.clone() ?? cameraTarget.clone()
        }
      };
    }

    document.querySelectorAll("[data-view]").forEach((button) => {
      button.addEventListener("click", () => {
        const view = button.dataset.view;

        if (view === "front") {
          tweenCamera({
            radius: 8.9,
            theta: 0.12,
            phi: 1.16,
            target: new THREE.Vector3(0, 1.65, 0)
          });
        } else if (view === "rear") {
          tweenCamera({
            radius: 8.9,
            theta: Math.PI - 0.15,
            phi: 1.14,
            target: new THREE.Vector3(0, 1.65, 0)
          });
        } else {
          tweenCamera({
            radius: 9.5,
            theta: 0.68,
            phi: 1.16,
            target: new THREE.Vector3(0, 1.55, 0)
          });
        }
      });
    });

    const canvas = renderer.domElement;
    const pointers = new Map();
    let dragMode = "orbit";
    let previousPinchDistance = 0;

    function pointerDistance() {
      const points = [...pointers.values()];
      if (points.length < 2) return 0;
      return Math.hypot(
        points[0].x - points[1].x,
        points[0].y - points[1].y
      );
    }

    canvas.addEventListener("contextmenu", (event) => {
      event.preventDefault();
    });

    canvas.addEventListener("pointerdown", (event) => {
      cameraTween = null;
      canvas.setPointerCapture(event.pointerId);

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        dragMode =
          event.button === 2 || event.shiftKey ? "pan" : "orbit";
      } else if (pointers.size === 2) {
        dragMode = "pinch";
        previousPinchDistance = pointerDistance();
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      const oldPoint = pointers.get(event.pointerId);
      const oldDistance = pointerDistance();

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        const dx = event.clientX - oldPoint.x;
        const dy = event.clientY - oldPoint.y;

        if (dragMode === "orbit") {
          spherical.theta -= dx * 0.006;
          spherical.phi = THREE.MathUtils.clamp(
            spherical.phi - dy * 0.006,
            0.28,
            1.46
          );
        } else if (dragMode === "pan") {
          const right = new THREE.Vector3();
          const up = new THREE.Vector3();

          camera.matrixWorld.extractBasis(right, up, new THREE.Vector3());

          const panScale = spherical.radius * 0.00125;
          cameraTarget.addScaledVector(right, -dx * panScale);
          cameraTarget.addScaledVector(up, dy * panScale);
          cameraTarget.y = THREE.MathUtils.clamp(
            cameraTarget.y,
            0.35,
            4.0
          );
        }

        updateCamera();
      } else if (pointers.size === 2) {
        const newDistance = pointerDistance();

        if (oldDistance > 0 && newDistance > 0) {
          spherical.radius = THREE.MathUtils.clamp(
            spherical.radius * (oldDistance / newDistance),
            4.8,
            18
          );
          updateCamera();
        }

        previousPinchDistance = newDistance;
      }
    });

    function endPointer(event) {
      pointers.delete(event.pointerId);

      if (pointers.size === 1) {
        dragMode = "orbit";
        previousPinchDistance = 0;
      } else if (pointers.size === 0) {
        dragMode = "orbit";
        previousPinchDistance = 0;
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraTween = null;

        spherical.radius = THREE.MathUtils.clamp(
          spherical.radius * Math.exp(event.deltaY * 0.001),
          4.8,
          18
        );

        updateCamera();
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", () => {
      tweenCamera({
        radius: 9.5,
        theta: 0.68,
        phi: 1.16,
        target: new THREE.Vector3(0, 1.55, 0)
      });
    });

    window.addEventListener("keydown", (event) => {
      if (event.target instanceof HTMLInputElement) return;

      cameraTween = null;

      if (event.key === "ArrowLeft") {
        spherical.theta -= 0.08;
      } else if (event.key === "ArrowRight") {
        spherical.theta += 0.08;
      } else if (event.key === "ArrowUp") {
        spherical.phi = Math.max(0.28, spherical.phi - 0.06);
      } else if (event.key === "ArrowDown") {
        spherical.phi = Math.min(1.46, spherical.phi + 0.06);
      } else if (event.key === "+" || event.key === "=") {
        spherical.radius = Math.max(4.8, spherical.radius - 0.45);
      } else if (event.key === "-" || event.key === "_") {
        spherical.radius = Math.min(18, spherical.radius + 0.45);
      } else {
        return;
      }

      updateCamera();
    });

    // -------------------------------------------------------------------------
    // Resize and render loop
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    function animate(time) {
      requestAnimationFrame(animate);

      if (cameraTween) {
        const elapsed = time - cameraTween.startTime;
        const t = THREE.MathUtils.clamp(
          elapsed / cameraTween.duration,
          0,
          1
        );
        const eased = 1 - Math.pow(1 - t, 3);

        spherical.radius = THREE.MathUtils.lerp(
          cameraTween.from.radius,
          cameraTween.to.radius,
          eased
        );

        spherical.phi = THREE.MathUtils.lerp(
          cameraTween.from.phi,
          cameraTween.to.phi,
          eased
        );

        const thetaDifference = shortestAngleDifference(
          cameraTween.from.theta,
          cameraTween.to.theta
        );

        spherical.theta =
          cameraTween.from.theta + thetaDifference * eased;

        cameraTarget.lerpVectors(
          cameraTween.from.target,
          cameraTween.to.target,
          eased
        );

        if (t >= 1) cameraTween = null;
      }

      updateCamera();
      renderer.render(scene, camera);
    }

    requestAnimationFrame(animate);
  </script>
</body>
