<body>
  <div id="loading">Building mechanism…</div>

  <div class="title-card">
    <div class="eyebrow">Interactive mechanical study</div>
    <h1>Chain-Driven Jackshaft</h1>
    <p class="subtitle">
      Roller-chain power transfer with a spring-loaded idler tensioner,
      pillow-block supports, and live synchronized rotation.
    </p>
  </div>

  <div class="controls">
    <div class="control-heading">Simulation controls</div>

    <div class="speed-row">
      <span>Chain speed</span>
      <span id="speedValue" class="speed-value">1.00×</span>
    </div>

    <input
      id="speed"
      type="range"
      min="0.15"
      max="2"
      step="0.05"
