      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset view</button>
      <button id="iso" class="active" type="button">Isometric</button>
      <button id="front" type="button">Chain view</button>
      <button id="toggleLabels" class="active" type="button">Labels on</button>
      <button id="resetSim" type="button">Reset motion</button>
    </div>
  </div>

  <div class="legend">
    <span class="legend-item">
      <i class="swatch"></i> Power source
    </span>
    <span class="legend-item">
      <i class="swatch blue"></i> Jackshaft
    </span>
    <span class="legend-item">
      <i class="swatch gray"></i> Tensioner
    </span>
  </div>

  <div class="hint">
    Drag: orbit · Wheel/pinch: zoom · Right-drag/Shift-drag: pan
  </div>

  <div id="labels">
    <div class="label" id="label-drive">Drive sprocket</div>
    <div class="label" id="label-shaft">Jackshaft</div>
    <div class="label" id="label-tensioner">Spring tensioner</div>
    <div class="label" id="label-bearing">Pillow-block bearing</div>
    <div class="label" id="label-output">Output coupling</div>
  </div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const loading = document.getElementById("loading");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x111820);
    scene.fog = new THREE.Fog(0x111820, 13, 31);

    const camera = new THREE.PerspectiveCamera(
      42,
      window.innerWidth / window.innerHeight,
      0.05,
      100
    );

    const ambient = new THREE.HemisphereLight(0xbdd8f4, 0x27303a, 2.1);
    scene.add(ambient);

    const keyLight = new THREE.DirectionalLight(0xffffff, 3.3);
    keyLight.position.set(5, 9, 6);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -8;
    keyLight.shadow.camera.right = 8;
    keyLight.shadow.camera.top = 8;
    keyLight.shadow.camera.bottom = -8;
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 25;
    keyLight.shadow.bias = -0.00035;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x65bfff, 2.2);
    rimLight.position.set(-6, 4, -5);
    scene.add(rimLight);

    const warmLight = new THREE.PointLight(0xffa13b, 22, 12, 2);
    warmLight.position.set(-1.5, 2.4, 3.2);
    scene.add(warmLight);

    // -------------------------------------------------------------------------
    // Materials
    // -------------------------------------------------------------------------

    const materials = {
      steel: new THREE.MeshStandardMaterial({
        color: 0x9ba7b3,
        metalness: 0.88,
        roughness: 0.26
      }),
      darkSteel: new THREE.MeshStandardMaterial({
        color: 0x303a45,
        metalness: 0.8,
        roughness: 0.3
      }),
      chain: new THREE.MeshStandardMaterial({
        color: 0x596675,
        metalness: 0.92,
        roughness: 0.24
      }),
      pin: new THREE.MeshStandardMaterial({
        color: 0xc3ccd4,
        metalness: 0.95,
        roughness: 0.2
      }),
      motor: new THREE.MeshStandardMaterial({
        color: 0x17688a,
        metalness: 0.58,
        roughness: 0.3
      }),
      bearing: new THREE.MeshStandardMaterial({
        color: 0x287c9d,
        metalness: 0.52,
        roughness: 0.33
      }),
      orange: new THREE.MeshStandardMaterial({
        color: 0xf49b32,
        metalness: 0.55,
        roughness: 0.28
      }),
      spring: new THREE.MeshStandardMaterial({
        color: 0xffa23f,
        metalness: 0.7,
        roughness: 0.23
      }),
      base: new THREE.MeshStandardMaterial({
        color: 0x252e37,
        metalness: 0.62,
        roughness: 0.42
      }),
      rubber: new THREE.MeshStandardMaterial({
        color: 0x15191e,
        metalness: 0.08,
        roughness: 0.86
      }),
      hole: new THREE.MeshStandardMaterial({
        color: 0x0b1015,
        metalness: 0.45,
        roughness: 0.55
      })
    };

    function addMesh(geometry, material, position, parent = scene) {
      const mesh = new THREE.Mesh(geometry, material);
      if (position) mesh.position.copy(position);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addBox(size, position, material, parent = scene) {
      return addMesh(
        new THREE.BoxGeometry(size.x, size.y, size.z),
        material,
        position,
        parent
      );
    }

    function addCylinder(radius, length, position, material, parent = scene, segments = 32) {
      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        segments
      );
      geometry.rotateZ(Math.PI / 2);
      return addMesh(geometry, material, position, parent);
    }

    // -------------------------------------------------------------------------
    // Floor and mounting rails
    // -------------------------------------------------------------------------

    const floor = addMesh(
      new THREE.PlaneGeometry(40, 30),
      new THREE.MeshStandardMaterial({
        color: 0x1b232c,
        metalness: 0.15,
        roughness: 0.88
      }),
      new THREE.Vector3(0, -0.12, 0)
    );
    floor.rotation.x = -Math.PI / 2;
    floor.castShadow = false;

    const grid = new THREE.GridHelper(30, 30, 0x6a7784, 0x35414d);
    grid.position.y = -0.105;
    grid.material.transparent = true;
    grid.material.opacity = 0.23;
    scene.add(grid);

    addBox(
      new THREE.Vector3(7.4, 0.12, 1.3),
      new THREE.Vector3(0, 0, -0.05),
      materials.base
    );

    // Two longitudinal rails under the machinery.
    for (const z of [-0.72, 0.68]) {
      addBox(
        new THREE.Vector3(7.2, 0.15, 0.2),
        new THREE.Vector3(0, 0.08, z),
        materials.darkSteel
      );
    }

    // -------------------------------------------------------------------------
    // Exact common-tangent chain path
    //
    // The 2D chain plane uses:
    //   x = world Z
    //   y = world Y
    // -------------------------------------------------------------------------

    const chainX = 0;

    const chainPitch = 0.17;

    function radiusForTeeth(teeth) {
      return chainPitch / (2 * Math.sin(Math.PI / teeth));
    }

    const circles = [
      {
        name: "drive",
        center: new THREE.Vector2(0, 0.72),
        radius: radiusForTeeth(26),
        teeth: 26
      },
      {
        name: "tensioner",
        center: new THREE.Vector2(0.86, 1.23),
        radius: radiusForTeeth(10),
        teeth: 10
      },
      {
        name: "jack",
        center: new THREE.Vector2(0, 2.25),
        radius: radiusForTeeth(20),
        teeth: 20
      }
    ];

    function buildChainPath(circleList) {
      const count = circleList.length;
      const edgeNormals = [];
      const edgePoints = [];

      // Circles are ordered counter-clockwise. For each edge, calculate the
      // common external tangent with an outward-facing normal.
      for (let i = 0; i < count; i++) {
        const a = circleList[i];
        const b = circleList[(i + 1) % count];

        const delta = b.center.clone().sub(a.center);
        const distance = delta.length();
        const u = delta.clone().normalize();
        const perpendicular = new THREE.Vector2(-u.y, u.x);

        const radiusDifference = b.radius - a.radius;
        const k = radiusDifference / distance;
        const h = Math.sqrt(Math.max(0, 1 - k * k));

        // Right-hand/outward normal for a counter-clockwise polygon.
        const normal = u.clone().multiplyScalar(-k)
          .addScaledVector(perpendicular, -h)
          .normalize();

        edgeNormals.push(normal);
        edgePoints.push({
          a: a.center.clone().addScaledVector(normal, a.radius),
          b: b.center.clone().addScaledVector(normal, b.radius)
        });
      }

      const segments = [];
      let totalLength = 0;

      for (let i = 0; i < count; i++) {
        const circle = circleList[i];
        const previousNormal = edgeNormals[(i - 1 + count) % count];
        const nextNormal = edgeNormals[i];

        const incomingAngle = Math.atan2(previousNormal.y, previousNormal.x);
        const outgoingAngle = Math.atan2(nextNormal.y, nextNormal.x);

        let sweep = outgoingAngle - incomingAngle;
        while (sweep < 0) sweep += Math.PI * 2;
        if (sweep < 0.0001) sweep += Math.PI * 2;

        const arcLength = circle.radius * sweep;

        segments.push({
          type: "arc",
          start: totalLength,
          length: arcLength,
          center: circle.center,
          radius: circle.radius,
          angle: incomingAngle,
          sweep
        });

        totalLength += arcLength;

        const lineStart = edgePoints[i].a;
        const lineEnd = edgePoints[i].b;
        const lineLength = lineStart.distanceTo(lineEnd);

        segments.push({
          type: "line",
          start: totalLength,
          length: lineLength,
          a: lineStart,
          b: lineEnd
        });

        totalLength += lineLength;
      }

      function pointAt(distance) {
        const s = ((distance % totalLength) + totalLength) % totalLength;
        const segment = segments.find(
          item => s >= item.start && s < item.start + item.length
        ) || segments[segments.length - 1];

        if (segment.type === "arc") {
          const t = (s - segment.start) / segment.length;
          const angle = segment.angle + segment.sweep * t;
          const point = new THREE.Vector2(
            segment.center.x + Math.cos(angle) * segment.radius,
            segment.center.y + Math.sin(angle) * segment.radius
          );
          const tangent = new THREE.Vector2(
            -Math.sin(angle),
            Math.cos(angle)
          );

          return {
            point: new THREE.Vector3(chainX, point.y, point.x),
            tangent: new THREE.Vector3(0, tangent.y, tangent.x)
          };
        }

        const t = (s - segment.start) / segment.length;
        const point2 = segment.a.clone().lerp(segment.b, t);
        const tangent2 = segment.b.clone().sub(segment.a).normalize();

        return {
          point: new THREE.Vector3(chainX, point2.y, point2.x),
          tangent: new THREE.Vector3(0, tangent2.y, tangent2.x)
        };
      }

      return {
        segments,
        totalLength,
        pointAt
      };
    }

    const chainPath = buildChainPath(circles);
    const linkCount = Math.round(chainPath.totalLength / chainPitch);
    const actualLinkSpacing = chainPath.totalLength / linkCount;

    // -------------------------------------------------------------------------
    // Sprocket construction
    // -------------------------------------------------------------------------

    function makeSprocket(radius, teeth, width, accentMaterial) {
      const group = new THREE.Group();

      const outerRadius = radius * 0.79;
      const innerRadius = Math.max(radius * 0.26, 0.105);

      const shape = new THREE.Shape();
      shape.absarc(0, 0, outerRadius, 0, Math.PI * 2, false);

      const hole = new THREE.Path();
      hole.absarc(0, 0, innerRadius, 0, Math.PI * 2, true);
      shape.holes.push(hole);

      const webGeometry = new THREE.ExtrudeGeometry(shape, {
        depth: width,
        bevelEnabled: true,
        bevelSegments: 2,
        bevelSize: 0.012,
        bevelThickness: 0.009,
        curveSegments: 64
      });

      // Shape XY becomes world ZY; extrusion becomes world X.
      webGeometry.rotateY(-Math.PI / 2);
      webGeometry.translate(width / 2, 0, 0);

      addMesh(webGeometry, materials.steel, null, group);

      addCylinder(
        Math.max(radius * 0.23, 0.13),
        width + 0.22,
        new THREE.Vector3(0, 0, 0),
        accentMaterial,
        group
      );

      // Faux recessed lightening holes on the visible face.
      const recessGeometry = new THREE.CylinderGeometry(
        Math.min(0.08, radius * 0.115),
        Math.min(0.08, radius * 0.115),
        0.018,
        24
      );
      recessGeometry.rotateZ(Math.PI / 2);

      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * Math.PI * 2;
        const r = radius * 0.51;

        addMesh(
          recessGeometry,
          materials.hole,
          new THREE.Vector3(
            width / 2 + 0.014,
            Math.sin(a) * r,
            Math.cos(a) * r
          ),
          group
        );
      }

      // Hub bolts.
      const boltGeometry = new THREE.CylinderGeometry(0.027, 0.027, 0.03, 6);
      boltGeometry.rotateZ(Math.PI / 2);

      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
        const r = Math.max(radius * 0.17, 0.095);

        addMesh(
          boltGeometry,
          materials.pin,
          new THREE.Vector3(
            width / 2 + 0.13,
            Math.sin(a) * r,
            Math.cos(a) * r
          ),
          group
        );
      }

      const tangentialWidth = Math.max(
        0.065,
        (Math.PI * 2 * radius / teeth) * 0.54
      );

      const toothGeometry = new THREE.BoxGeometry(
        width * 1.06,
        tangentialWidth,
        0.12
      );

      for (let i = 0; i < teeth; i++) {
        const a = (i / teeth) * Math.PI * 2;
        const tooth = addMesh(
          toothGeometry,
          materials.steel,
          new THREE.Vector3(
            0,
            Math.sin(a) * (radius - 0.012),
            Math.cos(a) * (radius - 0.012)
          ),
          group
        );
        tooth.rotation.x = -a;
      }

      return group;
    }

    // -------------------------------------------------------------------------
    // Drive motor and drive sprocket
    // -------------------------------------------------------------------------

    const driveCircle = circles[0];

    addBox(
      new THREE.Vector3(1.8, 0.14, 1.15),
      new THREE.Vector3(-0.9, 0.08, 0),
      materials.base
    );

    for (const x of [-1.45, -0.35]) {
      addBox(
        new THREE.Vector3(0.24, 0.32, 0.72),
        new THREE.Vector3(x, 0.29, 0),
        materials.motor
      );
    }

    addCylinder(
      0.47,
      1.55,
      new THREE.Vector3(-0.93, driveCircle.center.y, 0),
      materials.motor
    );

    const motorEndGeometry = new THREE.CylinderGeometry(0.49, 0.49, 0.12, 48);
    motorEndGeometry.rotateZ(Math.PI / 2);

    addMesh(
      motorEndGeometry,
      materials.darkSteel,
      new THREE.Vector3(-1.75, driveCircle.center.y, 0)
    );

    // Cooling fins.
    for (let i = 0; i < 8; i++) {
      const x = -1.58 + i * 0.19;
      const fin = addMesh(
        new THREE.TorusGeometry(0.47, 0.025, 8, 40),
        materials.darkSteel,
        new THREE.Vector3(x, driveCircle.center.y, 0)
      );
      fin.rotation.y = Math.PI / 2;
    }

    addBox(
      new THREE.Vector3(0.47, 0.24, 0.55),
      new THREE.Vector3(-0.92, 1.22, 0),
      materials.motor
    );

    const driveRotor = new THREE.Group();
    driveRotor.position.set(
      chainX,
      driveCircle.center.y,
      driveCircle.center.x
    );
    scene.add(driveRotor);

    addCylinder(
      0.12,
      0.75,
      new THREE.Vector3(-0.28, 0, 0),
      materials.steel,
      driveRotor
    );

    const driveSprocket = makeSprocket(
      driveCircle.radius,
      driveCircle.teeth,
      0.17,
      materials.orange
    );
    driveRotor.add(driveSprocket);

    // -------------------------------------------------------------------------
    // Main jackshaft
    // -------------------------------------------------------------------------

    const jackCircle = circles[2];
    const shaftY = jackCircle.center.y;

    const mainRotor = new THREE.Group();
    mainRotor.position.y = shaftY;
    scene.add(mainRotor);

    addCylinder(
      0.135,
      6.5,
      new THREE.Vector3(0, 0, 0),
      materials.steel,
      mainRotor,
      40
    );

    // A longitudinal key makes shaft rotation easier to perceive.
    addBox(
      new THREE.Vector3(6.2, 0.028, 0.055),
      new THREE.Vector3(0, 0.137, 0),
      materials.orange,
      mainRotor
    );

    const jackSprocket = makeSprocket(
      jackCircle.radius,
      jackCircle.teeth,
      0.18,
      materials.bearing
    );
    jackSprocket.position.x = chainX;
    mainRotor.add(jackSprocket);

    // Shaft collars.
    for (const x of [-2.6, -0.85, 1.15, 2.65]) {
      addCylinder(
        0.205,
        0.13,
        new THREE.Vector3(x, 0, 0),
        materials.darkSteel,
        mainRotor
      );
    }

    // Output coupling and visible bolt circle.
    addCylinder(
      0.39,
      0.28,
      new THREE.Vector3(3.08, 0, 0),
      materials.steel,
      mainRotor,
      48
    );

    const couplingBoltGeometry = new THREE.CylinderGeometry(
      0.047,
      0.047,
      0.045,
      6
    );
    couplingBoltGeometry.rotateZ(Math.PI / 2);

    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      addMesh(
        couplingBoltGeometry,
        materials.orange,
        new THREE.Vector3(
          3.235,
          Math.sin(a) * 0.275,
          Math.cos(a) * 0.275
        ),
        mainRotor
      );
    }

    // -------------------------------------------------------------------------
    // Pillow-block bearings and support pedestals
    // -------------------------------------------------------------------------

    function makeBearing(x) {
      addBox(
        new THREE.Vector3(0.92, 0.14, 1.08),
        new THREE.Vector3(x, 0.16, -0.14),
        materials.base
      );

      addBox(
        new THREE.Vector3(0.42, 1.82, 0.42),
        new THREE.Vector3(x, 1.08, -0.42),
        materials.base
      );

      const housing = addMesh(
        new THREE.TorusGeometry(0.235, 0.075, 14, 44),
        materials.bearing,
        new THREE.Vector3(x, shaftY, 0)
      );
      housing.rotation.y = Math.PI / 2;

      const innerRace = addMesh(
        new THREE.TorusGeometry(0.16, 0.027, 10, 40),
        materials.darkSteel,
        new THREE.Vector3(x, shaftY, 0)
      );
      innerRace.rotation.y = Math.PI / 2;

      // Small cap bolts.
      for (const z of [-0.26, 0.26]) {
        addCylinder(
          0.045,
          0.5,
          new THREE.Vector3(x, shaftY + 0.02, z),
          materials.steel
        );
      }
    }

    makeBearing(-1.65);
    makeBearing(1.65);

    // -------------------------------------------------------------------------
    // Spring-loaded tensioner
    // -------------------------------------------------------------------------

    const tensionerCircle = circles[1];
    const tensionerPosition = new THREE.Vector3(
      chainX,
      tensionerCircle.center.y,
      tensionerCircle.center.x
    );

    const tensionerRotor = new THREE.Group();
    tensionerRotor.position.copy(tensionerPosition);
    scene.add(tensionerRotor);

    const idlerSprocket = makeSprocket(
      tensionerCircle.radius,
      tensionerCircle.teeth,
      0.16,
      materials.darkSteel
    );
    tensionerRotor.add(idlerSprocket);

    // Idler axle extends behind the chain plane to the pivot arm.
    addCylinder(
      0.07,
      0.48,
      new THREE.Vector3(0.15, 0, 0),
      materials.steel
    );

    const pivot = new THREE.Vector3(0.25, 0.38, 1.55);
    const armEnd = new THREE.Vector3(
      0.25,
      tensionerCircle.center.y,
      tensionerCircle.center.x
    );

    const armDirection = armEnd.clone().sub(pivot);
    const armLength = armDirection.length();
    armDirection.normalize();

    const arm = addBox(
      new THREE.Vector3(0.12, armLength, 0.18),
      pivot.clone().add(armEnd).multiplyScalar(0.5),
      materials.darkSteel
    );
    arm.quaternion.setFromUnitVectors(
      new THREE.Vector3(0, 1, 0),
      armDirection
    );

    addCylinder(
      0.16,
      0.24,
      pivot,
      materials.steel
    );

    // Tensioner support.
    addBox(
      new THREE.Vector3(0.72, 0.14, 0.68),
      new THREE.Vector3(0.25, 0.15, 1.57),
      materials.base
    );

    addBox(
      new THREE.Vector3(0.18, 0.36, 0.25),
      new THREE.Vector3(0.25, 0.31, 1.57),
      materials.base
    );

    // Helical extension spring.
    const springStart = new THREE.Vector3(0.25, 0.34, 1.88);
    const springEnd = new THREE.Vector3(0.25, 0.97, 1.22);
    const springAxis = springEnd.clone().sub(springStart);
    const springLength = springAxis.length();
    springAxis.normalize();

    const springU = new THREE.Vector3(1, 0, 0);
    const springV = new THREE.Vector3()
      .crossVectors(springAxis, springU)
      .normalize();

    const springPoints = [];
    const springTurns = 10;
    const springSegments = 180;

    for (let i = 0; i <= springSegments; i++) {
      const t = i / springSegments;
      const a = t * Math.PI * 2 * springTurns;
      const center = springStart.clone()
        .addScaledVector(springAxis, springLength * t);

      const radial = springU.clone().multiplyScalar(Math.cos(a))
        .addScaledVector(springV, Math.sin(a))
        .multiplyScalar(0.075);

      springPoints.push(center.add(radial));
    }

    const springCurve = new THREE.CatmullRomCurve3(springPoints);
    addMesh(
      new THREE.TubeGeometry(springCurve, 180, 0.016, 6, false),
      materials.spring
    );

    addCylinder(
      0.055,
      0.2,
      springStart,
      materials.steel
    );

    // -------------------------------------------------------------------------
    // Instanced roller chain
    // -------------------------------------------------------------------------

    const rollerGeometry = new THREE.CylinderGeometry(
      0.046,
      0.046,
      0.155,
      14
    );
    rollerGeometry.rotateZ(Math.PI / 2);

    const pinGeometry = new THREE.CylinderGeometry(
      0.021,
      0.021,
      0.24,
      10
    );
    pinGeometry.rotateZ(Math.PI / 2);

    const plateGeometry = new THREE.BoxGeometry(1, 0.09, 0.026);

    const rollerMesh = new THREE.InstancedMesh(
      rollerGeometry,
      materials.chain,
      linkCount
    );
    const pinMesh = new THREE.InstancedMesh(
      pinGeometry,
      materials.pin,
      linkCount
    );

    const outerLinkCount = Math.ceil(linkCount / 2);
    const innerLinkCount = Math.floor(linkCount / 2);

    const outerPlateMesh = new THREE.InstancedMesh(
      plateGeometry,
      materials.darkSteel,
      outerLinkCount * 2
    );

    const innerPlateMesh = new THREE.InstancedMesh(
      plateGeometry,
      materials.steel,
      innerLinkCount * 2
    );

    for (const mesh of [
      rollerMesh,
      pinMesh,
      outerPlateMesh,
      innerPlateMesh
    ]) {
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.frustumCulled = false;
      scene.add(mesh);
    }

    const dummy = new THREE.Object3D();
    const worldX = new THREE.Vector3(1, 0, 0);
    const basis = new THREE.Matrix4();
    const plateQuaternion = new THREE.Quaternion();

    let chainTravel = 0;
    let lastChainTravel = 0;

    function updateChain() {
      const nodes = [];

      for (let i = 0; i <= linkCount; i++) {
        nodes.push(
          chainPath.pointAt(
            chainTravel + i * actualLinkSpacing
          )
        );
      }

      for (let i = 0; i < linkCount; i++) {
        const current = nodes[i];
        const next = nodes[i + 1];

        dummy.position.copy(current.point);
        dummy.quaternion.identity();
        dummy.scale.set(1, 1, 1);
        dummy.updateMatrix();
        rollerMesh.setMatrixAt(i, dummy.matrix);

        dummy.position.copy(current.point);
        dummy.updateMatrix();
        pinMesh.setMatrixAt(i, dummy.matrix);

        const direction = next.point.clone().sub(current.point).normalize();
        const side = new THREE.Vector3(
          0,
          -direction.z,
          direction.y
        ).normalize();

        // Local X follows the link, local Y is plate width in the chain plane,
        // and local Z is the axial plate thickness.
        basis.makeBasis(direction, side, worldX);
        plateQuaternion.setFromRotationMatrix(basis);

        const midpoint = current.point.clone().add(next.point).multiplyScalar(0.5);
        const length = current.point.distanceTo(next.point);

        const isOuter = i % 2 === 0;
        const plateOffset = isOuter ? 0.105 : 0.074;
        const targetMesh = isOuter ? outerPlateMesh : innerPlateMesh;
        const localIndex = isOuter
          ? Math.floor(i / 2)
          : Math.floor((i - 1) / 2);

        for (const sideSign of [-1, 1]) {
          dummy.position.copy(midpoint);
          dummy.position.x += sideSign * plateOffset;
          dummy.quaternion.copy(plateQuaternion);
          dummy.scale.set(length, 1, 1);
          dummy.updateMatrix();

          targetMesh.setMatrixAt(
            localIndex * 2 + (sideSign > 0 ? 1 : 0),
            dummy.matrix
          );
        }
      }

      rollerMesh.instanceMatrix.needsUpdate = true;
      pinMesh.instanceMatrix.needsUpdate = true;
      outerPlateMesh.instanceMatrix.needsUpdate = true;
      innerPlateMesh.instanceMatrix.needsUpdate = true;
    }

    // -------------------------------------------------------------------------
    // Custom orbit/pan/zoom camera controls
    // -------------------------------------------------------------------------

    const orbit = {
      target: new THREE.Vector3(0, 1.35, 0.15),
      radius: 9.2,
      theta: 0.88,
      phi: 1.08
    };

    function updateCamera() {
      const sinPhi = Math.sin(orbit.phi);

      camera.position.set(
        orbit.target.x + orbit.radius * sinPhi * Math.cos(orbit.theta),
        orbit.target.y + orbit.radius * Math.cos(orbit.phi),
        orbit.target.z + orbit.radius * sinPhi * Math.sin(orbit.theta)
      );

      camera.lookAt(orbit.target);
    }

    updateCamera();

    function setView(view) {
      if (view === "front") {
        orbit.target.set(0, 1.35, 0.25);
        orbit.radius = 7.8;
        orbit.theta = 0.02;
        orbit.phi = 1.39;
      } else {
        orbit.target.set(0, 1.35, 0.15);
        orbit.radius = 9.2;
        orbit.theta = 0.88;
        orbit.phi = 1.08;
      }

      updateCamera();
    }

    const canvas = renderer.domElement;
    const pointers = new Map();
    let pinchDistance = 0;

    canvas.addEventListener("contextmenu", event => event.preventDefault());

    canvas.addEventListener("pointerdown", event => {
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 2) {
        const points = [...pointers.values()];
        pinchDistance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );
      }
    });

    canvas.addEventListener("pointermove", event => {
      if (!pointers.has(event.pointerId)) return;

      const previous = pointers.get(event.pointerId);
      const dx = event.clientX - previous.x;
      const dy = event.clientY - previous.y;

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        const pan = event.button === 2 || event.shiftKey;

        if (pan) {
          const right = new THREE.Vector3()
            .setFromMatrixColumn(camera.matrix, 0);
          const up = new THREE.Vector3()
            .setFromMatrixColumn(camera.matrix, 1);

          orbit.target.addScaledVector(
            right,
            -dx * orbit.radius * 0.0014
          );
          orbit.target.addScaledVector(
            up,
            dy * orbit.radius * 0.0014
          );
        } else {
          orbit.theta -= dx * 0.006;
          orbit.phi = THREE.MathUtils.clamp(
            orbit.phi - dy * 0.005,
            0.24,
            1.46
          );
        }

        updateCamera();
      } else if (pointers.size === 2) {
        const points = [...pointers.values()];
        const distance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );

        if (pinchDistance > 0 && distance > 0) {
          orbit.radius = THREE.MathUtils.clamp(
            orbit.radius * (pinchDistance / distance),
            3.6,
            18
          );
          updateCamera();
        }

        pinchDistance = distance;
      }
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);
      pinchDistance = 0;
    }

    canvas.addEventListener("pointerup", releasePointer);
    canvas.addEventListener("pointercancel", releasePointer);

    canvas.addEventListener("wheel", event => {
      event.preventDefault();
      orbit.radius = THREE.MathUtils.clamp(
        orbit.radius * Math.exp(event.deltaY * 0.001),
        3.6,
        18
      );
      updateCamera();
    }, { passive: false });

    // -------------------------------------------------------------------------
    // Labels
    // -------------------------------------------------------------------------

    const labelDefinitions = [
      {
        element: document.getElementById("label-drive"),
        position: new THREE.Vector3(-0.1, 0.62, 0.15)
      },
      {
        element: document.getElementById("label-shaft"),
        position: new THREE.Vector3(1.75, 2.57, 0)
      },
      {
        element: document.getElementById("label-tensioner"),
        position: new THREE.Vector3(0.86, 1.55, 0.86)
      },
      {
        element: document.getElementById("label-bearing"),
        position: new THREE.Vector3(-1.65, 2.46, 0)
      },
      {
        element: document.getElementById("label-output"),
        position: new THREE.Vector3(3.18, 2.62, 0)
      }
    ];

    let labelsVisible = true;

    function updateLabels() {
      const width = window.innerWidth;
      const height = window.innerHeight;

      for (const definition of labelDefinitions) {
        const projected = definition.position.clone().project(camera);
        const visible =
          labelsVisible &&
          projected.z > -1 &&
          projected.z < 1 &&
          projected.x > -1.08 &&
          projected.x < 1.08 &&
          projected.y > -1.08 &&
          projected.y < 1.08;

        definition.element.style.opacity = visible ? "1" : "0";
        definition.element.style.left =
          `${(projected.x * 0.5 + 0.5) * width}px`;
        definition.element.style.top =
          `${(-projected.y * 0.5 + 0.5) * height}px`;
      }
    }

    // -------------------------------------------------------------------------
    // UI
    // -------------------------------------------------------------------------

    let paused = false;
    let speedScale = 1;

    const speedInput = document.getElementById("speed");
    const speedValue = document.getElementById("speedValue");
    const pauseButton = document.getElementById("pause");
    const labelsButton = document.getElementById("toggleLabels");
    const isoButton = document.getElementById("iso");
    const frontButton = document.getElementById("front");

    speedInput.addEventListener("input", () => {
      speedScale = Number(speedInput.value);
      speedValue.textContent = `${speedScale.toFixed(2)}×`;
    });

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
      pauseButton.classList.toggle("active", paused);
    });

    document.getElementById("reset").addEventListener("click", () => {
      setView("iso");
    });

    document.getElementById("resetSim").addEventListener("click", () => {
      chainTravel = 0;
      lastChainTravel = 0;
      updateChain();
    });

    isoButton.addEventListener("click", () => {
      setView("iso");
      isoButton.classList.add("active");
      frontButton.classList.remove("active");
    });

    frontButton.addEventListener("click", () => {
      setView("front");
      frontButton.classList.add("active");
      isoButton.classList.remove("active");
    });

    labelsButton.addEventListener("click", () => {
      labelsVisible = !labelsVisible;
      labelsButton.textContent = labelsVisible ? "Labels on" : "Labels off";
      labelsButton.classList.toggle("active", labelsVisible);
    });

    // -------------------------------------------------------------------------
    // Resize and animation
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    const clock = new THREE.Clock();

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);

      if (!paused) {
        chainTravel += delta * 0.62 * speedScale;
      }

      // The chain path is counter-clockwise in the Z/Y plane. A negative
      // world-X rotation therefore produces the correct sprocket direction.
      driveRotor.rotation.x = -chainTravel / driveCircle.radius;
      mainRotor.rotation.x = -chainTravel / jackCircle.radius;
      tensionerRotor.rotation.x = -chainTravel / tensionerCircle.radius;

      if (Math.abs(chainTravel - lastChainTravel) > 0.00001) {
        updateChain();
        lastChainTravel = chainTravel;
      }

      updateLabels();
      renderer.render(scene, camera);
    }

    updateChain();
    updateLabels();
    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
      setTimeout(() => loading.remove(), 400);
    });
  </script>
</body>
</html>
