    renderer.toneMappingExposure = 1.08;

    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional banyan tree with eight aerial root pillars"
    );

    sceneHost.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xb9d1c3);
    scene.fog = new THREE.Fog(0xb9d1c3, 23, 65);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      140
    );

    const hemisphere = new THREE.HemisphereLight(
      0xe7f3ff,
      0x35452b,
      1.7
    );
    scene.add(hemisphere);

    const sunLight = new THREE.DirectionalLight(0xffeac2, 3.25);
    sunLight.position.set(11, 18, 9);
    sunLight.castShadow = true;
    sunLight.shadow.mapSize.set(2048, 2048);
    sunLight.shadow.camera.left = -14;
    sunLight.shadow.camera.right = 14;
