    function box(w, h, d, material, x = 0, y = 0, z = 0, parent = scene) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(w, h, d),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function cylinderBetween(a, b, radius, material, parent = scene, segments = 8) {
      const direction = new THREE.Vector3().subVectors(b, a);
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radius, radius, direction.length(), segments),
        material
      );
      mesh.position.copy(a).add(b).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.clone().normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function makeLabelTexture(
      title,
      subtitle = "",
      background = "#102334",
      foreground = "#ecf8ff",
      accent = "#64e3ff"
    ) {
      const canvas = document.createElement("canvas");
      canvas.width = 1024;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = background;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = accent;
      ctx.fillRect(0, 0, 20, canvas.height);
      ctx.fillRect(36, 28, 8, 200);

      ctx.fillStyle = foreground;
      ctx.font = "700 70px system-ui, sans-serif";
      ctx.fillText(title, 72, 112);

      if (subtitle) {
        ctx.fillStyle = "#9db8c9";
        ctx.font = "500 31px system-ui, sans-serif";
        ctx.fillText(subtitle, 74, 174);
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function labelPlane(texture, w, h, x, y, z, parent = scene) {
