    function facadeTexture(base, windowColor, litColor) {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 512;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = base;
      ctx.fillRect(0, 0, 256, 512);

      for (let y = 35; y < 490; y += 58) {
