    function makeRibbonGeometry(curve, width, top, bottom, segments = 90) {
      const positions = [];
      const indices = [];
      const side = new THREE.Vector3();

      for (let i = 0; i <= segments; i++) {
        const u = i / segments;
        const p = curve.getPointAt(u);
        const tangent = curve.getTangentAt(u);
        side.set(-tangent.z, 0, tangent.x).normalize();

        const left = p.clone().addScaledVector(side, width / 2);
        const right = p.clone().addScaledVector(side, -width / 2);

        positions.push(
          left.x, top, left.z,
          right.x, top, right.z,
          right.x, bottom, right.z,
          left.x, bottom, left.z
        );

        if (i < segments) {
          const a = i * 4;
          const b = (i + 1) * 4;

          // Top
          indices.push(a, b, a + 1, a + 1, b, b + 1);
          // Outer right
          indices.push(a + 1, b + 1, a + 2, a + 2, b + 1, b + 2);
          // Bottom
          indices.push(a + 2, b + 2, a + 3, a + 3, b + 2, b + 3);
          // Outer left
          indices.push(a + 3, b + 3, a, a, b + 3, b);
        }
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(positions, 3)
      );
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      return geometry;
    }

    function offsetCurvePoints(curve, offset, y) {
      const points = [];
      const side = new THREE.Vector3();

      for (let i = 0; i <= 100; i++) {
        const p = curve.getPointAt(i / 100);
        const tangent = curve.getTangentAt(i / 100);
        side.set(-tangent.z, 0, tangent.x).normalize();
        const q = p.clone().addScaledVector(side, offset);
        q.y = y;
        points.push(q);
      }

      return new THREE.CatmullRomCurve3(points);
    }

    const branchACurve = new THREE.CubicBezierCurve3(
      new THREE.Vector3(-66, 8, 6),
      new THREE.Vector3(-30, 8, 6),
      new THREE.Vector3(20, 8, 42),
      new THREE.Vector3(76, 8, 42)
    );

    const branchBCurve = new THREE.CubicBezierCurve3(
      new THREE.Vector3(66, 8, -6),
      new THREE.Vector3(30, 8, -6),
      new THREE.Vector3(-20, 8, -42),
      new THREE.Vector3(-76, 8, -42)
    );

    function buildFlyover(curve) {
      const deckMaterial = mat.concrete.clone();
      deckMaterial.side = THREE.DoubleSide;

      const deck = new THREE.Mesh(
        makeRibbonGeometry(curve, 4.5, 8.0, 6.9),
        deckMaterial
      );
      deck.castShadow = true;
      deck.receiveShadow = true;
      scene.add(deck);

      const bed = new THREE.Mesh(
        makeRibbonGeometry(curve, 2.7, 8.07, 7.99),
        new THREE.MeshStandardMaterial({
          color: 0x4c5559,
          roughness: 1,
          side: THREE.DoubleSide
        })
      );
      bed.receiveShadow = true;
      scene.add(bed);

      for (const offset of [-0.73, 0.73]) {
        const railCurve = offsetCurvePoints(curve, offset, RAIL_Y);
        const rail = new THREE.Mesh(
          new THREE.TubeGeometry(railCurve, 150, 0.065, 6, false),
          mat.rail
        );
        rail.castShadow = true;
        scene.add(rail);
      }

      const branchSleepers = new THREE.InstancedMesh(
        new THREE.BoxGeometry(0.25, 0.15, 2.18),
        mat.sleeper,
        130
      );

      const dummy = new THREE.Object3D();
      for (let i = 0; i < 130; i++) {
        const u = i / 129;
        const p = curve.getPointAt(u);
        const tangent = curve.getTangentAt(u);

        dummy.position.set(p.x, 8.18, p.z);
        dummy.rotation.set(0, -Math.atan2(tangent.z, tangent.x), 0);
        dummy.updateMatrix();
        branchSleepers.setMatrixAt(i, dummy.matrix);
