      branchSleepers.instanceMatrix.needsUpdate = true;
      scene.add(branchSleepers);

      // Flyover piers.
      for (let i = 2; i < 18; i++) {
        const u = i / 19;
        const p = curve.getPointAt(u);
        const tangent = curve.getTangentAt(u);
        const rotation = -Math.atan2(tangent.z, tangent.x);

        const column = box(
          1.35, 6.75, 1.45,
          mat.concrete,
          p.x, 3.38, p.z
        );
        column.rotation.y = rotation;

        const cap = box(
          1.8, 0.7, 4.0,
          mat.concreteDark,
          p.x, 6.62, p.z
        );
        cap.rotation.y = rotation;

        box(
          2.2, 0.35, 2.2,
          mat.concreteDark,
          p.x, 0.12, p.z
