      // Junction point machine and warning marker.
      const start = curve.getPointAt(0.02);
      const startTangent = curve.getTangentAt(0.02);
      const machine = box(
        1.6, 0.55, 0.8,
        mat.yellow,
        start.x + Math.cos(-Math.atan2(startTangent.z, startTangent.x)) * 2.1,
