        start.z - Math.sin(-Math.atan2(startTangent.z, startTangent.x)) * 2.1
      );
      machine.rotation.y = -Math.atan2(startTangent.z, startTangent.x);
    }

    buildFlyover(branchACurve);
    buildFlyover(branchBCurve);

    // ---------------------------------------------------------------------
    // Station platforms, canopies, lighting, and signs
    // ---------------------------------------------------------------------

    const PLATFORM_TOP = 8.45;

    for (const side of [-1, 1]) {
