        );

        cylinderBetween(
          new THREE.Vector3(x, PLATFORM_TOP + 2.2, side * 8.55),
          new THREE.Vector3(x, 12.25, side * 8.55),
          0.055,
          mat.steel
        );
      }

      // Gently curved translucent canopy roof.
      const roofPositions = [];
      const roofIndices = [];
      const roofSegments = 14;
      const roofHalfWidth = 1.85;
      const roofCenterZ = side * 8.55;

      for (let i = 0; i <= roofSegments; i++) {
        const t = i / roofSegments;
        const localZ = (t - 0.5) * roofHalfWidth * 2;
        const normalized = localZ / roofHalfWidth;
        const y = 12.35 + 0.72 * (1 - normalized * normalized);

        roofPositions.push(
          -25, y, roofCenterZ + localZ,
           25, y, roofCenterZ + localZ
        );

        if (i < roofSegments) {
          const a = i * 2;
          const b = (i + 1) * 2;
          roofIndices.push(a, b, a + 1, a + 1, b, b + 1);
        }
      }

      const roofGeometry = new THREE.BufferGeometry();
      roofGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(roofPositions, 3)
      );
      roofGeometry.setIndex(roofIndices);
