      const roof = new THREE.Mesh(roofGeometry, mat.roofGlass);
      roof.castShadow = true;
      scene.add(roof);

      // Longitudinal canopy ribs.
      for (const offset of [-1.45, -0.75, 0, 0.75, 1.45]) {
        const normalized = offset / roofHalfWidth;
        const y = 12.35 + 0.72 * (1 - normalized * normalized);
        cylinderBetween(
          new THREE.Vector3(-25, y, roofCenterZ + offset),
          new THREE.Vector3(25, y, roofCenterZ + offset),
          0.035,
          mat.steel
        );
      }

      // Benches.
      for (const x of [-14, 14]) {
        box(3.2, 0.16, 0.7, mat.trunk, x, PLATFORM_TOP + 0.5, side * 8.6);
        box(3.2, 0.65, 0.12, mat.trunk, x, PLATFORM_TOP + 0.9, side * 8.9);
        for (const bx of [-1.25, 1.25]) {
          box(0.12, 0.5, 0.5, mat.darkSteel, x + bx, PLATFORM_TOP + 0.25, side * 8.6);
        }
      }

      // Warm platform lamps.
      for (const x of [-20, -10, 0, 10, 20]) {
        const lampMaterial = new THREE.MeshStandardMaterial({
          color: 0xffe8bd,
          emissive: 0xffc96b,
          emissiveIntensity: 1.15
        });

        cylinderBetween(
          new THREE.Vector3(x, PLATFORM_TOP, side * 9.25),
          new THREE.Vector3(x, 11.85, side * 9.25),
