          mat.darkSteel
        );

        box(
          0.8, 0.08, 0.18,
          lampMaterial,
          x, 11.82,
          side * 9.08
        );
      }
    }

    // ---------------------------------------------------------------------
    // Stairs from platform to street
    // ---------------------------------------------------------------------

    function buildStair(side, x) {
      const steps = 28;
      const rise = PLATFORM_TOP / steps;
      const run = 0.47;
      const startZ = side * 10.05;
      const stairWidth = 2.45;

      for (let i = 0; i < steps; i++) {
        const topY = PLATFORM_TOP - i * rise;
        const z = startZ + side * (i + 0.5) * run;

        box(
          stairWidth, 0.12, run + 0.03,
          mat.platform,
          x, topY - 0.06, z
        );

        box(
          stairWidth, rise, 0.08,
          mat.concreteDark,
          x, topY - rise / 2,
          startZ + side * i * run
        );
      }

      const endZ = startZ + side * steps * run;

      for (const edge of [-1, 1]) {
        const edgeX = x + edge * (stairWidth / 2 + 0.12);

        cylinderBetween(
          new THREE.Vector3(edgeX, PLATFORM_TOP - 0.05, startZ),
          new THREE.Vector3(edgeX, 0.25, endZ),
          0.11,
          mat.darkSteel
        );

        cylinderBetween(
          new THREE.Vector3(edgeX, PLATFORM_TOP + 1.0, startZ),
          new THREE.Vector3(edgeX, 1.0, endZ),
          0.045,
          mat.steel
        );

        for (let i = 0; i <= steps; i += 4) {
          const t = i / steps;
          const px = edgeX;
          const py = PLATFORM_TOP - t * PLATFORM_TOP;
          const pz = startZ + side * t * steps * run;

          cylinderBetween(
            new THREE.Vector3(px, py, pz),
            new THREE.Vector3(px, py + 1.0, pz),
            0.035,
            mat.steel
          );
        }
      }

      // Small station entrance at street level.
      box(
        3.8, 0.18, 2.4,
        mat.concreteDark,
        x, 0.12,
        endZ + side * 0.65
      );
    }

    buildStair(1, -16);
    buildStair(-1, 16);

    // ---------------------------------------------------------------------
    // Glass lifts
    // ---------------------------------------------------------------------

    const lifts = [];

    function buildLift(x, z, phase) {
      const shaft = box(
        2.45, 10.4, 2.35,
        mat.glass,
        x, 5.2, z
      );
      shaft.castShadow = false;

      for (const dx of [-1.2, 1.2]) {
        for (const dz of [-1.15, 1.15]) {
          box(
            0.13, 10.7, 0.13,
            mat.steel,
            x + dx, 5.35, z + dz
          );
        }
      }

      box(2.8, 0.22, 2.7, mat.darkSteel, x, 10.65, z);
      box(2.8, 0.18, 2.7, mat.concreteDark, x, 0.08, z);

      const cab = new THREE.Group();
      const cabBody = box(
        1.85, 2.0, 1.75,
        mat.glass,
        0, 0, 0,
        cab
      );
      cabBody.castShadow = false;

      box(1.95, 0.13, 1.85, mat.steel, 0, 1.02, 0, cab);
      box(1.95, 0.12, 1.85, mat.steel, 0, -1.02, 0, cab);

      cab.position.set(x, 1.1, z);
      scene.add(cab);

      // Short bridge to platform.
      const bridgeZ = z > 0 ? z - 1.55 : z + 1.55;
      box(
        2.0, 0.18, 1.2,
        mat.steel,
        x, PLATFORM_TOP - 0.05,
        bridgeZ
      );

      lifts.push({ cab, phase });
    }

    buildLift(8, 10.25, 0);
    buildLift(8, -10.25, 0.5);

    // ---------------------------------------------------------------------
    // Platform passengers
    // ---------------------------------------------------------------------

    const passengers = [];

    function addPassenger(x, z, side, phase) {
      const group = new THREE.Group();

      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(0.13, 0.18, 0.62, 7),
