    // ---------------------------------------------------------------------
    // Signal gantries and dynamic route boards
    // ---------------------------------------------------------------------

    const gantries = [];

    function makeRouteBoardTexture(
      title,
      subtitle,
      accent,
      number
    ) {
      const canvas = document.createElement("canvas");
      canvas.width = 1024;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#0b1722";
      ctx.fillRect(0, 0, 1024, 256);

      ctx.fillStyle = accent;
      ctx.fillRect(0, 0, 18, 256);

      ctx.strokeStyle = accent;
      ctx.lineWidth = 5;
      ctx.strokeRect(32, 24, 960, 208);

      ctx.fillStyle = accent;
      ctx.font = "800 31px system-ui, sans-serif";
      ctx.fillText(`ROUTE CHANGE  ${String(number).padStart(2, "0")}`, 63, 76);

      ctx.fillStyle = "#f4fbff";
      ctx.font = "800 67px system-ui, sans-serif";
      ctx.fillText(title, 61, 151);

      ctx.fillStyle = "#a9c2d2";
      ctx.font = "500 29px system-ui, sans-serif";
      ctx.fillText(subtitle, 63, 202);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function buildGantry(x, name) {
      const group = new THREE.Group();

      for (const z of [-10.8, 10.8]) {
        box(
          0.48, 6.3, 0.48,
          mat.darkSteel,
          x, 11.1, z,
          group
        );
        box(
          0.9, 0.3, 0.9,
          mat.concrete,
          x, 8.1, z,
          group
        );
      }

      box(
        0.58, 0.58, 22.1,
        mat.darkSteel,
        x, 14.18, 0,
        group
      );

      // Diagonal braces.
      cylinderBetween(
        new THREE.Vector3(x, 12.6, -10.8),
        new THREE.Vector3(x, 14.0, -8.3),
        0.09,
        mat.steel,
        group
      );

      cylinderBetween(
        new THREE.Vector3(x, 12.6, 10.8),
        new THREE.Vector3(x, 14.0, 8.3),
        0.09,
        mat.steel,
        group
      );

      const signals = [];

      for (const z of trackZ) {
        const signal = new THREE.Group();
        signal.position.set(x + 0.2, 12.45, z);

        box(0.4, 1.12, 0.48, mat.black, 0, 0, 0, signal);

        const red = new THREE.MeshStandardMaterial({
          color: 0x3b0808,
          emissive: 0x000000,
          emissiveIntensity: 0
        });
        const yellow = new THREE.MeshStandardMaterial({
          color: 0x493807,
          emissive: 0x000000,
          emissiveIntensity: 0
        });
        const green = new THREE.MeshStandardMaterial({
          color: 0x073722,
          emissive: 0x000000,
          emissiveIntensity: 0
        });

        const lensGeometry = new THREE.SphereGeometry(0.135, 10, 8);

        const r = new THREE.Mesh(lensGeometry, red);
        r.position.set(0.23, 0.34, 0);
        signal.add(r);

        const y = new THREE.Mesh(lensGeometry, yellow);
        y.position.set(0.23, 0, 0);
        signal.add(y);

        const g = new THREE.Mesh(lensGeometry, green);
        g.position.set(0.23, -0.34, 0);
        signal.add(g);

        group.add(signal);
        signals.push({ red, yellow, green });
      }

      scene.add(group);

      const boardTexture = makeRouteBoardTexture(
