        13.4,
        11.02
      );

      box(
        8.35, 2.22, 0.12,
        mat.darkSteel,
        x,
        13.4,
        10.94
      );

      // Keep the board in front of its frame.
      board.position.z = 11.03;

      gantries.push({
        x,
        name,
        signals,
        board,
        texture: boardTexture,
        routeIndex: -1,
