    buildGantry(-66, "WEST JUNCTION");
    buildGantry(0, "AERIA STATION");
    buildGantry(66, "EAST JUNCTION");

    const routeSets = [
      [
        ["R1  MAINLINE", "TRACKS 1–2 · ALL STOPS", "#62f0a5"],
        ["R2  FLYOVER A", "NORTHBOUND JUNCTION EXIT", "#64d9ff"],
        ["R3  STATION STOP", "PLATFORMS 1 & 2", "#ffbf65"]
      ],
      [
        ["R1  MAINLINE", "TRACKS 3–4 · ALL STOPS", "#62f0a5"],
        ["R2  FLYOVER B", "SOUTHBOUND JUNCTION EXIT", "#ff789b"],
        ["R3  HOLD", "WAIT FOR CLEAR SIGNAL", "#ffbf65"]
      ],
      [
        ["R1  MAINLINE A", "WESTBOUND THROUGH SERVICE", "#62f0a5"],
        ["R2  FLYOVER A", "NORTHBOUND DIVERGING LINE", "#64d9ff"],
        ["R3  FLYOVER B", "SOUTHBOUND DIVERGING LINE", "#ff789b"]
      ]
    ];

    function updateGantries(force = false) {
      for (let gi = 0; gi < gantries.length; gi++) {
        const gantry = gantries[gi];
        const routeIndex = (Math.floor(gantry.cycle / 7) + gi) % routeSets[gi].length;

        if (!force && routeIndex === gantry.routeIndex) continue;

        gantry.routeIndex = routeIndex;
        const route = routeSets[gi][routeIndex];

        const texture = makeRouteBoardTexture(
          route[0],
          route[1],
          route[2],
          gantry.cycle + 1
        );

        gantry.board.material.map.dispose();
        gantry.board.material.map = texture;
        gantry.board.material.needsUpdate = true;

        gantry.signals.forEach((signal, i) => {
          signal.red.emissive.setHex(0x000000);
          signal.yellow.emissive.setHex(0x000000);
          signal.green.emissive.setHex(0x000000);

          if (i === routeIndex) {
            signal.green.emissive.setHex(0x35ff88);
            signal.green.emissiveIntensity = 2.4;
          } else if (i === (routeIndex + 1) % 4) {
            signal.yellow.emissive.setHex(0xffc83d);
            signal.yellow.emissiveIntensity = 1.8;
          } else {
            signal.red.emissive.setHex(0xff3245);
            signal.red.emissiveIntensity = 1.7;
          }
        });
      }
    }

    updateGantries(true);

    // ---------------------------------------------------------------------
    // Train paths
    // ---------------------------------------------------------------------

    function linePath(x1, z1, x2, z2) {
      return new THREE.LineCurve3(
        new THREE.Vector3(x1, TRAIN_Y, z1),
        new THREE.Vector3(x2, TRAIN_Y, z2)
      );
    }

    const pathA = new THREE.CurvePath();
    pathA.add(linePath(-100, 6, -66, 6));
    pathA.add(new THREE.CubicBezierCurve3(
      new THREE.Vector3(-66, TRAIN_Y, 6),
      new THREE.Vector3(-30, TRAIN_Y, 6),
      new THREE.Vector3(20, TRAIN_Y, 42),
      new THREE.Vector3(76, TRAIN_Y, 42)
    ));

    const pathB = new THREE.CurvePath();
    pathB.add(linePath(100, -6, 66, -6));
    pathB.add(new THREE.CubicBezierCurve3(
      new THREE.Vector3(66, TRAIN_Y, -6),
      new THREE.Vector3(30, TRAIN_Y, -6),
      new THREE.Vector3(-20, TRAIN_Y, -42),
      new THREE.Vector3(-76, TRAIN_Y, -42)
    ));

    const mainPathEast = linePath(-100, 0, 100, 0);
    const mainPathWest = linePath(100, 0, -100, 0);

    // ---------------------------------------------------------------------
    // Train models
    // ---------------------------------------------------------------------

    const trains = [];

    function createTrain(path, color, progress, speed, name) {
      const bodyMaterial = new THREE.MeshStandardMaterial({
        color,
        roughness: 0.36,
        metalness: 0.28
      });

      const roofMaterial = new THREE.MeshStandardMaterial({
        color: 0xe8eeee,
        roughness: 0.48,
        metalness: 0.15
      });

      const windowMaterial = new THREE.MeshStandardMaterial({
        color: 0x234b63,
        emissive: 0x0b2636,
        emissiveIntensity: 0.75,
        roughness: 0.18,
        metalness: 0.3
      });

      const headlightMaterial = new THREE.MeshStandardMaterial({
        color: 0xffffdf,
        emissive: 0xffe7aa,
        emissiveIntensity: 2.2
      });

      const cars = [];
      const carCount = 4;
      const carSpacing = 4.65;

      for (let i = 0; i < carCount; i++) {
        const car = new THREE.Group();

        box(4.05, 1.25, 1.55, bodyMaterial, 0, 1.05, 0, car);
        box(3.72, 0.16, 1.42, roofMaterial, 0, 1.72, 0, car);
        box(3.45, 0.42, 0.035, windowMaterial, 0, 1.28, 0.786, car);
        box(3.45, 0.42, 0.035, windowMaterial, 0, 1.28, -0.786, car);

        // Door seams.
        for (const x of [-1.2, 1.2]) {
          box(0.045, 0.83, 0.025, bodyMaterial, x, 1.0, 0.808, car);
          box(0.045, 0.83, 0.025, bodyMaterial, x, 1.0, -0.808, car);
        }

        const wheelGeometry = new THREE.CylinderGeometry(0.29, 0.29, 0.18, 12);
        for (const x of [-1.27, 1.27]) {
          for (const z of [-0.77, 0.77]) {
            const wheel = new THREE.Mesh(wheelGeometry, mat.black);
            wheel.rotation.x = Math.PI / 2;
            wheel.position.set(x, 0.3, z);
            wheel.castShadow = true;
            car.add(wheel);
          }
        }

        if (i === 0) {
          box(0.045, 0.46, 1.16, windowMaterial, 2.045, 1.31, 0, car);

          for (const z of [-0.48, 0.48]) {
            const lamp = new THREE.Mesh(
              new THREE.SphereGeometry(0.105, 10, 8),
              headlightMaterial
            );
            lamp.position.set(2.08, 0.82, z);
            car.add(lamp);
          }
        }

        scene.add(car);
        cars.push(car);
      }

      const train = {
        path,
        cars,
        progress,
        speed,
        name,
        length: path.getLength()
      };

      trains.push(train);
      return train;
    }

    createTrain(
      linePath(-100, -2.3, 100, -2.3),
      0xef6b45,
      0.18,
      6.0,
      "City Local"
    );

    createTrain(
      linePath(100, 2.3, -100, 2.3),
      0x2f8eb7,
      0.68,
      5.6,
      "Regional Express"
    );

    createTrain(
      pathA,
      0x4f9f79,
      0.53,
      6.3,
      "Flyover A"
    );

    createTrain(
      pathB,
      0x8b68b4,
      0.57,
      6.3,
      "Flyover B"
    );

    function updateTrains(dt) {
      for (const train of trains) {
        train.progress = (train.progress + train.speed * dt / train.length) % 1;

        train.cars.forEach((car, i) => {
          const carOffset = i * 4.65 / train.length;
          const u = (train.progress - carOffset + 1) % 1;
          const point = train.path.getPointAt(u);
          const tangent = train.path.getTangentAt(u);

          car.position.copy(point);
          car.rotation.y = -Math.atan2(tangent.z, tangent.x);
        });
      }
    }

    // ---------------------------------------------------------------------
    // Street traffic
    // ---------------------------------------------------------------------

    const cars = [];

    function createCar(color, horizontal, lane, direction, speed) {
      const group = new THREE.Group();

      const bodyMaterial = new THREE.MeshStandardMaterial({
        color,
        roughness: 0.38,
        metalness: 0.38
      });

      const glassMaterial = new THREE.MeshStandardMaterial({
        color: 0x264554,
        roughness: 0.16,
        metalness: 0.45
      });

      box(2.7, 0.68, 1.2, bodyMaterial, 0, 0.57, 0, group);
      box(1.5, 0.58, 1.05, glassMaterial, -0.1, 1.12, 0, group);
      box(1.38, 0.08, 1.03, bodyMaterial, -0.1, 1.43, 0, group);

      const wheelGeometry = new THREE.CylinderGeometry(0.28, 0.28, 0.18, 10);
      for (const x of [-0.85, 0.85]) {
        for (const z of [-0.61, 0.61]) {
          const wheel = new THREE.Mesh(wheelGeometry, mat.black);
          wheel.rotation.x = Math.PI / 2;
          wheel.position.set(x, 0.29, z);
          group.add(wheel);
        }
      }

      const lightMaterial = new THREE.MeshStandardMaterial({
        color: 0xffffdf,
        emissive: 0xffe5a1,
        emissiveIntensity: 1.5
      });

      for (const z of [-0.4, 0.4]) {
        const lamp = new THREE.Mesh(
          new THREE.SphereGeometry(0.08, 8, 6),
          lightMaterial
        );
        lamp.position.set(1.37, 0.62, z);
        group.add(lamp);
      }

      scene.add(group);

      cars.push({
        group,
        horizontal,
        lane,
        direction,
        speed,
        offset: random() * 120
      });
    }

    const carColors = [
      0xe7e9e5, 0x394f6a, 0xb8443e, 0xd0a04c,
      0x6f8f98, 0x30363b, 0x557a61, 0x8b6f99
    ];

    for (let i = 0; i < 16; i++) {
      const horizontal = i % 2 === 0;
      const lane = horizontal
        ? roadZ[Math.floor(random() * roadZ.length)] + (random() > 0.5 ? 2.15 : -2.15)
        : roadX[Math.floor(random() * roadX.length)] + (random() > 0.5 ? 2.15 : -2.15);

      createCar(
        carColors[i % carColors.length],
        horizontal,
        lane,
        random() > 0.5 ? 1 : -1,
        3.6 + random() * 4.5
      );
    }

    function updateCars(dt) {
      for (const car of cars) {
        car.offset = (car.offset + car.speed * car.direction * dt) % 130;
        if (car.offset < 0) car.offset += 130;

        if (car.horizontal) {
          car.group.position.set(-65 + car.offset, 0.06, car.lane);
          car.group.rotation.y = car.direction > 0 ? 0 : Math.PI;
        } else {
          car.group.position.set(car.lane, 0.07, -65 + car.offset);
          car.group.rotation.y = car.direction > 0 ? -Math.PI / 2 : Math.PI / 2;
        }
      }
    }

    // ---------------------------------------------------------------------
    // Clouds and atmospheric details
    // ---------------------------------------------------------------------

    const cloudMaterial = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.62,
      depthWrite: false
    });

    const clouds = [];

    for (let i = 0; i < 8; i++) {
      const cloud = new THREE.Group();
      const baseX = -150 + random() * 300;
      const baseZ = -125 + random() * 250;
      const baseY = 42 + random() * 22;

      for (let j = 0; j < 5; j++) {
        const puff = new THREE.Mesh(
          new THREE.SphereGeometry(5 + random() * 5, 12, 8),
          cloudMaterial
        );
        puff.position.set(
          (j - 2) * 5 + random() * 3,
          random() * 3,
          random() * 3
        );
        puff.scale.y = 0.48;
        cloud.add(puff);
      }

      cloud.position.set(baseX, baseY, baseZ);
      scene.add(cloud);
      clouds.push({ group: cloud, speed: 0.35 + random() * 0.3 });
    }

    // ---------------------------------------------------------------------
    // Directly implemented orbit / pan / zoom camera controls
    // ---------------------------------------------------------------------

    const cameraState = {
      target: new THREE.Vector3(0, 4.2, 0),
      radius: 145,
      theta: 0.67,
      phi: 0.92
    };

    function applyCamera() {
      const sinPhi = Math.sin(cameraState.phi);
      camera.position.set(
        cameraState.target.x + cameraState.radius * sinPhi * Math.sin(cameraState.theta),
        cameraState.target.y + cameraState.radius * Math.cos(cameraState.phi),
        cameraState.target.z + cameraState.radius * sinPhi * Math.cos(cameraState.theta)
      );
      camera.lookAt(cameraState.target);
    }

    function resetCamera() {
      cameraState.target.set(0, 4.2, 0);
      cameraState.radius = 145;
      cameraState.theta = 0.67;
      cameraState.phi = 0.92;
      applyCamera();
    }

    let dragging = false;
    let dragButton = 0;
    let lastX = 0;
    let lastY = 0;

    renderer.domElement.addEventListener("contextmenu", event => {
      event.preventDefault();
    });

    renderer.domElement.addEventListener("pointerdown", event => {
      dragging = true;
      dragButton = event.button;
      lastX = event.clientX;
      lastY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointerup", event => {
      dragging = false;
      if (renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    });

    renderer.domElement.addEventListener("pointermove", event => {
      if (!dragging) return;

      const dx = event.clientX - lastX;
      const dy = event.clientY - lastY;
      lastX = event.clientX;
      lastY = event.clientY;

      if (dragButton === 2) {
        const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
        const forward = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 2);
        forward.y = 0;
        forward.normalize();

        const panScale = cameraState.radius * 0.0012;
        cameraState.target.addScaledVector(right, -dx * panScale);
        cameraState.target.addScaledVector(forward, -dy * panScale);
      } else {
        cameraState.theta -= dx * 0.005;
        cameraState.phi = THREE.MathUtils.clamp(
          cameraState.phi - dy * 0.004,
          0.18,
          1.43
        );
      }

      applyCamera();
    });

    renderer.domElement.addEventListener("wheel", event => {
      event.preventDefault();
      cameraState.radius = THREE.MathUtils.clamp(
        cameraState.radius * Math.exp(event.deltaY * 0.001),
        25,
        260
      );
      applyCamera();
    }, { passive: false });

    document.getElementById("cameraReset").addEventListener("click", resetCamera);

    let paused = false;
    const pauseButton = document.getElementById("pause");

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
    });

    // ---------------------------------------------------------------------
    // Animation
    // ---------------------------------------------------------------------

    const clock = new THREE.Clock();
    let simulationTime = 0;
    let lastSignalCycle = 0;

    function animate() {
      requestAnimationFrame(animate);

      const dt = Math.min(clock.getDelta(), 0.05);
      if (!paused) {
        simulationTime += dt;

        updateTrains(dt);
        updateCars(dt);

        // Lift cabins continuously travel between street and platform level.
        for (const lift of lifts) {
          const phase = (simulationTime * 0.075 + lift.phase) % 1;
          const cycle = 0.5 - 0.5 * Math.cos(phase * Math.PI * 2);
          lift.cab.position.y = 0.9 + cycle * (PLATFORM_TOP - 0.9);
        }

        // Small platform pedestrians.
        for (const passenger of passengers) {
          const range = 17;
          const offset = Math.sin(simulationTime * 0.16 + passenger.phase * 8) * range;
          passenger.group.position.x = passenger.originX + offset;
          passenger.group.rotation.y = Math.cos(simulationTime * 0.16 + passenger.phase * 8) > 0
            ? Math.PI / 2
            : -Math.PI / 2;
        }

        for (const cloud of clouds) {
          cloud.group.position.x += cloud.speed * dt;
          if (cloud.group.position.x > 175) cloud.group.position.x = -175;
        }

        // Every seven simulated seconds the selected junction route changes.
        const signalCycle = Math.floor(simulationTime / 7);
        if (signalCycle !== lastSignalCycle) {
          lastSignalCycle = signalCycle;
          gantries.forEach(gantry => gantry.cycle++);
          updateGantries();
        }
      }

      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    });

    resetCamera();
    updateTrains(0);
    updateCars(0);
    animate();

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
    });
  </script>
</body>
</html>
