    const bondMaterial = new THREE.MeshStandardMaterial({
      color: 0x858e96,
      roughness: 0.36,
      metalness: 0.4
    });

    const sleeveMaterial = new THREE.MeshStandardMaterial({
      color: 0xa5adb4,
      roughness: 0.3,
      metalness: 0.48
    });

    const molecule = new THREE.Group();
    scene.add(molecule);

    // Molecular geometry: 104.5° at the oxygen apex.
    const oxygenRadius = 0.38;
    const hydrogenRadius = 0.25;
    const bondLength = 1.65;
    const bondAngle = THREE.MathUtils.degToRad(104.5);
    const halfAngle = bondAngle / 2;

    const oxygenPosition = new THREE.Vector3(0, 0.68, 0);

    const leftDirection = new THREE.Vector3(
      -Math.sin(halfAngle),
      -Math.cos(halfAngle),
      0
    );

