      Math.sin(halfAngle),
      -Math.cos(halfAngle),
      0
    );

    const leftHydrogen = oxygenPosition
      .clone()
      .addScaledVector(leftDirection, bondLength);

    const rightHydrogen = oxygenPosition
      .clone()
      .addScaledVector(rightDirection, bondLength);

    // Utility for creating a cylinder between two points.
    function cylinderBetween(start, end, radius, material, openEnded = false) {
      const direction = end.clone().sub(start);
      const length = direction.length();

      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        48,
        1,
        openEnded
      );

      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );

      mesh.castShadow = true;
      mesh.receiveShadow = true;
      return mesh;
    }

