    oxygen.receiveShadow = true;
    molecule.add(oxygen);

    for (const hydrogenPosition of [leftHydrogen, rightHydrogen]) {
      const hydrogen = new THREE.Mesh(
        new THREE.SphereGeometry(hydrogenRadius, 48, 32),
