      hydrogen.position.copy(hydrogenPosition);
      hydrogen.castShadow = true;
      hydrogen.receiveShadow = true;
      molecule.add(hydrogen);
    }

    // Bonds and shallow gray sleeves around each atomic connection.
    function addBond(hydrogenPosition, direction) {
      // Main bond.
      molecule.add(
        cylinderBetween(
          oxygenPosition,
          hydrogenPosition,
          0.105,
          bondMaterial
        )
      );

      // Sleeve around the oxygen side of the bond.
      const oxygenSleeveStart = oxygenPosition
        .clone()
        .addScaledVector(direction, oxygenRadius - 0.12);

      const oxygenSleeveEnd = oxygenPosition
        .clone()
        .addScaledVector(direction, oxygenRadius + 0.075);

      molecule.add(
