          oxygenSleeveStart,
          oxygenSleeveEnd,
          0.19,
          sleeveMaterial,
          true
        )
      );

      // Sleeve around the hydrogen side, pointing back toward oxygen.
      const hydrogenSleeveStart = hydrogenPosition
        .clone()
        .addScaledVector(direction, -(hydrogenRadius + 0.075));

      const hydrogenSleeveEnd = hydrogenPosition
        .clone()
        .addScaledVector(direction, -(hydrogenRadius - 0.1));

      molecule.add(
        cylinderBetween(
          hydrogenSleeveStart,
          hydrogenSleeveEnd,
          0.15,
          sleeveMaterial,
          true
        )
      );
    }

    addBond(leftHydrogen, leftDirection);
    addBond(rightHydrogen, rightDirection);

    // Transparent floor for a soft contact shadow.
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.ShadowMaterial({
        color: 0x263746,
        opacity: 0.14
      })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.91;
    floor.receiveShadow = true;
    scene.add(floor);

    // Direct camera controls implemented without Three.js addons.
    const target = new THREE.Vector3(0, 0.08, 0);
    const spherical = new THREE.Spherical(4.7, Math.PI / 2, 0);
    let dragging = false;
    let previousX = 0;
    let previousY = 0;

    function updateCamera() {
      camera.position.setFromSpherical(spherical).add(target);
      camera.lookAt(target);
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      previousX = event.clientX;
      previousY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;

      spherical.theta -= deltaX * 0.006;
      spherical.phi = THREE.MathUtils.clamp(
        spherical.phi - deltaY * 0.005,
        0.45,
        Math.PI - 0.45
      );

      previousX = event.clientX;
      previousY = event.clientY;
      updateCamera();
    });

    function stopDragging(event) {
      dragging = false;
      if (event.pointerId !== undefined) {
        if (renderer.domElement.hasPointerCapture(event.pointerId)) {
          renderer.domElement.releasePointerCapture(event.pointerId);
        }
      }
    }

    renderer.domElement.addEventListener("pointerup", stopDragging);
    renderer.domElement.addEventListener("pointercancel", stopDragging);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        spherical.radius = THREE.MathUtils.clamp(
          spherical.radius + event.deltaY * 0.003,
          3.1,
          8
        );
        updateCamera();
      },
      { passive: false }
    );

    updateCamera();

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();

      // Subtle floating motion; drag interaction remains available.
      molecule.position.y = Math.sin(elapsed * 0.8) * 0.035;
      molecule.rotation.y = Math.sin(elapsed * 0.42) * 0.07;

      renderer.render(scene, camera);
    }

    animate();
  </script>
