      touch-action: none;
    }

    .hud {
      position: fixed;
      z-index: 10;
      pointer-events: none;
    }

    .title-card {
      top: 24px;
      left: 24px;
      max-width: min(420px, calc(100vw - 48px));
      padding: 17px 20px 16px;
      color: #f6fbff;
      background: linear-gradient(135deg, rgba(8, 29, 43, 0.86), rgba(13, 53, 66, 0.58));
      border: 1px solid rgba(255, 255, 255, 0.19);
      border-radius: 15px;
      box-shadow: 0 14px 40px rgba(5, 24, 35, 0.2);
      backdrop-filter: blur(12px);
    }

    .eyebrow {
      margin-bottom: 5px;
      color: #80d7e6;
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.22em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(23px, 3vw, 34px);
      font-weight: 760;
      letter-spacing: -0.035em;
    }

    .subtitle {
      margin-top: 7px;
      color: rgba(236, 248, 255, 0.72);
      font-size: 12px;
      line-height: 1.5;
    }

    .status {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 13px;
      color: #d7f7f2;
      font-size: 11px;
      font-weight: 650;
    }

    .status-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #55e6a6;
      box-shadow: 0 0 12px #55e6a6;
    }

    .help {
      left: 24px;
      bottom: 24px;
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 10px 13px;
      color: rgba(245, 252, 255, 0.85);
      background: rgba(7, 28, 39, 0.66);
      border: 1px solid rgba(255, 255, 255, 0.15);
      border-radius: 11px;
      backdrop-filter: blur(10px);
      font-size: 11px;
      letter-spacing: 0.01em;
    }

    .help span {
      opacity: 0.58;
    }

    button {
      pointer-events: auto;
      border: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 7px;
      padding: 6px 9px;
      color: #f4fbff;
      background: rgba(255, 255, 255, 0.1);
      font: inherit;
      font-size: 10px;
      font-weight: 750;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      cursor: pointer;
      transition: background 150ms ease, transform 150ms ease;
    }

    button:hover {
      background: rgba(255, 255, 255, 0.19);
      transform: translateY(-1px);
    }

    #loading {
      position: fixed;
      z-index: 100;
      inset: 0;
      display: grid;
      place-items: center;
      color: #effcff;
      background: #123747;
      font-size: 12px;
      font-weight: 750;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      transition: opacity 500ms ease;
    }

    #loading.hidden {
      opacity: 0;
      pointer-events: none;
    }

    @media (max-width: 600px) {
      .title-card {
        top: 14px;
        left: 14px;
        padding: 14px 16px;
      }

      .help {
        left: 14px;
        right: 14px;
        bottom: 14px;
        justify-content: space-between;
      }
    }
  </style>
</head>

<body>
  <div id="loading">Preparing the vessel</div>

  <section class="hud title-card">
    <div class="eyebrow">Port service vessel · North sea operations</div>
    <h1>M/V Northstar</h1>
    <div class="subtitle">
      Buoy tender with an articulated stern crane, open working deck,
      navigation systems, and deck handling equipment.
    </div>
    <div class="status">
      <div class="status-dot"></div>
      Crane operational · Buoy recovery in progress
    </div>
  </section>

  <section class="hud help">
    <div>Drag to orbit <span>•</span> Scroll to zoom <span>•</span> Double-click to reset</div>
    <button id="reset-camera" type="button">Reset view</button>
  </section>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0xb5d1d9, 0.0085);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      260
    );

    const clock = new THREE.Clock();
    const vessel = new THREE.Group();
    vessel.position.y = 0.04;
    scene.add(vessel);

    // -------------------------------------------------------------------------
    // Materials
    // -------------------------------------------------------------------------

    const material = (color, roughness = 0.5, metalness = 0.05) =>
      new THREE.MeshStandardMaterial({ color, roughness, metalness });

    const mats = {
      hull: new THREE.MeshStandardMaterial({
        color: 0xa83229,
        roughness: 0.5,
        metalness: 0.12,
        side: THREE.DoubleSide
      }),
      navy: material(0x153748, 0.42, 0.18),
      deck: material(0x727d78, 0.85, 0.02),
      cream: material(0xe8e7dc, 0.47, 0.04),
      white: material(0xf4f1e7, 0.4, 0.04),
      orange: material(0xf18b22, 0.38, 0.12),
      orangeDark: material(0xb95516, 0.46, 0.14),
      yellow: material(0xf2c735, 0.42, 0.1),
      steel: material(0x889397, 0.28, 0.72),
      darkSteel: material(0x263238, 0.3, 0.62),
      rubber: material(0x111719, 0.88, 0.02),
      glass: new THREE.MeshPhysicalMaterial({
        color: 0x173f50,
        roughness: 0.12,
        metalness: 0.22,
        transparent: true,
        opacity: 0.92
      }),
      rope: material(0x4d5149, 0.96, 0),
      red: material(0xe54838, 0.4, 0.08),
      green: material(0x1c9c62, 0.4, 0.08),
      skin: material(0xb97c5d, 0.75, 0),
      navyCloth: material(0x182d42, 0.9, 0),
      hiVis: material(0xe6f04f, 0.55, 0)
    };

    mats.greenLight = new THREE.MeshStandardMaterial({
      color: 0x36e78e,
      emissive: 0x0d9a50,
      emissiveIntensity: 2.4
    });

    mats.redLight = new THREE.MeshStandardMaterial({
      color: 0xff4b3d,
      emissive: 0xb8140d,
      emissiveIntensity: 2.4
    });

    // -------------------------------------------------------------------------
    // Geometry helpers
    // -------------------------------------------------------------------------

    function addMesh(parent, geometry, mat, cast = true, receive = true) {
      const object = new THREE.Mesh(geometry, mat);
      object.castShadow = cast;
      object.receiveShadow = receive;
      parent.add(object);
      return object;
    }

    function box(parent, w, h, d, x, y, z, mat, cast = true) {
      const object = addMesh(
        parent,
        new THREE.BoxGeometry(w, h, d),
        mat,
        cast,
        true
      );
      object.position.set(x, y, z);
      return object;
    }

    function cylinder(
      parent,
      rTop,
      rBottom,
      height,
      x,
      y,
      z,
      mat,
      radialSegments = 20
    ) {
      const object = addMesh(
        parent,
        new THREE.CylinderGeometry(rTop, rBottom, height, radialSegments),
        mat
      );
      object.position.set(x, y, z);
      return object;
    }

    function sphere(parent, radius, x, y, z, mat, segments = 20) {
      const object = addMesh(
        parent,
        new THREE.SphereGeometry(radius, segments, Math.max(10, segments / 2)),
        mat
      );
      object.position.set(x, y, z);
      return object;
    }

    const up = new THREE.Vector3(0, 1, 0);

    function orientBeam(object, a, b) {
      const direction = new THREE.Vector3().subVectors(b, a);
      object.position.copy(a).add(b).multiplyScalar(0.5);
      object.quaternion.setFromUnitVectors(up, direction.clone().normalize());
      object.scale.y = direction.length();
    }

    function beam(parent, a, b, radius, mat) {
      const object = addMesh(
        parent,
        new THREE.CylinderGeometry(radius, radius, 1, 10),
        mat
      );
      orientBeam(object, a, b);
      return object;
    }

    function rectangularBeam(parent, a, b, width, depth, mat) {
      const object = addMesh(
        parent,
        new THREE.BoxGeometry(width, 1, depth),
        mat
      );
      orientBeam(object, a, b);
      return object;
    }

    function railSegment(parent, a, b, height = 0.95, spacing = 0.95) {
      const topA = a.clone().add(new THREE.Vector3(0, height, 0));
      const topB = b.clone().add(new THREE.Vector3(0, height, 0));

      beam(parent, topA, topB, 0.033, mats.cream);
      beam(
        parent,
        a.clone().add(new THREE.Vector3(0, height * 0.52, 0)),
        b.clone().add(new THREE.Vector3(0, height * 0.52, 0)),
        0.022,
        mats.cream
      );

      const count = Math.max(1, Math.ceil(a.distanceTo(b) / spacing));
      for (let i = 0; i <= count; i++) {
        const p = a.clone().lerp(b, i / count);
        beam(parent, p, p.clone().add(new THREE.Vector3(0, height, 0)), 0.026, mats.cream);
      }
    }

    function bollard(parent, x, z) {
      cylinder(parent, 0.13, 0.16, 0.48, x, 1.36, z, mats.yellow, 14);
      box(parent, 0.62, 0.11, 0.18, x, 1.58, z, mats.yellow);
    }

    // -------------------------------------------------------------------------
    // Hull and working deck
    // -------------------------------------------------------------------------

    const hullSections = [
      { z: -9.0, w: 0.12 },
      { z: -7.6, w: 1.45 },
      { z: -5.0, w: 2.35 },
      { z: -1.0, w: 2.72 },
      { z: 4.8, w: 2.76 },
      { z: 6.7, w: 2.52 },
      { z: 7.15, w: 2.40 }
    ];

    const hullPositions = [];
    const hullIndices = [];

    for (const section of hullSections) {
      const w = section.w;
      hullPositions.push(
        -w, 1.05, section.z,
        -w * 0.98, 0.12, section.z,
        -w * 0.62, -1.02, section.z,
        w * 0.62, -1.02, section.z,
        w * 0.98, 0.12, section.z,
        w, 1.05, section.z
      );
    }

    for (let i = 0; i < hullSections.length - 1; i++) {
      for (let j = 0; j < 5; j++) {
        const a = i * 6 + j;
        const b = (i + 1) * 6 + j;
        const c = (i + 1) * 6 + j + 1;
        const d = i * 6 + j + 1;
        hullIndices.push(a, b, d, b, c, d);
      }
    }

    for (const endIndex of [0, hullSections.length - 1]) {
      const z = hullSections[endIndex].z;
      const centerIndex = hullPositions.length / 3;
      hullPositions.push(0, -0.15, z);
      for (let j = 0; j < 5; j++) {
        hullIndices.push(
          centerIndex,
          endIndex * 6 + j + 1,
          endIndex * 6 + j
        );
      }
    }

    const hullGeometry = new THREE.BufferGeometry();
    hullGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(hullPositions, 3)
    );
    hullGeometry.setIndex(hullIndices);
    hullGeometry.computeVertexNormals();
    addMesh(vessel, hullGeometry, mats.hull);

    // Navy upper hull belt.
    const beltPositions = [];
    const beltIndices = [];

    for (const side of [-1, 1]) {
      const base = beltPositions.length / 3;

      for (const section of hullSections) {
        beltPositions.push(
          side * (section.w + 0.025), 0.68, section.z,
          side * (section.w + 0.025), 1.05, section.z
        );
      }

      for (let i = 0; i < hullSections.length - 1; i++) {
        const a = base + i * 2;
        const b = base + (i + 1) * 2;
        beltIndices.push(a, b, a + 1, b, b + 1, a + 1);
      }
    }

    const beltGeometry = new THREE.BufferGeometry();
    beltGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(beltPositions, 3)
    );
    beltGeometry.setIndex(beltIndices);
    beltGeometry.computeVertexNormals();
    addMesh(
      vessel,
      beltGeometry,
      new THREE.MeshStandardMaterial({
        color: 0x153748,
        roughness: 0.42,
        metalness: 0.15,
        side: THREE.DoubleSide
      })
    );

    // Deck polygon.
    const deckOutline = [
      [-0.10, -9.0],
      [-1.85, -7.15],
      [-2.50, -4.55],
      [-2.72, 0.0],
      [-2.69, 5.55],
      [-2.38, 6.96],
      [2.38, 6.96],
      [2.69, 5.55],
      [2.72, 0.0],
      [2.50, -4.55],
      [1.85, -7.15]
    ];

    const deckPositions = [0, 1.08, 0];
    const deckIndices = [];

    for (const [x, z] of deckOutline) {
      deckPositions.push(x, 1.08, z);
    }

    for (let i = 0; i < deckOutline.length; i++) {
      deckIndices.push(
        0,
        1 + i,
        1 + ((i + 1) % deckOutline.length)
      );
    }

    const deckGeometry = new THREE.BufferGeometry();
    deckGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(deckPositions, 3)
    );
    deckGeometry.setIndex(deckIndices);
    deckGeometry.computeVertexNormals();
    addMesh(vessel, deckGeometry, mats.deck);

    // Non-slip working area and safety markings.
    box(vessel, 4.8, 0.035, 4.75, 0, 1.105, 3.75, material(0x4f5d59, 0.94, 0.01));
    box(vessel, 0.10, 0.045, 4.65, -1.94, 1.14, 3.7, mats.yellow);
    box(vessel, 0.10, 0.045, 4.65, 1.94, 1.14, 3.7, mats.yellow);
    box(vessel, 3.95, 0.045, 0.10, 0, 1.14, 1.38, mats.yellow);

    // Deckhouse and wheelhouse.
    box(vessel, 3.75, 2.6, 3.45, 0, 2.38, -1.18, mats.cream);
    box(vessel, 3.42, 1.75, 2.58, 0, 4.55, -1.28, mats.white);
    box(vessel, 3.68, 0.16, 2.88, 0, 5.49, -1.28, mats.cream);

    // Front windows.
    for (const x of [-1.08, 0, 1.08]) {
      const window = box(vessel, 0.91, 0.72, 0.045, x, 4.72, -2.59, mats.glass, false);
      window.rotation.x = -0.08;
    }

    // Side windows.
    for (const side of [-1, 1]) {
      for (const z of [-1.95, -0.72]) {
        box(vessel, 0.045, 0.70, 0.86, side * 1.73, 4.73, z, mats.glass, false);
      }
      box(vessel, 0.045, 1.05, 0.68, side * 1.895, 2.85, -0.3, mats.navy);
      box(vessel, 0.05, 0.08, 0.75, side * 1.925, 2.42, -0.3, mats.yellow);
    }

    // Rear doors and windows.
    box(vessel, 0.90, 1.38, 0.05, -0.55, 2.45, 0.56, mats.navy);
    box(vessel, 1.08, 0.60, 0.045, 0.62, 4.72, 0.025, mats.glass, false);
    box(vessel, 0.05, 0.28, 0.05, -0.18, 2.43, 0.61, mats.steel);

    // Roof equipment.
    box(vessel, 0.68, 1.05, 0.62, 0.73, 6.02, -0.30, mats.navy);
    box(vessel, 0.78, 0.11, 0.70, 0.73, 6.58, -0.30, mats.darkSteel);

    for (const x of [-0.65, 0.65]) {
      const raft = cylinder(vessel, 0.28, 0.28, 1.18, x, 5.88, -1.35, mats.orange, 18);
      raft.rotation.z = Math.PI / 2;
    }

    // Navigation mast and radar.
    cylinder(vessel, 0.075, 0.11, 3.0, 0, 7.04, -0.85, mats.cream, 14);
    beam(
      vessel,
      new THREE.Vector3(-0.72, 7.7, -0.85),
      new THREE.Vector3(0.72, 7.7, -0.85),
      0.04,
      mats.cream
    );

    const radar = new THREE.Group();
    radar.position.set(0, 8.13, -0.85);
    vessel.add(radar);

    cylinder(radar, 0.15, 0.15, 0.18, 0, 0, 0, mats.cream, 16);
    box(radar, 1.80, 0.09, 0.19, 0, 0.10, 0, mats.white);

    cylinder(vessel, 0.025, 0.035, 1.15, 0.45, 7.55, -0.85, mats.cream, 10);
    cylinder(vessel, 0.025, 0.035, 1.0, -0.45, 7.45, -0.85, mats.cream, 10);

    // Navigation lights.
    sphere(vessel, 0.095, -1.78, 5.33, -0.4, mats.redLight, 14);
    sphere(vessel, 0.095, 1.78, 5.33, -0.4, mats.greenLight, 14);
    sphere(vessel, 0.095, 0, 8.42, -0.85, mats.white, 14);

    // Exhaust stack.
    cylinder(vessel, 0.19, 0.24, 0.78, -0.85, 5.95, -0.1, mats.darkSteel, 16);

    // Lifebuoy on the cabin side.
    const lifebuoy = addMesh(
      vessel,
      new THREE.TorusGeometry(0.32, 0.075, 10, 28),
      mats.orange
    );
    lifebuoy.position.set(1.94, 3.3, -0.55);
    lifebuoy.rotation.y = Math.PI / 2;

    // -------------------------------------------------------------------------
    // Foredeck equipment
    // -------------------------------------------------------------------------

    box(vessel, 1.4, 0.16, 1.0, 0, 1.18, -4.7, mats.darkSteel);
    const windlassDrum = cylinder(vessel, 0.32, 0.32, 1.0, 0, 1.56, -4.7, mats.steel, 20);
    windlassDrum.rotation.z = Math.PI / 2;

    for (const x of [-0.54, 0.54]) {
      const flange = cylinder(vessel, 0.40, 0.40, 0.09, x, 1.56, -4.7, mats.orange, 20);
      flange.rotation.z = Math.PI / 2;
    }

    beam(
      vessel,
      new THREE.Vector3(0, 1.63, -5.55),
      new THREE.Vector3(0, 1.63, -3.9),
      0.025,
      mats.rope
    );

    for (const x of [-1.35, 1.35]) {
      bollard(vessel, x, -5.85);
    }

    // Bow anchor.
    box(vessel, 0.12, 0.80, 0.16, 0.0, 0.45, -8.15, mats.darkSteel);
    box(vessel, 0.85, 0.13, 0.18, 0.0, 0.26, -8.18, mats.darkSteel);
    beam(
      vessel,
      new THREE.Vector3(0, 0.5, -8.0),
      new THREE.Vector3(0, 1.2, -7.4),
      0.035,
      mats.darkSteel
    );

    // -------------------------------------------------------------------------
    // Stern working-deck equipment
    // -------------------------------------------------------------------------

    // Large winch.
    box(vessel, 1.75, 0.18, 0.95, 0, 1.2, 2.25, mats.darkSteel);
    const winchDrum = cylinder(vessel, 0.46, 0.46, 1.55, 0, 1.67, 2.25, mats.steel, 24);
    winchDrum.rotation.z = Math.PI / 2;

    for (const x of [-0.84, 0.84]) {
      const flange = cylinder(vessel, 0.60, 0.60, 0.11, x, 1.67, 2.25, mats.orange, 24);
      flange.rotation.z = Math.PI / 2;
    }

    for (let i = 0; i < 8; i++) {
      const winding = addMesh(
        vessel,
        new THREE.TorusGeometry(0.47, 0.027, 7, 26),
        mats.rope
      );
      winding.position.set(-0.65 + i * 0.185, 1.67, 2.25);
      winding.rotation.y = Math.PI / 2;
    }

    beam(
      vessel,
      new THREE.Vector3(0.54, 1.72, 2.35),
      new THREE.Vector3(0.12, 1.25, 4.55),
      0.027,
      mats.rope
    );

    // Hatch and cargo pallet.
    box(vessel, 1.45, 0.13, 1.18, -1.22, 1.18, 3.58, mats.cream);
    box(vessel, 1.22, 0.10, 0.95, -1.22, 1.28, 3.58, mats.yellow);
    box(vessel, 0.85, 0.62, 0.72, -1.22, 1.62, 3.58, material(0x8a6842, 0.93, 0));
    box(vessel, 0.89, 0.06, 0.75, -1.22, 1.95, 3.58, mats.cream);

    // Stacked deck buoys.
    for (let i = 0; i < 2; i++) {
      const buoy = sphere(
        vessel,
        0.34,
        1.55,
        1.48 + i * 0.60,
        3.25,
        i === 0 ? mats.red : mats.yellow
      );
      buoy.scale.y = 1.12;
      cylinder(
        vessel,
        0.05,
        0.05,
        0.28,
        1.55,
        1.89 + i * 0.60,
        3.25,
        mats.darkSteel,
        10
      );
    }

    // Rope coil.
    for (let i = 0; i < 4; i++) {
      const coil = addMesh(
        vessel,
        new THREE.TorusGeometry(0.24 + i * 0.035, 0.026, 7, 28),
        mats.rope
      );
      coil.position.set(-1.53, 1.16 + i * 0.006, 1.85);
      coil.rotation.x = Math.PI / 2;
    }

    // Work light.
    cylinder(vessel, 0.045, 0.055, 1.4, 1.6, 1.9, 4.35, mats.cream, 10);
    const workLight = box(vessel, 0.38, 0.25, 0.18, 1.6, 2.58, 4.35, mats.yellow);
    workLight.rotation.x = 0.2;

    // Bollards and stern safety gear.
    for (const x of [-2.05, 2.05]) {
      bollard(vessel, x, 6.2);
    }

    // Railings leave a working opening on the starboard side.
    const deckY = 1.1;
    railSegment(
      vessel,
      new THREE.Vector3(-2.60, deckY, 0.78),
      new THREE.Vector3(-2.60, deckY, 4.45)
    );
    railSegment(
      vessel,
      new THREE.Vector3(-2.60, deckY, 4.45),
      new THREE.Vector3(-2.60, deckY, 6.70)
    );
    railSegment(
      vessel,
      new THREE.Vector3(2.60, deckY, 0.78),
      new THREE.Vector3(2.60, deckY, 4.28)
    );
    railSegment(
      vessel,
      new THREE.Vector3(2.60, deckY, 6.16),
      new THREE.Vector3(2.60, deckY, 6.72)
    );
    railSegment(
      vessel,
      new THREE.Vector3(-2.35, deckY, 6.83),
      new THREE.Vector3(2.35, deckY, 6.83)
    );

    // Bow rails.
    railSegment(
      vessel,
      new THREE.Vector3(-2.47, deckY, -4.45),
      new THREE.Vector3(-1.82, deckY, -7.03)
    );
    railSegment(
      vessel,
      new THREE.Vector3(2.47, deckY, -4.45),
      new THREE.Vector3(1.82, deckY, -7.03)
    );

    // Side fenders.
    for (const z of [-2.8, 0.2, 3.2]) {
      for (const side of [-1, 1]) {
        const fender = addMesh(
          vessel,
          new THREE.TorusGeometry(0.28, 0.095, 9, 20),
          mats.rubber
        );
        fender.position.set(side * 2.78, 0.58, z);
        fender.rotation.y = Math.PI / 2;
        fender.scale.y = 1.22;
      }
    }

    // -------------------------------------------------------------------------
    // Stern lattice crane
    // -------------------------------------------------------------------------

    function latticeBoom(parent, a, b, width, mat) {
      const offset = new THREE.Vector3(0, 0, width * 0.5);
      const aLeft = a.clone().sub(offset);
      const aRight = a.clone().add(offset);
      const bLeft = b.clone().sub(offset);
      const bRight = b.clone().add(offset);

      beam(parent, aLeft, bLeft, 0.065, mat);
      beam(parent, aRight, bRight, 0.065, mat);

      const divisions = 5;
      for (let i = 0; i < divisions; i++) {
        const t0 = i / divisions;
        const t1 = (i + 1) / divisions;
        const p0Left = aLeft.clone().lerp(bLeft, t0);
        const p0Right = aRight.clone().lerp(bRight, t0);
        const p1Left = aLeft.clone().lerp(bLeft, t1);
        const p1Right = aRight.clone().lerp(bRight, t1);

        if (i % 2 === 0) {
          beam(parent, p0Left, p1Right, 0.035, mat);
        } else {
          beam(parent, p0Right, p1Left, 0.035, mat);
        }
      }
    }

    const craneBase = new THREE.Group();
    vessel.add(craneBase);

    cylinder(craneBase, 0.69, 0.78, 1.05, 0, 1.68, 5.08, mats.orange, 28);
    cylinder(craneBase, 0.72, 0.72, 0.15, 0, 2.22, 5.08, mats.darkSteel, 28);
    cylinder(craneBase, 0.50, 0.60, 0.76, 0, 2.66, 5.08, mats.orange, 24);

    const cranePivot = new THREE.Vector3(0, 3.03, 5.08);
    const craneElbow = new THREE.Vector3(0.88, 5.48, 5.14);
    const craneTip = new THREE.Vector3(2.78, 7.08, 5.20);
    const craneCounter = new THREE.Vector3(-1.28, 4.02, 5.03);

    latticeBoom(craneBase, cranePivot, craneElbow, 0.48, mats.orange);
    latticeBoom(craneBase, craneElbow, craneTip, 0.40, mats.orange);
    rectangularBeam(
      craneBase,
      cranePivot,
      craneCounter,
      0.30,
      0.34,
      mats.orangeDark
    );

    box(craneBase, 0.95, 0.72, 0.92, -1.35, 3.99, 5.03, mats.orangeDark);
    box(craneBase, 0.99, 0.13, 0.96, -1.35, 4.37, 5.03, mats.yellow);

    for (const pivot of [cranePivot, craneElbow, craneTip]) {
      const joint = cylinder(craneBase, 0.18, 0.18, 0.62, pivot.x, pivot.y, pivot.z, mats.darkSteel, 18);
      joint.rotation.x = Math.PI / 2;
    }

    // Hydraulic lift ram.
    const ramStart = new THREE.Vector3(-0.48, 2.52, 5.30);
    const ramEnd = new THREE.Vector3(0.57, 4.60, 5.30);
    const ramMid = ramStart.clone().lerp(ramEnd, 0.62);
    beam(craneBase, ramStart, ramMid, 0.105, mats.darkSteel);
    beam(craneBase, ramMid, ramEnd, 0.057, mats.steel);

    // Winch on crane.
    const craneWinch = cylinder(craneBase, 0.24, 0.24, 0.66, 0.10, 3.50, 5.10, mats.steel, 20);
    craneWinch.rotation.z = Math.PI / 2;

    // Hoist cable, hook block, and suspended recovery buoy.
    const hoistCable = beam(
      vessel,
      craneTip,
      new THREE.Vector3(2.78, 3.15, 5.20),
      0.018,
      mats.darkSteel
    );

    const hookBlock = box(vessel, 0.30, 0.38, 0.25, 2.78, 3.02, 5.20, mats.darkSteel);

    const hook = addMesh(
      vessel,
      new THREE.TorusGeometry(0.17, 0.047, 9, 24, Math.PI * 1.7),
      mats.steel
    );
    hook.position.set(2.78, 2.70, 5.20);
    hook.rotation.z = -0.35;

    const sling = beam(
      vessel,
      new THREE.Vector3(2.78, 2.57, 5.20),
      new THREE.Vector3(2.78, 2.42, 5.20),
      0.021,
      mats.rope
    );

    const suspendedBuoy = new THREE.Group();
    suspendedBuoy.position.set(2.78, 2.04, 5.20);
    vessel.add(suspendedBuoy);

    const buoyBody = sphere(suspendedBuoy, 0.43, 0, 0, 0, mats.orange, 24);
    buoyBody.scale.y = 1.08;
    cylinder(suspendedBuoy, 0.26, 0.33, 0.22, 0, 0.32, 0, mats.yellow, 20);
    cylinder(suspendedBuoy, 0.045, 0.045, 0.44, 0, 0.63, 0, mats.darkSteel, 10);
    sphere(suspendedBuoy, 0.07, 0, 0.87, 0, mats.greenLight, 12);

    // -------------------------------------------------------------------------
    // Crew figures
    // -------------------------------------------------------------------------

    function addCrew(x, z, rotation, vestMat) {
      const crew = new THREE.Group();
      crew.position.set(x, 1.1, z);
      crew.rotation.y = rotation;
      vessel.add(crew);

      for (const side of [-1, 1]) {
        cylinder(crew, 0.095, 0.105, 0.68, side * 0.14, 0.42, 0, mats.navyCloth, 12);
        box(crew, 0.20, 0.14, 0.31, side * 0.14, 0.10, 0.06, mats.rubber);
      }

      box(crew, 0.48, 0.56, 0.29, 0, 1.01, 0, vestMat);
      box(crew, 0.51, 0.08, 0.31, 0, 0.97, 0, mats.white);
      sphere(crew, 0.16, 0, 1.48, 0, mats.skin, 16);

      const helmet = sphere(crew, 0.19, 0, 1.60, 0, mats.yellow, 16);
      helmet.scale.y = 0.65;
      cylinder(crew, 0.22, 0.22, 0.04, 0, 1.55, 0, mats.yellow, 16);

      beam(
        crew,
        new THREE.Vector3(-0.27, 1.20, 0),
        new THREE.Vector3(-0.35, 0.78, 0.13),
        0.065,
        vestMat
      );
      beam(
        crew,
        new THREE.Vector3(0.27, 1.20, 0),
        new THREE.Vector3(0.34, 0.80, 0.18),
        0.065,
        vestMat
      );
    }

    addCrew(-0.85, 1.78, 0.2, mats.hiVis);
    addCrew(1.12, 2.95, -0.75, mats.orange);

    // -------------------------------------------------------------------------
    // Vessel lettering
    // -------------------------------------------------------------------------

    function createLabelTexture(text) {
      const canvas = document.createElement("canvas");
      canvas.width = 768;
      canvas.height = 160;
      const context = canvas.getContext("2d");
      context.clearRect(0, 0, canvas.width, canvas.height);
      context.fillStyle = "rgba(248,247,232,0.96)";
      context.font = "800 76px Arial, sans-serif";
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillText(text, canvas.width / 2, canvas.height / 2 + 2);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    const labelTexture = createLabelTexture("NORTHSTAR  ·  TENDER 07");
    const labelMaterial = new THREE.MeshBasicMaterial({
      map: labelTexture,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide
    });

    const starboardLabel = addMesh(
      vessel,
      new THREE.PlaneGeometry(2.75, 0.57),
      labelMaterial,
      false,
      false
    );
    starboardLabel.position.set(2.787, 0.43, 0.1);
    starboardLabel.rotation.y = Math.PI / 2;

    const portLabel = addMesh(
      vessel,
      new THREE.PlaneGeometry(2.75, 0.57),
      labelMaterial,
      false,
      false
    );
    portLabel.position.set(-2.787, 0.43, 0.1);
    portLabel.rotation.y = -Math.PI / 2;

    // -------------------------------------------------------------------------
    // Ocean
    // -------------------------------------------------------------------------

    const waterGeometry = new THREE.PlaneGeometry(180, 180, 76, 76);
    const waterMaterial = new THREE.MeshStandardMaterial({
      color: 0x187b8e,
      roughness: 0.28,
      metalness: 0.24,
      side: THREE.DoubleSide
    });

    const water = addMesh(scene, waterGeometry, waterMaterial, false, true);
    water.rotation.x = -Math.PI / 2;
    water.position.y = 0;

    function waveHeight(x, y, time) {
      return (
        Math.sin(x * 0.18 + time * 0.92) * 0.11 +
        Math.sin(y * 0.22 - time * 0.71) * 0.075 +
        Math.sin((x + y) * 0.105 + time * 0.48) * 0.065
      );
    }

    // Sun glints on the surface.
    const sparkleCount = 230;
    const sparklePositions = new Float32Array(sparkleCount * 3);
    const sparkleBases = [];

    for (let i = 0; i < sparkleCount; i++) {
      const x = (Math.random() - 0.5) * 105;
      const z = (Math.random() - 0.5) * 105;
      sparkleBases.push({ x, z });
      sparklePositions[i * 3] = x;
      sparklePositions[i * 3 + 1] = 0.04;
      sparklePositions[i * 3 + 2] = z;
    }

    const sparkleGeometry = new THREE.BufferGeometry();
    sparkleGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(sparklePositions, 3)
    );

    const sparkles = new THREE.Points(
      sparkleGeometry,
      new THREE.PointsMaterial({
        color: 0xe8fcff,
        size: 0.065,
        transparent: true,
        opacity: 0.72,
        depthWrite: false,
        sizeAttenuation: true
      })
    );
    scene.add(sparkles);

    // -------------------------------------------------------------------------
    // Sky, sun, clouds, and distant islands
    // -------------------------------------------------------------------------

    const skyMaterial = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      toneMapped: false,
      uniforms: {
        sunDirection: {
          value: new THREE.Vector3(-0.42, 0.72, -0.54).normalize()
        }
      },
      vertexShader: `
        varying vec3 vWorldDirection;

        void main() {
          vec4 worldPosition = modelMatrix * vec4(position, 1.0);
          vWorldDirection = normalize(worldPosition.xyz - cameraPosition);
          gl_Position = projectionMatrix * viewMatrix * worldPosition;
        }
      `,
      fragmentShader: `
        varying vec3 vWorldDirection;
        uniform vec3 sunDirection;

        void main() {
          vec3 direction = normalize(vWorldDirection);
          float height = clamp(direction.y * 0.5 + 0.5, 0.0, 1.0);

          vec3 horizon = vec3(0.72, 0.86, 0.89);
          vec3 zenith = vec3(0.18, 0.43, 0.64);
          vec3 sky = mix(horizon, zenith, pow(height, 0.72));

          float sunDot = max(dot(direction, sunDirection), 0.0);
          float sunGlow = pow(sunDot, 28.0);
          float sunDisk = pow(sunDot, 900.0);

          sky += vec3(1.0, 0.72, 0.38) * sunGlow * 0.45;
          sky += vec3(1.0, 0.93, 0.78) * sunDisk * 2.0;

          gl_FragColor = vec4(sky, 1.0);
        }
      `
    });

    const sky = new THREE.Mesh(new THREE.SphereGeometry(150, 32, 18), skyMaterial);
    scene.add(sky);

    const cloudMaterial = new THREE.MeshLambertMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.76,
      depthWrite: false
    });

    const cloudData = [
      [-40, 21, -52, 1.1],
      [30, 25, -62, 1.4],
      [58, 18, 18, 0.9],
      [-55, 19, 32, 1.0],
      [8, 30, -78, 1.7]
    ];

    for (const [x, y, z, scale] of cloudData) {
      const cloud = new THREE.Group();
      cloud.position.set(x, y, z);
      cloud.scale.setScalar(scale);
      scene.add(cloud);

      for (let i = 0; i < 5; i++) {
        const puff = new THREE.Mesh(
          new THREE.SphereGeometry(1, 12, 8),
          cloudMaterial
        );
        puff.position.set((i - 2) * 0.95, Math.sin(i * 1.4) * 0.22, 0);
        puff.scale.set(1.5, 0.62 + (i % 2) * 0.2, 0.8);
        cloud.add(puff);
      }
    }

    const islandMaterial = material(0x536b58, 0.96, 0);
    const rockMaterial = material(0x69716b, 1, 0);

    const islandData = [
      [-33, -0.75, -40, 6.5],
      [36, -0.9, -48, 8.0],
      [51, -0.85, 11, 5.4],
      [-49, -0.85, 22, 7.0]
    ];

    for (const [x, y, z, radius] of islandData) {
      const island = addMesh(
        scene,
        new THREE.ConeGeometry(radius, 3.0, 7),
        islandMaterial,
        false,
        false
      );
      island.position.set(x, y, z);
      island.scale.set(1.35, 0.42, 0.75);
      island.rotation.y = Math.random() * Math.PI;

      const rock = addMesh(
        scene,
        new THREE.DodecahedronGeometry(radius * 0.33, 0),
        rockMaterial,
        false,
        false
      );
      rock.position.set(x + radius * 0.25, -0.6, z + 1);
      rock.scale.set(1.4, 0.55, 0.8);
    }

    // -------------------------------------------------------------------------
    // Lighting
    // -------------------------------------------------------------------------

    const hemisphere = new THREE.HemisphereLight(0xccefff, 0x32443a, 1.65);
    scene.add(hemisphere);

    const sunLight = new THREE.DirectionalLight(0xffe2b0, 3.25);
    sunLight.position.set(-14, 24, -10);
    sunLight.castShadow = true;
    sunLight.shadow.mapSize.set(2048, 2048);
    sunLight.shadow.camera.left = -18;
    sunLight.shadow.camera.right = 18;
    sunLight.shadow.camera.top = 18;
    sunLight.shadow.camera.bottom = -18;
    sunLight.shadow.camera.near = 1;
    sunLight.shadow.camera.far = 65;
    sunLight.shadow.normalBias = 0.025;
    sunLight.shadow.bias = -0.0001;
    scene.add(sunLight);

    const fillLight = new THREE.DirectionalLight(0x9adcf1, 0.65);
    fillLight.position.set(15, 8, 16);
    scene.add(fillLight);

    // -------------------------------------------------------------------------
    // Custom orbit camera controls
    // -------------------------------------------------------------------------

    const cameraState = {
      target: new THREE.Vector3(0, 2.25, 0.35),
      theta: 0.72,
      phi: 1.10,
      radius: 25
    };

    const initialCameraState = {
      theta: 0.72,
      phi: 1.10,
      radius: 25,
      target: cameraState.target.clone()
    };

    function updateCamera() {
      const sinPhi = Math.sin(cameraState.phi);
      camera.position.set(
        cameraState.target.x + cameraState.radius * sinPhi * Math.sin(cameraState.theta),
        cameraState.target.y + cameraState.radius * Math.cos(cameraState.phi),
        cameraState.target.z + cameraState.radius * sinPhi * Math.cos(cameraState.theta)
      );
      camera.lookAt(cameraState.target);
    }

    function resetCamera() {
      cameraState.theta = initialCameraState.theta;
      cameraState.phi = initialCameraState.phi;
      cameraState.radius = initialCameraState.radius;
      cameraState.target.copy(initialCameraState.target);
      updateCamera();
    }

    let dragging = false;
    let previousX = 0;
    let previousY = 0;
    let activePointerId = null;

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      activePointerId = event.pointerId;
      previousX = event.clientX;
      previousY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
      renderer.domElement.style.cursor = "grabbing";
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging || event.pointerId !== activePointerId) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;
      previousX = event.clientX;
      previousY = event.clientY;

      cameraState.theta -= deltaX * 0.0055;
      cameraState.phi = THREE.MathUtils.clamp(
        cameraState.phi - deltaY * 0.0045,
        0.28,
        1.48
      );

      updateCamera();
    });

    function endDrag(event) {
      if (event && activePointerId !== null && event.pointerId !== activePointerId) return;
      dragging = false;
      activePointerId = null;
      renderer.domElement.style.cursor = "grab";
    }

    renderer.domElement.addEventListener("pointerup", endDrag);
    renderer.domElement.addEventListener("pointercancel", endDrag);
    renderer.domElement.addEventListener("pointerleave", endDrag);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraState.radius = THREE.MathUtils.clamp(
          cameraState.radius + event.deltaY * 0.018,
          10,
          55
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetCamera);
    document.getElementById("reset-camera").addEventListener("click", resetCamera);
    renderer.domElement.style.cursor = "grab";
    updateCamera();

    // -------------------------------------------------------------------------
    // Animation
    // -------------------------------------------------------------------------

    let frame = 0;

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);
      const time = clock.elapsedTime;
      frame++;

      // Gentle vessel motion.
      vessel.position.y = 0.04 + Math.sin(time * 0.63) * 0.055;
      vessel.rotation.z = Math.sin(time * 0.47) * 0.008;
      vessel.rotation.x = Math.sin(time * 0.39 + 1.1) * 0.004;
      vessel.rotation.y = Math.sin(time * 0.25) * 0.003;

      // Radar sweep.
      radar.rotation.y += delta * 0.85;

      // Navigation beacon pulse.
      mats.greenLight.emissiveIntensity = 1.8 + Math.sin(time * 4.2) * 0.65;
      mats.redLight.emissiveIntensity = 1.8 + Math.sin(time * 4.2 + 1.5) * 0.65;

      // Slightly swinging suspended load.
      const swayX = Math.sin(time * 0.78) * 0.055;
      const swayZ = Math.cos(time * 0.66) * 0.035;
      const blockPosition = new THREE.Vector3(
        craneTip.x + swayX,
        3.02 + Math.sin(time * 0.78) * 0.025,
        craneTip.z + swayZ
      );

      orientBeam(hoistCable, craneTip, blockPosition);
      hookBlock.position.copy(blockPosition);
      hook.position.set(blockPosition.x, 2.70, blockPosition.z);
      suspendedBuoy.position.set(
        blockPosition.x,
        2.04 + Math.sin(time * 0.78) * 0.025,
        blockPosition.z
      );
      orientBeam(
        sling,
        new THREE.Vector3(blockPosition.x, 2.57, blockPosition.z),
        new THREE.Vector3(suspendedBuoy.position.x, 2.40, suspendedBuoy.position.z)
      );

      // Animated water surface.
      const positionAttribute = waterGeometry.attributes.position;

      for (let i = 0; i < positionAttribute.count; i++) {
        const x = positionAttribute.getX(i);
        const y = positionAttribute.getY(i);
        positionAttribute.setZ(i, waveHeight(x, y, time));
      }

      positionAttribute.needsUpdate = true;
      if (frame % 2 === 0) {
        waterGeometry.computeVertexNormals();
      }

      // Moving surface glints.
      for (let i = 0; i < sparkleCount; i++) {
        const base = sparkleBases[i];
        sparklePositions[i * 3 + 1] =
          waveHeight(base.x, -base.z, time) + 0.055;
      }
      sparkleGeometry.attributes.position.needsUpdate = true;

      renderer.render(scene, camera);
    }

    animate();

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    requestAnimationFrame(() => {
      document.getElementById("loading").classList.add("hidden");
    });
  </script>
</body>
</html>
