    </div>
  </div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const loading = document.getElementById("loading");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.setAttribute("aria-label", "Interactive 3D bogie roller test stand");

    document.body.insertBefore(renderer.domElement, document.body.firstChild);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a1119);
    scene.fog = new THREE.Fog(0x0a1119, 11, 27);

    const camera = new THREE.PerspectiveCamera(
      42,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const hemi = new THREE.HemisphereLight(0xb9dcff, 0x20252b, 1.65);
    scene.add(hemi);

    const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
    keyLight.position.set(-4.5, 8.5, 6.5);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -7;
    keyLight.shadow.camera.right = 7;
    keyLight.shadow.camera.top = 7;
    keyLight.shadow.camera.bottom = -5;
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 24;
    keyLight.shadow.bias = -0.00025;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x5caeff, 2.1);
    rimLight.position.set(6, 4.5, -5);
    scene.add(rimLight);

    const warmLight = new THREE.PointLight(0xffaa4d, 32, 12, 2);
    warmLight.position.set(3.5, 3.6, 3.2);
    scene.add(warmLight);

    // -------------------------------------------------------------------------
    // Materials and procedural textures
    // -------------------------------------------------------------------------

    function standardMaterial(color, metalness = 0, roughness = 0.5, extra = {}) {
      return new THREE.MeshStandardMaterial({
        color,
        metalness,
        roughness,
        ...extra
      });
    }

    function makeStripeTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 64;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#f5bd26";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "#151b20";
      for (let x = -80; x < canvas.width + 80; x += 80) {
        ctx.beginPath();
        ctx.moveTo(x, 64);
        ctx.lineTo(x + 34, 64);
        ctx.lineTo(x + 94, 0);
        ctx.lineTo(x + 60, 0);
        ctx.closePath();
        ctx.fill();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(5, 1);
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function makeLabelTexture(text, accent = "#55ddff") {
      const canvas = document.createElement("canvas");
      canvas.width = 768;
      canvas.height = 160;
      const ctx = canvas.getContext("2d");

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "rgba(5, 15, 22, 0.88)";
      ctx.strokeStyle = accent;
      ctx.lineWidth = 4;

      const x = 12;
      const y = 18;
      const w = canvas.width - 24;
      const h = canvas.height - 36;
      const r = 20;

      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + r);
      ctx.lineTo(x + w, y + h - r);
      ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
      ctx.lineTo(x + r, y + h);
      ctx.quadraticCurveTo(x, y + h, x, y + h - r);
      ctx.lineTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = accent;
      ctx.fillRect(34, 45, 8, 68);

      ctx.font = "700 42px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = "#eaf8ff";
      ctx.fillText(text, canvas.width / 2 + 12, canvas.height / 2);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function makeTopDecalTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 768;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "rgba(8, 16, 22, 0.82)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = "#f5bd26";
      ctx.lineWidth = 8;
      ctx.strokeRect(12, 12, canvas.width - 24, canvas.height - 24);

      ctx.textAlign = "center";
      ctx.fillStyle = "#ffc94e";
      ctx.font = "800 38px system-ui, sans-serif";
      ctx.fillText("BALLAST LOAD", canvas.width / 2, 95);

      ctx.fillStyle = "#ffffff";
      ctx.font = "800 76px system-ui, sans-serif";
      ctx.fillText("80 kN", canvas.width / 2, 180);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    const stripeTexture = makeStripeTexture();

    const materials = {
      floor: standardMaterial(0x141b21, 0.05, 0.94),
      wall: standardMaterial(0x101820, 0.18, 0.78),
      wallRib: standardMaterial(0x1b2832, 0.45, 0.55),
      base: standardMaterial(0x111920, 0.62, 0.48),
      deck: standardMaterial(0x263845, 0.65, 0.38),
      frame: standardMaterial(0x267dbf, 0.62, 0.29),
      frameDark: standardMaterial(0x155180, 0.68, 0.36),
      steel: standardMaterial(0xa8b7c0, 0.86, 0.25),
      darkSteel: standardMaterial(0x35434c, 0.82, 0.31),
      wheel: standardMaterial(0x30383e, 0.9, 0.25),
      wheelFace: standardMaterial(0x47545c, 0.82, 0.33),
      black: standardMaterial(0x11171c, 0.18, 0.72),
      yellow: standardMaterial(0xf2b92d, 0.35, 0.42),
      orange: standardMaterial(0xe77724, 0.42, 0.4),
      red: standardMaterial(0xdb3232, 0.3, 0.36),
      green: standardMaterial(0x2fd17a, 0.2, 0.35),
      stripe: standardMaterial(0xffffff, 0.15, 0.55, { map: stripeTexture }),
      cyan: standardMaterial(0x55ddff, 0.35, 0.28, {
        emissive: 0x0a6b86,
        emissiveIntensity: 0.8
      })
    };

    // -------------------------------------------------------------------------
    // Geometry helpers
    // -------------------------------------------------------------------------

    function box(w, h, d, material, x = 0, y = 0, z = 0, parent = scene) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function cylinder(
      radius,
      length,
      material,
      x = 0,
      y = 0,
      z = 0,
      parent = scene,
      axis = "y",
      segments = 32
    ) {
      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        segments
      );

      if (axis === "z") geometry.rotateX(Math.PI / 2);
      if (axis === "x") geometry.rotateZ(Math.PI / 2);

      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function beam(a, b, width, depth, material, parent = scene) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const midpoint = start.clone().add(end).multiplyScalar(0.5);

      const mesh = box(
        width,
        direction.length(),
        depth,
        material,
        midpoint.x,
        midpoint.y,
        midpoint.z,
        parent
      );

      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );

      return mesh;
    }

    function torus(radius, tube, material, x, y, z, parent = scene) {
      const mesh = new THREE.Mesh(
        new THREE.TorusGeometry(radius, tube, 12, 48),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // -------------------------------------------------------------------------
    // Factory floor and industrial backdrop
    // -------------------------------------------------------------------------

    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      materials.floor
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.012;
    floor.receiveShadow = true;
    scene.add(floor);

    const grid = new THREE.GridHelper(30, 60, 0x385467, 0x1b2932);
    grid.position.y = 0.002;
    grid.material.transparent = true;
    grid.material.opacity = 0.45;
    scene.add(grid);

    box(24, 6.2, 0.25, materials.wall, 0, 3.1, -6.2);

    for (let x = -10; x <= 10; x += 2) {
      box(0.055, 5.8, 0.08, materials.wallRib, x, 3.0, -6.04);
    }

    box(24, 0.12, 0.1, materials.wallRib, 0, 1.0, -6.02);

    const wallLightMaterial = new THREE.MeshBasicMaterial({
      color: 0xb9e9ff
    });

    for (const x of [-5.5, 0, 5.5]) {
      box(2.5, 0.08, 0.08, wallLightMaterial, x, 5.25, -6.01);
    }

    // -------------------------------------------------------------------------
    // Test stand foundation
    // -------------------------------------------------------------------------

