    // -------------------------------------------------------------------------
    // Custom camera controls: orbit, pan, zoom, touch pinch
    // -------------------------------------------------------------------------

    class CameraController {
      constructor(camera, domElement) {
        this.camera = camera;
        this.domElement = domElement;

        this.target = new THREE.Vector3(0, 1.32, 0);
        this.goalTarget = this.target.clone();

        this.spherical = new THREE.Spherical(8.8, 1.18, 0.69);
        this.goal = this.spherical.clone();

        this.pointers = new Map();
        this.mode = "rotate";
        this.lastPinchDistance = 0;

        this.onPointerDown = this.onPointerDown.bind(this);
        this.onPointerMove = this.onPointerMove.bind(this);
        this.onPointerUp = this.onPointerUp.bind(this);
        this.onWheel = this.onWheel.bind(this);
        this.onContextMenu = (event) => event.preventDefault();

        domElement.addEventListener("pointerdown", this.onPointerDown);
        domElement.addEventListener("pointermove", this.onPointerMove);
        domElement.addEventListener("pointerup", this.onPointerUp);
        domElement.addEventListener("pointercancel", this.onPointerUp);
        domElement.addEventListener("wheel", this.onWheel, { passive: false });
        domElement.addEventListener("contextmenu", this.onContextMenu);
      }

      setView(name) {
        const views = {
          iso: {
            position: new THREE.Vector3(6.2, 4.6, 6.9),
            target: new THREE.Vector3(0, 1.32, 0)
          },
          front: {
            position: new THREE.Vector3(0, 3.25, 9.2),
            target: new THREE.Vector3(0, 1.42, 0)
          },
          side: {
            position: new THREE.Vector3(8.8, 3.25, 0.05),
            target: new THREE.Vector3(0, 1.42, 0)
          },
          top: {
            position: new THREE.Vector3(0, 9.0, 0.08),
            target: new THREE.Vector3(0, 1.12, 0)
          }
        };

        const view = views[name];
        if (!view) return;

        const offset = view.position.clone().sub(view.target);
        const spherical = new THREE.Spherical().setFromVector3(offset);

        this.goal.radius = THREE.MathUtils.clamp(spherical.radius, 3.8, 14);
        this.goal.phi = THREE.MathUtils.clamp(spherical.phi, 0.08, 1.48);
        this.goal.theta = spherical.theta;
        this.goalTarget.copy(view.target);
      }

      onPointerDown(event) {
        this.domElement.setPointerCapture(event.pointerId);

        this.pointers.set(event.pointerId, {
          x: event.clientX,
          y: event.clientY
        });

        if (this.pointers.size === 1) {
          this.mode =
            event.button === 2 || event.shiftKey ? "pan" : "rotate";
        } else if (this.pointers.size === 2) {
          this.mode = "pinch";
          this.lastPinchDistance = this.getPinchDistance();
        }
      }

      onPointerMove(event) {
        const previous = this.pointers.get(event.pointerId);
        if (!previous) return;

        const dx = event.clientX - previous.x;
        const dy = event.clientY - previous.y;

        previous.x = event.clientX;
        previous.y = event.clientY;

        if (this.mode === "rotate" && this.pointers.size === 1) {
          this.goal.theta -= dx * 0.0052;
          this.goal.phi = THREE.MathUtils.clamp(
            this.goal.phi - dy * 0.0048,
            0.08,
            1.48
          );
        } else if (this.mode === "pan" && this.pointers.size === 1) {
          this.pan(dx, dy);
        } else if (this.mode === "pinch" && this.pointers.size >= 2) {
          const distance = this.getPinchDistance();

          if (this.lastPinchDistance > 0 && distance > 0) {
            this.goal.radius = THREE.MathUtils.clamp(
              this.goal.radius * (this.lastPinchDistance / distance),
              3.8,
              14
            );
          }

          this.lastPinchDistance = distance;
        }
      }

      onPointerUp(event) {
        this.pointers.delete(event.pointerId);

        if (this.pointers.size === 0) {
          this.mode = "rotate";
        } else if (this.pointers.size === 1) {
          this.mode = "rotate";
          this.lastPinchDistance = 0;
        }
      }

      onWheel(event) {
        event.preventDefault();
        this.goal.radius = THREE.MathUtils.clamp(
          this.goal.radius * Math.exp(event.deltaY * 0.001),
          3.8,
          14
        );
      }

      pan(dx, dy) {
        const forward = new THREE.Vector3();
        this.camera.getWorldDirection(forward);

        const right = new THREE.Vector3()
          .crossVectors(forward, this.camera.up)
          .normalize();

        const scale = this.goal.radius * 0.00135;

        this.goalTarget.addScaledVector(right, -dx * scale);
        this.goalTarget.addScaledVector(this.camera.up, dy * scale);

        this.goalTarget.x = THREE.MathUtils.clamp(this.goalTarget.x, -3.2, 3.2);
        this.goalTarget.y = THREE.MathUtils.clamp(this.goalTarget.y, 0.35, 2.8);
        this.goalTarget.z = THREE.MathUtils.clamp(this.goalTarget.z, -2.6, 2.6);
      }

      getPinchDistance() {
        const points = [...this.pointers.values()];
        if (points.length < 2) return 0;

        return Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );
      }

      update() {
        const damping = 0.12;

        this.spherical.radius +=
          (this.goal.radius - this.spherical.radius) * damping;
        this.spherical.phi +=
          (this.goal.phi - this.spherical.phi) * damping;
        this.spherical.theta +=
          (this.goal.theta - this.spherical.theta) * damping;

        this.target.lerp(this.goalTarget, damping);

        const offset = new THREE.Vector3().setFromSpherical(this.spherical);
        this.camera.position.copy(this.target).add(offset);
        this.camera.lookAt(this.target);
      }
    }

    const cameraController = new CameraController(camera, renderer.domElement);
    cameraController.update();

    // -------------------------------------------------------------------------
    // UI and animation state
    // -------------------------------------------------------------------------

    const runButton = document.getElementById("run");
    const speedInput = document.getElementById("speed");
    const speedValue = document.getElementById("speedValue");
    const rpmValue = document.getElementById("rpmValue");
    const statusValue = document.getElementById("statusValue");
    const statusDot = document.getElementById("statusDot");

    let running = true;
    let speed = 1;
    let rollerAngle = 0;
    let wheelAngle = 0;

    function updateRangeProgress() {
      const min = Number(speedInput.min);
      const max = Number(speedInput.max);
      const value = Number(speedInput.value);
      const progress = ((value - min) / (max - min)) * 100;
      speedInput.style.setProperty("--range-progress", `${progress}%`);
    }

    function updateUI() {
      const rpm = running ? Math.round(speed * 126) : 0;

      speedValue.textContent = `${rpm} rpm`;
      rpmValue.innerHTML = `${rpm} <small>rpm</small>`;

      runButton.textContent = running ? "Pause" : "Run";
      runButton.classList.toggle("active", !running);

      statusValue.textContent = running ? "RUNNING" : "PAUSED";
      statusDot.classList.toggle("paused", !running);

      beaconMaterial.color.set(running ? 0x42e888 : 0xffb02e);
      beaconMaterial.emissive.set(running ? 0x1a9c52 : 0x9b5b00);

      updateRangeProgress();
      updateScreen();
    }

    function toggleRunning() {
      running = !running;
      updateUI();
    }

    runButton.addEventListener("click", toggleRunning);

    speedInput.addEventListener("input", () => {
      speed = Number(speedInput.value);
      updateUI();
    });

    document.getElementById("reset").addEventListener("click", () => {
      rollerAngle = 0;
      wheelAngle = 0;

      for (const rotor of rollerRotors) rotor.rotation.z = 0;
      for (const wheelset of wheelGroups) wheelset.rotation.z = 0;
    });

    const labelsButton = document.getElementById("labels");

    labelsButton.addEventListener("click", () => {
      labelGroup.visible = !labelGroup.visible;
      labelsButton.classList.toggle("active", labelGroup.visible);
    });

    document.querySelectorAll("[data-view]").forEach((button) => {
      button.addEventListener("click", () => {
        cameraController.setView(button.dataset.view);

        document.querySelectorAll("[data-view]").forEach((other) => {
          other.classList.toggle("active", other === button);
        });
      });
    });

    document.getElementById("fullscreen").addEventListener("click", async () => {
      if (!document.fullscreenElement) {
        await document.documentElement.requestFullscreen?.();
      } else {
        await document.exitFullscreen?.();
      }
    });

    window.addEventListener("keydown", (event) => {
      if (event.target instanceof HTMLInputElement) return;

      if (event.code === "Space") {
        event.preventDefault();
        toggleRunning();
      }

      if (event.key.toLowerCase() === "r") {
        rollerAngle = 0;
        wheelAngle = 0;
      }

      if (event.key.toLowerCase() === "l") {
        labelsButton.click();
      }

      const views = {
        "1": "iso",
        "2": "front",
        "3": "side",
        "4": "top"
      };

      if (views[event.key]) {
        document.querySelector(`[data-view="${views[event.key]}"]`).click();
      }
    });

    // -------------------------------------------------------------------------
    // Instrument display
    // -------------------------------------------------------------------------

    function updateScreen() {
      const ctx = screenContext;
      const rpm = running ? Math.round(speed * 126) : 0;

      ctx.fillStyle = "#06151b";
      ctx.fillRect(0, 0, 512, 256);

      ctx.strokeStyle = "#1f5968";
      ctx.lineWidth = 4;
      ctx.strokeRect(5, 5, 502, 246);

      ctx.fillStyle = "#54ddff";
      ctx.font = "700 23px system-ui, sans-serif";
      ctx.textAlign = "left";
      ctx.fillText("BOGIE DYNAMICS / BAY 04", 24, 38);

      ctx.fillStyle = running ? "#64f5a5" : "#ffc247";
      ctx.font = "800 48px system-ui, sans-serif";
      ctx.fillText(running ? "ACTIVE TEST" : "PAUSED", 24, 96);

      ctx.fillStyle = "#ffffff";
      ctx.font = "700 34px system-ui, sans-serif";
      ctx.fillText(`${rpm} RPM`, 24, 150);

      ctx.fillStyle = "#87a9b9";
      ctx.font = "600 20px system-ui, sans-serif";
      ctx.fillText("AXLE LOAD 80 kN  •  2 AXLES", 24, 190);

      ctx.fillStyle = "#102b34";
      ctx.fillRect(24, 214, 464, 14);

      ctx.fillStyle = running ? "#55ddff" : "#ffc247";
      ctx.fillRect(24, 214, 464 * Math.min(speed / 2.4, 1), 14);

      screenTexture.needsUpdate = true;
    }

    // -------------------------------------------------------------------------
    // Render loop
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();
    let screenTimer = 0;

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      if (running) {
        const driveRate = speed * 13.2;
        rollerAngle += delta * driveRate;
        wheelAngle += delta * driveRate * (0.285 / 0.455);
      }

      for (const rotor of rollerRotors) {
        rotor.rotation.z = rollerAngle;
      }

      for (const wheelset of wheelGroups) {
        wheelset.rotation.z = wheelAngle;
      }

      // Very small frame vibration under load.
      bogie.position.y = running
        ? Math.sin(elapsed * 36) * 0.0022 * Math.min(speed, 1.4)
        : 0;

      cameraController.update();

      screenTimer += delta;
      if (screenTimer > 0.1) {
        screenTimer = 0;
        updateScreen();
      }

      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    updateUI();
    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
      setTimeout(() => loading.remove(), 450);
    });
  </script>
</body>
</html>
