    function canvasTexture(canvas, repeatX = 1, repeatY = 1) {
      const texture = new THREE.CanvasTexture(canvas);
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(repeatX, repeatY);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function makeConcreteTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 512;
      const ctx = canvas.getContext("2d");
      const image = ctx.createImageData(512, 512);

      for (let i = 0; i < image.data.length; i += 4) {
        const value = 91 + Math.random() * 28;
        image.data[i] = value;
        image.data[i + 1] = value + 2;
        image.data[i + 2] = value;
        image.data[i + 3] = 255;
      }

      ctx.putImageData(image, 0, 0);
      ctx.strokeStyle = "rgba(40,45,44,0.12)";
      ctx.lineWidth = 1;

      for (let i = 0; i < 45; i++) {
        const x = Math.random() * 512;
        const y = Math.random() * 512;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.random() * 40 - 20, y + Math.random() * 10 - 5);
        ctx.stroke();
      }

      return canvasTexture(canvas, 3, 5);
    }

    function makeWoodTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 1024;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");

      const gradient = ctx.createLinearGradient(0, 0, 0, 256);
      gradient.addColorStop(0, "#9a6743");
      gradient.addColorStop(0.5, "#815237");
      gradient.addColorStop(1, "#a16b45");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, 1024, 256);

      for (let i = 0; i < 180; i++) {
        const y = Math.random() * 256;
        ctx.strokeStyle = `rgba(55,27,15,${0.03 + Math.random() * 0.11})`;
        ctx.lineWidth = 0.5 + Math.random() * 2;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.bezierCurveTo(
          260,
          y + Math.random() * 18 - 9,
          680,
          y + Math.random() * 18 - 9,
          1024,
          y + Math.random() * 8 - 4
        );
        ctx.stroke();
      }

      for (let i = 0; i < 5; i++) {
        const x = Math.random() * 1024;
        const y = Math.random() * 256;
        ctx.strokeStyle = "rgba(46,22,12,0.18)";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.ellipse(x, y, 22 + Math.random() * 18, 5 + Math.random() * 4, 0, 0, Math.PI * 2);
        ctx.stroke();
      }

      return canvasTexture(canvas, 2, 1);
    }

    function makePegboardTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 512;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#ad8158";
      ctx.fillRect(0, 0, 512, 512);

      for (let y = 16; y < 512; y += 32) {
        for (let x = 16; x < 512; x += 32) {
          ctx.fillStyle = "#493729";
          ctx.beginPath();
          ctx.arc(x, y + 1.5, 3.1, 0, Math.PI * 2);
          ctx.fill();

          ctx.strokeStyle = "rgba(255,225,185,0.25)";
          ctx.lineWidth = 1;
          ctx.beginPath();
