      const gradient = ctx.createLinearGradient(0, 0, 1024, 320);
      gradient.addColorStop(0, background);
      gradient.addColorStop(1, "#111a1c");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, 1024, 320);

      ctx.fillStyle = accent;
      ctx.fillRect(0, 0, 28, 320);

      ctx.strokeStyle = "rgba(255,255,255,0.12)";
      ctx.lineWidth = 3;
      ctx.strokeRect(50, 38, 938, 244);

      ctx.fillStyle = "#f5eee2";
      ctx.textAlign = "center";
      ctx.font = "900 92px Arial, sans-serif";
      ctx.fillText(title, 512, 150);

      ctx.fillStyle = accent;
      ctx.font = "700 30px Arial, sans-serif";
      ctx.letterSpacing = "8px";
      ctx.fillText(subtitle, 512, 220);

      return canvasTexture(canvas);
