      })
    };

    function addMesh(geometry, material, parent = scene) {
      const object = new THREE.Mesh(geometry, material);
      object.castShadow = true;
      object.receiveShadow = true;
      parent.add(object);
      return object;
    }

    function box(w, h, d, material, x, y, z, parent = scene) {
      const object = addMesh(new THREE.BoxGeometry(w, h, d), material, parent);
      object.position.set(x, y, z);
      return object;
    }

    function cylinder(rt, rb, h, material, x, y, z, parent = scene, segments = 16) {
      const object = addMesh(
        new THREE.CylinderGeometry(rt, rb, h, segments),
        material,
        parent
      );
      object.position.set(x, y, z);
      return object;
    }

    function torus(radius, thickness, material, x, y, z, parent = scene, radial = 10, tubular = 40) {
      const object = addMesh(
        new THREE.TorusGeometry(radius, thickness, radial, tubular),
        material,
        parent
      );
      object.position.set(x, y, z);
      return object;
    }

    function tube(a, b, radius, material, parent = scene, segments = 10) {
      const start = Array.isArray(a) ? V(...a) : a.clone();
      const end = Array.isArray(b) ? V(...b) : b.clone();
      const direction = new THREE.Vector3().subVectors(end, start);
      const object = addMesh(
        new THREE.CylinderGeometry(radius, radius, direction.length(), segments),
        material,
        parent
      );
      object.position.copy(start).add(end).multiplyScalar(0.5);
      object.quaternion.setFromUnitVectors(V(0, 1, 0), direction.normalize());
      return object;
    }

    function textPlane(width, height, texture, x, y, z, parent = scene, rotationY = 0) {
      const material = new THREE.MeshStandardMaterial({
        map: texture,
        roughness: 0.86,
        metalness: 0
      });
      const plane = addMesh(new THREE.PlaneGeometry(width, height), material, parent);
      plane.position.set(x, y, z);
      plane.rotation.y = rotationY;
      plane.castShadow = false;
      return plane;
    }

    // ------------------------------------------------------------------
    // Narrow workshop shell
    // ------------------------------------------------------------------

    const floor = box(6.5, 0.16, 12.3, M.floor, 0, -0.08, 0);
    floor.castShadow = false;

    box(0.18, 4.15, 12.25, M.wall, -3.25, 2.0, 0);
    box(6.5, 4.15, 0.18, M.wall, 0, 2.0, -6.08);
    box(0.18, 0.72, 12.25, M.wallLower, 3.25, 0.36, 0);

    box(0.045, 1.02, 12.1, M.wallLower, -3.145, 0.51, 0);
    box(6.34, 1.02, 0.045, M.wallLower, 0, 0.51, -5.97);

    box(0.09, 0.18, 12.1, M.trim, -3.11, 0.09, 0);
    box(6.34, 0.18, 0.09, M.trim, 0, 0.09, -5.93);
    box(0.09, 0.18, 12.1, M.trim, 3.11, 0.09, 0);

    for (let z = -5; z <= 5; z += 2) {
      box(0.025, 3.4, 0.025, M.wallDark, -3.145, 2.05, z);
      box(6.25, 0.015, 0.018, M.wallDark, 0, 0.012, z);
    }

    for (const z of [-4.25, -0.55]) {
      box(6.45, 0.11, 0.14, M.beam, 0, 4.03, z);
    }

    const pipe = cylinder(0.045, 0.045, 6.15, M.darkMetal, -3.06, 3.52, -0.25);
    pipe.rotation.x = Math.PI / 2;

    const serviceMat = box(4.35, 0.022, 3.35, M.mat, -0.05, 0.014, -1.15);
    serviceMat.castShadow = false;

    for (let x = -1.8; x <= 1.8; x += 0.6) {
