    box(0.08, 0.19, 5.82, M.frame, -1.80, 1.02, -0.45);
    box(1.08, 0.08, 5.35, M.wood, -2.48, 0.27, -0.45);

    for (const x of [-2.93, -2.02]) {
      for (const z of [-2.95, -0.45, 2.02]) {
        box(0.11, 0.92, 0.11, M.darkMetal, x, 0.55, z);
        box(0.16, 0.06, 0.16, M.rubber, x, 0.04, z);
      }
    }

    box(0.10, 0.12, 4.95, M.darkMetal, -2.94, 0.91, -0.45);
    box(0.10, 0.12, 4.95, M.darkMetal, -2.02, 0.91, -0.45);

    box(0.92, 0.70, 1.42, M.blueDark, -2.49, 0.68, -2.28);
    for (let i = 0; i < 3; i++) {
      const y = 0.47 + i * 0.21;
      box(0.045, 0.18, 1.32, M.blue, -2.01, y, -2.28);
      const handle = cylinder(0.018, 0.018, 0.30, M.metal, -1.965, y, -2.28);
      handle.rotation.x = Math.PI / 2;
    }

