    function makeWheel(parent, center, outerRadius = 0.64, spokeCount = 20) {
      const group = new THREE.Group();
      group.position.set(...center);
      parent.add(group);

      const major = outerRadius - 0.05;
      torus(major, 0.05, M.tire, 0, 0, 0, group, 10, 48);
      torus(major - 0.045, 0.018, M.chrome, 0, 0, 0, group, 8, 48);

      const hub = cylinder(0.055, 0.055, 0.17, M.chrome, 0, 0, 0, group);
      hub.rotation.x = Math.PI / 2;

      for (let i = 0; i < spokeCount; i++) {
        const angle = (i / spokeCount) * Math.PI * 2;
        const innerRadius = 0.045;
        const outer = major - 0.065;
        tube(
          [Math.cos(angle) * innerRadius, Math.sin(angle) * innerRadius, i % 2 ? 0.025 : -0.025],
          [Math.cos(angle + 0.07) * outer, Math.sin(angle + 0.07) * outer, 0],
          0.0055,
          M.spoke,
          group,
          5
        );
      }

      const nut = cylinder(0.033, 0.033, 0.205, M.darkMetal, 0, 0, 0, group);
      nut.rotation.x = Math.PI / 2;

      return group;
    }

