    function clampView() {
      view.radius = THREE.MathUtils.clamp(view.radius, 5.0, 8.0);
      view.theta = THREE.MathUtils.clamp(view.theta, -0.28, 0.52);
      view.phi = THREE.MathUtils.clamp(view.phi, 0.95, 1.42);
      view.target.x = THREE.MathUtils.clamp(view.target.x, -1.8, 1.8);
      view.target.y = THREE.MathUtils.clamp(view.target.y, 0.75, 2.35);
      view.target.z = THREE.MathUtils.clamp(view.target.z, -4.2, 0.4);
    }

    function resetView() {
      view.target.set(-0.25, 1.28, -1.55);
      view.radius = 7.25;
      view.theta = 0.40;
      view.phi = 1.29;
      updateCamera();
    }

    let drag = null;

    renderer.domElement.addEventListener("contextmenu", event => event.preventDefault());

    renderer.domElement.addEventListener("pointerdown", event => {
      drag = {
        x: event.clientX,
        y: event.clientY,
        pan: event.shiftKey || event.button === 2
      };
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", event => {
      if (!drag) return;

      const dx = event.clientX - drag.x;
      const dy = event.clientY - drag.y;
      drag.x = event.clientX;
      drag.y = event.clientY;

      if (drag.pan) {
        const right = V().setFromMatrixColumn(camera.matrix, 0);
        const up = V().setFromMatrixColumn(camera.matrix, 1);
        const scale = view.radius * 0.00125;

        view.target.addScaledVector(right, -dx * scale);
        view.target.addScaledVector(up, dy * scale);
      } else {
        view.theta -= dx * 0.0046;
        view.phi -= dy * 0.0038;
      }

      clampView();
      updateCamera();
    });

    function endDrag(event) {
      drag = null;
      if (event.pointerId !== undefined && renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endDrag);
    renderer.domElement.addEventListener("pointercancel", endDrag);

    renderer.domElement.addEventListener(
      "wheel",
      event => {
        event.preventDefault();
        view.radius *= Math.exp(event.deltaY * 0.001);
        clampView();
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetView);

    window.addEventListener("keydown", event => {
      const key = event.key.toLowerCase();
      let handled = true;

      if (key === "arrowleft") view.theta += 0.045;
      else if (key === "arrowright") view.theta -= 0.045;
      else if (key === "arrowup") view.phi -= 0.035;
      else if (key === "arrowdown") view.phi += 0.035;
      else if (key === "+" || key === "=") view.radius -= 0.25;
      else if (key === "-" || key === "_") view.radius += 0.25;
      else if (key === "r") resetView();
      else handled = false;

      if (handled) {
        event.preventDefault();
        clampView();
        updateCamera();
      }
    });

    document.getElementById("resetView").addEventListener("click", resetView);

    function onResize() {
      const width = window.innerWidth;
      const height = window.innerHeight;
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(width, height);
      camera.aspect = width / height;
      camera.fov = width < 700 ? 58 : 48;
      camera.updateProjectionMatrix();
      updateCamera();
    }

    window.addEventListener("resize", onResize);

    // ------------------------------------------------------------------
    // Render loop
    // ------------------------------------------------------------------

    const clock = new THREE.Clock();

    function animate() {
      const elapsed = clock.getElapsedTime();
      dust.rotation.y = Math.sin(elapsed * 0.055) * 0.018;
      dust.position.y = Math.sin(elapsed * 0.18) * 0.035;
      renderer.render(scene, camera);
    }

    updateCamera();
    renderer.render(scene, camera);
    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
      setTimeout(() => loading.remove(), 600);
    });
  </script>
</body>
</html>
