<body>
  <div class="hud">
    <div class="eyebrow">Lunar Materials Facility / Line 04</div>
    <h1>Automated Regolith<br />Sintering Plant</h1>
    <div class="subtitle">
      Bucket elevator → hopper → automated gantry → tunnel kiln train
    </div>

    <div class="status-row">
