    </div>
  </div>

  <div class="controls">
    <strong>Drag</strong> orbit · <strong>Wheel</strong> zoom ·
    <strong>Right-drag</strong> pan · <strong>Double-click</strong> reset
  </div>

  <div id="cycle-fade"></div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // ---------------------------------------------------------------------
    // Renderer, scene, lighting
    // ---------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setSize(innerWidth, innerHeight);
    renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x17212a);
    scene.fog = new THREE.Fog(0x17212a, 72, 155);

    const camera = new THREE.PerspectiveCamera(
      42,
      innerWidth / innerHeight,
      0.1,
      260
    );

    const hemisphere = new THREE.HemisphereLight(0xb8d9ef, 0x5e4434, 2.1);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xfff0d2, 3.1);
    sun.position.set(-24, 48, 31);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -60;
    sun.shadow.camera.right = 60;
    sun.shadow.camera.top = 45;
    sun.shadow.camera.bottom = -45;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 130;
    sun.shadow.normalBias = 0.025;
    scene.add(sun);

    const rimLight = new THREE.DirectionalLight(0x6fb9d9, 1.25);
    rimLight.position.set(35, 22, -35);
    scene.add(rimLight);

    const ambient = new THREE.AmbientLight(0x8c9da8, 0.28);
    scene.add(ambient);

    // ---------------------------------------------------------------------
    // Materials and small construction helpers
    // ---------------------------------------------------------------------

    const material = {
      concrete: new THREE.MeshStandardMaterial({
        color: 0x78838a,
        roughness: 0.94,
        metalness: 0.02
      }),
      darkConcrete: new THREE.MeshStandardMaterial({
        color: 0x3d484f,
        roughness: 0.95
      }),
      steel: new THREE.MeshStandardMaterial({
        color: 0x66757d,
        roughness: 0.48,
        metalness: 0.72
      }),
      darkSteel: new THREE.MeshStandardMaterial({
        color: 0x263239,
        roughness: 0.5,
        metalness: 0.76
      }),
      rail: new THREE.MeshStandardMaterial({
        color: 0x9aa5aa,
        roughness: 0.26,
        metalness: 0.9
      }),
      yellow: new THREE.MeshStandardMaterial({
        color: 0xe6a12b,
        roughness: 0.48,
        metalness: 0.32
      }),
      orange: new THREE.MeshStandardMaterial({
        color: 0xd76d2c,
        roughness: 0.52,
        metalness: 0.28
      }),
      red: new THREE.MeshStandardMaterial({
        color: 0xbb3f30,
        roughness: 0.52,
        metalness: 0.42
      }),
      black: new THREE.MeshStandardMaterial({
        color: 0x111719,
        roughness: 0.74,
        metalness: 0.25
      }),
      regolith: new THREE.MeshStandardMaterial({
        color: 0xb78a62,
        roughness: 1.0
      }),
      refractory: new THREE.MeshStandardMaterial({
        color: 0x9b6b4e,
        roughness: 0.9
      }),
      glass: new THREE.MeshStandardMaterial({
        color: 0x77bfd1,
        roughness: 0.16,
        metalness: 0.2,
        transparent: true,
        opacity: 0.48
      }),
      hot: new THREE.MeshStandardMaterial({
        color: 0xff7328,
        emissive: 0xff3b08,
        emissiveIntensity: 4.2,
        roughness: 0.38
      }),
      roof: new THREE.MeshStandardMaterial({
        color: 0x66747c,
        roughness: 0.68,
        metalness: 0.45,
        side: THREE.DoubleSide
      })
    };

    const up = new THREE.Vector3(0, 1, 0);

    function box(parent, size, pos, mat, cast = true, receive = true) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(size[0], size[1], size[2]),
        mat
      );
      mesh.position.set(pos[0], pos[1], pos[2]);
      mesh.castShadow = cast;
      mesh.receiveShadow = receive;
      parent.add(mesh);
      return mesh;
    }

    function cylinder(parent, radiusTop, radiusBottom, height, pos, mat, segments = 20) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          height,
          segments
        ),
        mat
      );
      mesh.position.set(pos[0], pos[1], pos[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function sphere(parent, radius, pos, mat, segments = 16) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(radius, segments, Math.max(8, segments / 2)),
        mat
      );
      mesh.position.set(pos[0], pos[1], pos[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function beamBetween(parent, a, b, width, depth, mat) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(width, length, depth),
        mat
      );
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(up, direction.normalize());
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function strutBetween(parent, a, b, radius, mat) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radius, radius, 1, 10),
        mat
      );
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.scale.y = length;
      mesh.quaternion.setFromUnitVectors(up, direction.normalize());
      mesh.castShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function makeTextSprite(text, color = "#d9f2fb", background = "#17232c") {
      const canvas = document.createElement("canvas");
      canvas.width = 768;
      canvas.height = 160;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = background;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = color;
      ctx.lineWidth = 7;
      ctx.strokeRect(7, 7, canvas.width - 14, canvas.height - 14);

      ctx.fillStyle = color;
      ctx.font = "700 54px Arial";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(text, canvas.width / 2, canvas.height / 2 + 3);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;

      const sprite = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: texture,
          transparent: true,
          depthWrite: false
        })
      );

      sprite.scale.set(8.2, 1.7, 1);
      return sprite;
    }

    // ---------------------------------------------------------------------
    // Ground, markings and rail line
    // ---------------------------------------------------------------------

    const groundTextureCanvas = document.createElement("canvas");
    groundTextureCanvas.width = 512;
    groundTextureCanvas.height = 512;
    const groundCtx = groundTextureCanvas.getContext("2d");

    groundCtx.fillStyle = "#6b7275";
    groundCtx.fillRect(0, 0, 512, 512);

    for (let i = 0; i < 18000; i++) {
      const shade = 80 + Math.floor(Math.random() * 65);
      groundCtx.fillStyle = `rgba(${shade},${shade + 4},${shade + 7},0.22)`;
      groundCtx.fillRect(
        Math.random() * 512,
        Math.random() * 512,
        1 + Math.random() * 2,
        1 + Math.random() * 2
      );
    }

    const groundTexture = new THREE.CanvasTexture(groundTextureCanvas);
    groundTexture.colorSpace = THREE.SRGBColorSpace;
    groundTexture.wrapS = THREE.RepeatWrapping;
    groundTexture.wrapT = THREE.RepeatWrapping;
    groundTexture.repeat.set(18, 18);

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(180, 120),
      new THREE.MeshStandardMaterial({
        map: groundTexture,
        color: 0xa5aaa7,
        roughness: 0.96
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.set(0, -0.05, 0);
    ground.receiveShadow = true;
    scene.add(ground);

    // Concrete road strips
    box(scene, [125, 0.08, 4.4], [0, 0.01, 8.2], material.darkConcrete, false, true);
    box(scene, [125, 0.09, 0.14], [0, 0.07, 6.05], material.yellow, false, true);
    box(scene, [125, 0.09, 0.14], [0, 0.07, 10.35], material.yellow, false, true);

    // Rail bed
    box(scene, [104, 0.16, 3.9], [3, 0.06, 0], material.darkConcrete, false, true);

    for (let x = -48; x <= 55; x += 1.45) {
      const tie = box(
        scene,
        [0.3, 0.18, 2.9],
        [x, 0.16, 0],
        material.black,
        false,
        true
      );
      tie.rotation.y = (x % 3) * 0.004;
    }

    for (const z of [-0.92, 0.92]) {
      box(scene, [105, 0.22, 0.18], [3, 0.33, z], material.rail, false, true);
      box(scene, [105, 0.08, 0.28], [3, 0.17, z], material.darkSteel, false, true);
    }

    // ---------------------------------------------------------------------
    // Long cutaway tunnel kiln
    // ---------------------------------------------------------------------

    const kiln = new THREE.Group();
    scene.add(kiln);

    const kilnStart = 0;
    const kilnLength = 44;
    const kilnCenter = kilnStart + kilnLength / 2;

    box(
      kiln,
      [kilnLength + 1.2, 0.25, 10.8],
      [kilnCenter, 0.18, 0],
      material.darkConcrete,
      false,
      true
    );

    // Back refractory wall
    box(
      kiln,
      [kilnLength, 2.8, 0.45],
      [kilnCenter, 1.5, -5.12],
      material.refractory,
      false,
      true
    );

    // Low front lip and transparent cutaway skin
    box(
      kiln,
      [kilnLength, 0.55, 0.45],
      [kilnCenter, 0.45, 5.12],
      material.refractory,
      false,
      true
    );

    const cutawayMaterial = new THREE.MeshStandardMaterial({
      color: 0x91b3c0,
      roughness: 0.22,
      metalness: 0.1,
      transparent: true,
      opacity: 0.13,
      depthWrite: false,
      side: THREE.DoubleSide
    });

    box(
      kiln,
      [kilnLength, 2.45, 0.08],
      [kilnCenter, 1.7, 5.15],
      cutawayMaterial,
      false,
      false
    );

    // Half-cylinder arched roof, open toward the camera for a cutaway view.
    const roofGeometry = new THREE.CylinderGeometry(
      5.4,
      5.4,
      kilnLength,
      56,
      1,
      true,
      0,
      Math.PI
    );
    const roof = new THREE.Mesh(roofGeometry, material.roof);
    roof.rotation.z = Math.PI / 2;
    roof.position.set(kilnCenter, 2.65, 0);
    roof.castShadow = true;
    roof.receiveShadow = true;
    kiln.add(roof);

    // Structural arch ribs
    for (let x = kilnStart; x <= kilnStart + kilnLength + 0.01; x += 5.5) {
      const rib = new THREE.Mesh(
        new THREE.TorusGeometry(5.48, 0.16, 8, 40, Math.PI),
        material.darkSteel
      );
      rib.rotation.y = Math.PI / 2;
      rib.position.set(x, 2.65, 0);
      rib.castShadow = true;
      kiln.add(rib);
    }

    // Glowing entry arch
    const entryArch = new THREE.Mesh(
      new THREE.TorusGeometry(5.2, 0.11, 8, 48, Math.PI),
      material.hot
    );
    entryArch.rotation.y = Math.PI / 2;
    entryArch.position.set(-0.08, 2.65, 0);
    kiln.add(entryArch);

    // Hot kiln floor
    box(
      kiln,
      [kilnLength - 0.4, 0.08, 7.2],
      [kilnCenter, 0.37, 0],
      new THREE.MeshStandardMaterial({
        color: 0x7b351e,
        emissive: 0xd83a0d,
        emissiveIntensity: 1.45,
        roughness: 0.8
      }),
      false,
      false
    );

    // Heating elements on the back wall
    for (let x = 2; x < 43; x += 4.2) {
      box(
        kiln,
        [2.2, 0.17, 0.18],
        [x, 2.15, -4.78],
        material.hot,
        false,
        false
      );
      box(
        kiln,
        [2.2, 0.11, 0.15],
        [x, 1.15, -4.76],
        new THREE.MeshStandardMaterial({
          color: 0xff6b26,
          emissive: 0xff2b05,
          emissiveIntensity: 2.6,
          roughness: 0.45
        }),
        false,
        false
      );
    }

    // Warm lights inside the kiln
    for (const x of [4, 13, 22, 31, 40]) {
      const light = new THREE.PointLight(0xff6a22, 22, 10, 2);
      light.position.set(x, 3.2, 0.5);
      kiln.add(light);
    }

    // Roof access hatches
    for (const x of [7, 18, 29, 40]) {
      box(kiln, [3.2, 0.18, 2.1], [x, 8.13, 0.2], material.darkSteel);
      box(kiln, [2.7, 0.06, 1.7], [x, 8.25, 0.2], material.steel);
    }

    // Exhaust stack
    cylinder(kiln, 0.82, 0.95, 5.1, [34, 10.45, -2.8], material.darkSteel, 20);
    cylinder(kiln, 1.05, 1.05, 0.28, [34, 13.02, -2.8], material.steel, 20);
    cylinder(kiln, 0.88, 0.88, 0.5, [34, 13.32, -2.8], material.black, 20);

    const kilnLabel = makeTextSprite("SINTER KILN / 04", "#ffb24c", "#241a13");
    kilnLabel.position.set(20, 10.6, 4.9);
    kilnLabel.scale.set(9.4, 1.95, 1);
    kiln.add(kilnLabel);

    // ---------------------------------------------------------------------
    // Bucket elevator and feed conveyor
    // ---------------------------------------------------------------------

    const elevator = new THREE.Group();
    scene.add(elevator);

    const elevatorX = -28;
    const elevatorZ = -6.4;

    // Elevator frame
    for (const dx of [-0.82, 0.82]) {
      for (const dz of [-0.72, 0.72]) {
        beamBetween(
          elevator,
          [elevatorX + dx, 0.35, elevatorZ + dz],
          [elevatorX + dx, 16.15, elevatorZ + dz],
          0.16,
          0.16,
          material.steel
        );
      }
    }

