    // ---------------------------------------------------------------------
    // Custom camera controls: orbit, pan, wheel zoom
    // ---------------------------------------------------------------------

    const orbit = {
      target: new THREE.Vector3(0, 4, 0),
      radius: 90,
      theta: 0.72,
      phi: 1.10
    };

    function updateCamera() {
      const sinPhi = Math.sin(orbit.phi);
      camera.position.set(
        orbit.target.x + orbit.radius * sinPhi * Math.sin(orbit.theta),
        orbit.target.y + orbit.radius * Math.cos(orbit.phi),
        orbit.target.z + orbit.radius * sinPhi * Math.cos(orbit.theta)
      );
      camera.lookAt(orbit.target);
    }

    function resetCamera() {
      orbit.target.set(0, 4, 0);
      orbit.radius = 90;
      orbit.theta = 0.72;
      orbit.phi = 1.10;
      updateCamera();
    }

    let dragging = false;
    let panning = false;
    let lastPointerX = 0;
    let lastPointerY = 0;

    renderer.domElement.addEventListener("contextmenu", event => {
      event.preventDefault();
    });

    renderer.domElement.addEventListener("pointerdown", event => {
      dragging = true;
      panning = event.button === 2 || event.shiftKey;
      lastPointerX = event.clientX;
      lastPointerY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", event => {
      if (!dragging) return;

      const dx = event.clientX - lastPointerX;
      const dy = event.clientY - lastPointerY;
      lastPointerX = event.clientX;
      lastPointerY = event.clientY;

      if (panning) {
        const right = new THREE.Vector3();
        const upDirection = new THREE.Vector3();

        camera.matrixWorld.extractBasis(right, upDirection, new THREE.Vector3());
        const panScale = orbit.radius * 0.0014;

        orbit.target.addScaledVector(right, -dx * panScale);
        orbit.target.addScaledVector(upDirection, dy * panScale);
      } else {
        orbit.theta -= dx * 0.005;
        orbit.phi = THREE.MathUtils.clamp(
          orbit.phi - dy * 0.005,
          0.18,
          Math.PI * 0.49
        );
      }

      updateCamera();
    });

    function stopDragging(event) {
      dragging = false;
      if (event && renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", stopDragging);
    renderer.domElement.addEventListener("pointercancel", stopDragging);

    renderer.domElement.addEventListener(
      "wheel",
      event => {
        event.preventDefault();
        orbit.radius = THREE.MathUtils.clamp(
          orbit.radius * Math.exp(event.deltaY * 0.001),
          18,
          145
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", resetCamera);

    updateCamera();

    // ---------------------------------------------------------------------
    // Animation and automatic plant cycle
    // ---------------------------------------------------------------------

    const clock = new THREE.Clock();
    const cycleLength = 38;

    const phaseElement = document.getElementById("phase");
    const detailElement = document.getElementById("detail");
    const progressElement = document.getElementById("progress-fill");
    const statusDot = document.getElementById("status-dot");
    const cycleFade = document.getElementById("cycle-fade");

    const smooth = value => {
      const x = THREE.MathUtils.clamp(value, 0, 1);
      return x * x * (3 - 2 * x);
    };

    let previousCycle = -1;
    let fadeAmount = 0;

    function animate() {
      requestAnimationFrame(animate);

      const elapsed = clock.getElapsedTime();
      const cycleTime = elapsed % cycleLength;
      const cycleIndex = Math.floor(elapsed / cycleLength);

      if (cycleIndex !== previousCycle) {
        previousCycle = cycleIndex;
        fadeAmount = 0.85;

        for (const car of cars) {
          car.pressed = false;
          car.mound.scale.y = 0.36;
        }
      }

      fadeAmount = Math.max(0, fadeAmount - 0.025);
      cycleFade.style.opacity = fadeAmount.toFixed(3);

      let trainOffset = 0;
      let pressAmount = 0;
      let activeCar = 0;
      let phaseText = "";
      let detailText = "";
      let dotColor = "#71ed9c";

      // Five press/index stages, followed by movement into the kiln.
      if (cycleTime < 20) {
        activeCar = Math.min(4, Math.floor(cycleTime / 4));
        const localTime = cycleTime - activeCar * 4;

        const indexProgress = smooth((localTime - 3.0) / 1.0);
        trainOffset = activeCar * carSpacing + carSpacing * indexProgress;

        if (localTime < 0.55) {
          pressAmount = 0;
        } else if (localTime < 1.5) {
          pressAmount = smooth((localTime - 0.55) / 0.95);
        } else if (localTime < 2.15) {
          pressAmount = 1;
        } else if (localTime < 3.0) {
          pressAmount = 1 - smooth((localTime - 2.15) / 0.85);
        } else {
          pressAmount = 0;
        }

        if (pressAmount > 0.94) {
          cars[activeCar].pressed = true;
        }

        phaseText = pressAmount > 0.02
          ? "Compacting regolith charge"
          : indexProgress > 0
            ? "Indexing kiln car train"
            : "Positioning press head";

        detailText = `CAR ${String(activeCar + 1).padStart(2, "0")}`;

        if (pressAmount > 0.02) {
          dotColor = "#ffb24b";
        }
      } else if (cycleTime < 24) {
        activeCar = 4;
        trainOffset = 25;
        phaseText = "Press cycle complete";
        detailText = "5 / 5";
        dotColor = "#73d6ea";
      } else if (cycleTime < 34) {
        activeCar = 4;
        const transferProgress = smooth((cycleTime - 24) / 10);
        trainOffset = 25 + 30 * transferProgress;
        phaseText = "Charging tunnel kiln";
        detailText = `${Math.round(transferProgress * 100)}%`;
        dotColor = "#ff8848";
      } else {
        activeCar = 4;
        trainOffset = 55;
        phaseText = "Kiln sintering / soak cycle";
        detailText = "HOT";
        dotColor = "#ff5b2e";
      }

      // Move the rail-mounted cars.
      for (let i = 0; i < cars.length; i++) {
        const car = cars[i];
        car.group.position.x = gantryX - i * carSpacing + trainOffset;

        if (car.pressed) {
          car.mound.scale.y += (0.22 - car.mound.scale.y) * 0.12;
        }
      }

      // Move the pressing assembly.
      const pressHigh = 6.3;
      const pressLow = 2.58;
      pressHead.position.y = THREE.MathUtils.lerp(
        pressHigh,
        pressLow,
        pressAmount
      );

      // Upper piston from the fixed carriage to the moving head.
      const pistonBottom = pressHead.position.y + 2.65;
      const pistonTop = 10.05;
      const pistonLength = Math.max(0.1, pistonTop - pistonBottom);

      upperPiston.scale.y = pistonLength;
      upperPiston.position.y = pistonBottom + pistonLength / 2;

      // Telescopic material feed chute from hopper outlet to press body.
      const feedBottom = pressHead.position.y + 2.35;
      const feedTop = 11.25;
      const feedLength = Math.max(0.1, feedTop - feedBottom);

      feedChute.scale.y = feedLength;
      feedChute.position.y = feedBottom + feedLength / 2;

      // Bucket elevator motion.
      for (let i = 0; i < elevatorBuckets.length; i++) {
        const bucket = elevatorBuckets[i];
        const u = (i / elevatorBuckets.length + elapsed * 0.075) % 1;

        if (u < 0.5) {
          bucket.position.set(
            elevatorX - 0.46,
            1.0 + u * 2 * 14.9,
            elevatorZ
          );
        } else {
          bucket.position.set(
            elevatorX + 0.46,
            15.9 - (u - 0.5) * 2 * 14.9,
            elevatorZ
          );
        }
      }

      // Regolith spill / compression particles.
      regolithParticles.visible = pressAmount > 0.02;
      if (regolithParticles.visible) {
        for (let i = 0; i < particleCount; i++) {
          const angle = (i / particleCount) * Math.PI * 2;
          const radius = 0.65 + ((i * 37) % 100) / 100 * 1.2;
          const fall = (elapsed * (1.25 + (i % 5) * 0.12) + i * 0.037) % 1;

          particlePositions[i * 3] =
            gantryX + Math.cos(angle) * radius * (0.45 + fall * 0.55);

          particlePositions[i * 3 + 1] =
            2.35 + (1 - fall) * (2.2 + pressAmount * 1.5);

          particlePositions[i * 3 + 2] =
            Math.sin(angle) * radius * 0.7;
        }
        particleGeometry.attributes.position.needsUpdate = true;
        particleMaterial.opacity = 0.25 + pressAmount * 0.62;
      }

      // Beacon flashes while the press is active.
      const beaconPulse = 0.5 + 0.5 * Math.sin(elapsed * 11);
      beaconMaterial.emissive.set(
        pressAmount > 0.02 ? 0xff6b22 : 0x30ff70
      );
      beaconMaterial.emissiveIntensity =
        pressAmount > 0.02 ? 1.2 + beaconPulse * 4 : 1.1 + beaconPulse * 2;
      beacon.scale.setScalar(0.92 + beaconPulse * 0.14);

      // Exhaust puffs.
      for (let i = 0; i < smokePuffs.length; i++) {
        const life = (elapsed * 0.16 + i / smokePuffs.length) % 1;
        const puff = smokePuffs[i];

        puff.position.set(
          34 + Math.sin(i * 2.1 + life * 4) * life * 1.6,
          13.8 + life * 8.5,
          -2.8 + Math.cos(i * 1.4 + life * 3) * life * 1.1
        );

        const puffScale = 0.45 + life * 1.8;
        puff.scale.setScalar(puffScale);
        puff.material.opacity = 0.22 * (1 - life) * (1 - life);
      }

      // Subtle heat shimmer light inside the tunnel.
      const kilnLight = kiln.children.find(
        child => child.isPointLight && child.position.x === 4
      );
      if (kilnLight) {
        kilnLight.intensity = 20 + Math.sin(elapsed * 3.2) * 2.2;
      }

      // HUD
      phaseElement.textContent = phaseText;
      detailElement.textContent = detailText;
      statusDot.style.background = dotColor;
      statusDot.style.boxShadow = `0 0 14px ${dotColor}`;
      progressElement.style.width = `${(cycleTime / cycleLength) * 100}%`;

      renderer.render(scene, camera);
    }

    animate();

    // ---------------------------------------------------------------------
    // Resize handling
    // ---------------------------------------------------------------------

    addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
    });
  </script>
</body>
</html>
