  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0xb8cbca, 30, 76);

    const camera = new THREE.PerspectiveCamera(
      42,
      innerWidth / innerHeight,
      0.1,
      120
    );

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.prepend(renderer.domElement);

    const hemisphere = new THREE.HemisphereLight(0xd9efff, 0x5c3d28, 2.25);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xffe0ad, 3.7);
    sun.position.set(-11, 19, 13);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -22;
    sun.shadow.camera.right = 22;
    sun.shadow.camera.top = 22;
    sun.shadow.camera.bottom = -12;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 55;
    sun.shadow.bias = -0.00035;
    scene.add(sun);

    const warmFill = new THREE.PointLight(0xffa85b, 18, 16, 2);
    warmFill.position.set(0, 8.5, 0.8);
    scene.add(warmFill);

    // -------------------------------------------------------------------------
    // Procedural textures and materials
    // -------------------------------------------------------------------------

    let randomSeed = 14831;

    function random() {
      randomSeed = (randomSeed * 1664525 + 1013904223) >>> 0;
      return randomSeed / 4294967296;
    }

    function makeRockTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#a47c58";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 2400; i++) {
        const shade = 80 + Math.floor(random() * 105);
        const alpha = 0.025 + random() * 0.09;
        ctx.fillStyle = `rgba(${shade}, ${Math.floor(shade * 0.76)}, 50, ${alpha})`;
        const size = 1 + random() * 8;
        ctx.fillRect(random() * 256, random() * 256, size, size * 0.6);
      }

      for (let i = 0; i < 45; i++) {
        ctx.strokeStyle = `rgba(62, 41, 25, ${0.05 + random() * 0.09})`;
        ctx.lineWidth = 1 + random() * 2;
        ctx.beginPath();
        const x = random() * 256;
        const y = random() * 256;
        ctx.moveTo(x, y);
        ctx.lineTo(x + random() * 45 - 22, y + random() * 35);
        ctx.stroke();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(3, 3);
      return texture;
    }

    function makeWoodTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#81502d";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 160; i++) {
        const x = random() * 256;
        ctx.strokeStyle = random() > 0.5
          ? `rgba(39, 20, 8, ${0.06 + random() * 0.16})`
          : `rgba(225, 158, 79, ${0.04 + random() * 0.12})`;
        ctx.lineWidth = 0.5 + random() * 2.2;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.bezierCurveTo(
          x + random() * 9 - 4.5,
          70,
          x + random() * 10 - 5,
          170,
          x + random() * 7 - 3.5,
          256
        );
        ctx.stroke();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(1.5, 2.5);
      return texture;
    }

    const rockTexture = makeRockTexture();
    const woodTexture = makeWoodTexture();

    const materials = {
      rock: new THREE.MeshStandardMaterial({
        color: 0xc0a17c,
        map: rockTexture,
        roughness: 0.98
      }),
      rockDark: new THREE.MeshStandardMaterial({
        color: 0x8d7054,
        map: rockTexture,
        roughness: 1
      }),
      rockLight: new THREE.MeshStandardMaterial({
        color: 0xd0ad83,
        map: rockTexture,
        roughness: 1
      }),
      wood: new THREE.MeshStandardMaterial({
        color: 0xffffff,
        map: woodTexture,
        roughness: 0.83
      }),
      darkWood: new THREE.MeshStandardMaterial({
        color: 0x805333,
        map: woodTexture,
        roughness: 0.91
      }),
      paleWood: new THREE.MeshStandardMaterial({
        color: 0xd6aa6e,
        map: woodTexture,
        roughness: 0.8
      }),
      plaster: new THREE.MeshStandardMaterial({
        color: 0xc9ad7c,
        roughness: 0.95
      }),
      interior: new THREE.MeshStandardMaterial({
        color: 0x3a291d,
        roughness: 1
      }),
      iron: new THREE.MeshStandardMaterial({
        color: 0x3e3a34,
        metalness: 0.68,
        roughness: 0.56
      }),
      rope: new THREE.MeshStandardMaterial({
        color: 0xb99a62,
        roughness: 1
      }),
      glow: new THREE.MeshStandardMaterial({
        color: 0xffc77b,
        emissive: 0xff9d38,
        emissiveIntensity: 1.15,
        roughness: 0.8
      }),
      ground: new THREE.MeshStandardMaterial({
        color: 0x9c8664,
        roughness: 1
      })
    };

    const unitBox = new THREE.BoxGeometry(1, 1, 1);
    const unitCylinder = new THREE.CylinderGeometry(1, 1, 1, 10);
    const rockGeometry = new THREE.DodecahedronGeometry(1, 0);

    function addBox(size, position, material, parent = scene) {
      const mesh = new THREE.Mesh(unitBox, material);
      mesh.scale.set(size[0], size[1], size[2]);
      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function beamBetween(a, b, width, material, parent = scene) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = new THREE.Mesh(unitBox, material);
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.scale.set(width, length, width);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function cylinderBetween(a, b, radius, material, parent = scene) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = new THREE.Mesh(unitCylinder, material);
      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.scale.set(radius, length, radius);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addRock(x, y, z, sx, sy, sz, material = materials.rock) {
      const mesh = new THREE.Mesh(rockGeometry, material);
      mesh.position.set(x, y, z);
      mesh.scale.set(sx, sy, sz);
      mesh.rotation.set(random() * 0.6, random() * Math.PI, random() * 0.4);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      scene.add(mesh);
      return mesh;
    }

    function makePlaque(text) {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 128;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#3f2918";
      ctx.fillRect(0, 0, 256, 128);
      ctx.strokeStyle = "#d4a65f";
      ctx.lineWidth = 7;
      ctx.strokeRect(8, 8, 240, 112);
      ctx.fillStyle = "#f0d39b";
      ctx.font = "bold 68px Georgia";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(text, 128, 67);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;

      return new THREE.Mesh(
        new THREE.PlaneGeometry(0.72, 0.36),
        new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide })
      );
    }

    // -------------------------------------------------------------------------
    // Canyon floor and distant formations
    // -------------------------------------------------------------------------

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(100, 100),
      materials.ground
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.05;
    ground.receiveShadow = true;
    scene.add(ground);

    for (let i = 0; i < 36; i++) {
      const x = -22 + random() * 44;
      const z = -13 + random() * 22;
      if (Math.abs(x) < 13 && z < 5) continue;
      addRock(
        x,
        -0.5 + random() * 0.3,
        z,
        0.45 + random() * 1.3,
        0.35 + random() * 0.8,
        0.5 + random() * 1.4,
        random() > 0.5 ? materials.rockDark : materials.rockLight
      );
    }

    addRock(-24, 3.3, -14, 6, 5, 4, materials.rockDark);
    addRock(24, 4.5, -17, 7, 6.5, 5, materials.rockDark);
    addRock(-17, 1.8, -24, 8, 3.3, 4, materials.rock);
    addRock(18, 2.6, -27, 9, 4.2, 5, materials.rock);

    // -------------------------------------------------------------------------
    // Cliff mass, recesses, and overhang
    // -------------------------------------------------------------------------

    addBox([31, 13.4, 1.4], [0, 5.45, -3.8], materials.rockDark);
    addBox([31.5, 2.5, 4.1], [0, 12.0, -1.15], materials.rock);

    for (let i = 0; i < 23; i++) {
      addRock(
        -15 + i * 1.35,
        11.5 + random() * 1.9,
        -0.8 + random() * 1.2,
        1.2 + random() * 1.5,
        1.1 + random() * 1.5,
        1.5 + random() * 1.8,
        random() > 0.48 ? materials.rock : materials.rockLight
      );
    }

    const pierPositions = [-10.55, -3.45, 3.55, 10.55];

    for (const x of pierPositions) {
      for (const y of [1.2, 3.4, 5.6, 7.8, 10.0]) {
        addRock(
          x + (random() - 0.5) * 0.45,
          y,
          -0.65 + random() * 0.45,
          1.0 + random() * 0.5,
          1.45 + random() * 0.55,
          1.2 + random() * 0.65,
          random() > 0.5 ? materials.rock : materials.rockDark
        );
      }
    }

    // -------------------------------------------------------------------------
    // Three timber-framed dwellings in shallow cliff recesses
    // -------------------------------------------------------------------------

    const roomCenters = [-7, 0, 7];
    const romanNumerals = ["I", "II", "III"];

    roomCenters.forEach((cx, index) => {
      // Recessed back wall and chamber floor.
      addBox([4.45, 3.85, 0.3], [cx, 9.08, -2.67], materials.interior);
      addBox([4.5, 0.22, 3.05], [cx, 7.22, -1.12], materials.darkWood);

      // Warm window recesses.
      for (const offset of [-0.78, 0.78]) {
        addBox([1.13, 1.25, 0.055], [cx + offset, 9.16, -2.48], materials.glow);
        addBox([0.075, 1.28, 0.075], [cx + offset, 9.16, -2.42], materials.darkWood);
        addBox([1.17, 0.075, 0.075], [cx + offset, 9.16, -2.42], materials.darkWood);
      }

      // Main facade timbers.
      addBox([0.22, 3.8, 0.27], [cx - 2.16, 9.05, -0.03], materials.darkWood);
      addBox([0.22, 3.8, 0.27], [cx + 2.16, 9.05, -0.03], materials.darkWood);
      addBox([4.55, 0.28, 0.32], [cx, 10.89, -0.02], materials.darkWood);
      addBox([4.45, 0.2, 0.26], [cx, 7.32, -0.03], materials.darkWood);

      // Side braces and lintel details.
      beamBetween(
        [cx - 2.05, 7.42, 0.09],
        [cx - 1.24, 8.55, 0.09],
        0.15,
        materials.darkWood
      );
      beamBetween(
        [cx + 2.05, 7.42, 0.09],
        [cx + 1.24, 8.55, 0.09],
        0.15,
        materials.darkWood
      );
      beamBetween(
        [cx - 1.85, 10.72, 0.09],
        [cx - 0.7, 9.58, 0.09],
        0.12,
        materials.wood
      );
      beamBetween(
        [cx + 1.85, 10.72, 0.09],
        [cx + 0.7, 9.58, 0.09],
        0.12,
        materials.wood
      );

      // Plaster panels tucked behind the timber frame.
      addBox([0.75, 1.28, 0.15], [cx - 1.44, 9.38, -0.36], materials.plaster);
      addBox([0.75, 1.28, 0.15], [cx + 1.44, 9.38, -0.36], materials.plaster);

      // Small hanging storage vessel.
      const jar = new THREE.Mesh(
        new THREE.CylinderGeometry(0.16, 0.11, 0.34, 10),
        materials.darkWood
      );
      jar.position.set(cx + 1.58, 7.76, -0.48);
      jar.castShadow = true;
      scene.add(jar);

      const plaque = makePlaque(romanNumerals[index]);
      plaque.position.set(cx, 10.52, 0.15);
      scene.add(plaque);
    });

    // -------------------------------------------------------------------------
    // Continuous upper landing and supporting brackets
    // -------------------------------------------------------------------------

    addBox([22.1, 0.35, 1.62], [0, 7.05, 0.73], materials.darkWood);

    for (let x = -10.7; x <= 10.7; x += 0.5) {
      addBox([0.46, 0.06, 1.58], [x, 7.22, 0.73], materials.wood);
    }

    for (let x = -10; x <= 10; x += 2.5) {
      beamBetween(
        [x, 5.62, -0.45],
        [x, 6.9, 1.28],
        0.22,
        materials.darkWood
      );
      addBox([0.28, 0.3, 0.36], [x, 5.62, -0.42], materials.iron);
    }

    // -------------------------------------------------------------------------
    // Lower ledge path, split by the counterweight-door gap
    // -------------------------------------------------------------------------

    const pathLeftStart = -13.05;
    const pathLeftEnd = 3.15;
    const pathRightStart = 5.85;
    const pathRightEnd = 13.05;
    const pathZ = 4.7;

    function buildPathSegment(start, end) {
      const width = end - start;
      const center = (start + end) * 0.5;

      addBox(
        [width, 0.72, 1.62],
        [center, 2.65, pathZ],
        materials.rockDark
      );

      for (let x = start + 0.24; x < end; x += 0.49) {
        addBox(
          [0.45, 0.055, 1.57],
          [x, 3.025, pathZ],
          materials.wood
        );
      }
    }

    buildPathSegment(pathLeftStart, pathLeftEnd);
    buildPathSegment(pathRightStart, pathRightEnd);

    for (let x = -12; x <= 12; x += 3) {
      if (x > 2.7 && x < 6.2) continue;
      beamBetween(
        [x, 0.2, -0.5],
        [x, 2.42, 3.95],
        0.28,
        materials.darkWood
      );
    }

    // Irregular stones beneath the ledge.
    for (let x = -12.5; x <= 12.5; x += 1.7) {
      if (x > 2.5 && x < 6.2) continue;
      addRock(
        x,
        2.15,
        4.05 + random() * 0.25,
        1.05 + random() * 0.5,
        0.65 + random() * 0.45,
        0.8 + random() * 0.45,
        materials.rock
      );
    }

    // Rope railing, interrupted at the door gap.
    const railPosts = [];

    function addRailingPost(x) {
      addBox([0.12, 0.72, 0.12], [x, 3.38, 5.47], materials.darkWood);
      railPosts.push(x);
    }

    [-12, -9, -6, -3, 0, 2.4].forEach(addRailingPost);
    [6.2, 8.5, 10.8, 12.6].forEach(addRailingPost);

    for (let i = 0; i < railPosts.length - 1; i++) {
      const x1 = railPosts[i];
      const x2 = railPosts[i + 1];
      cylinderBetween(
        [x1, 3.69, 5.47],
        [x2, 3.69, 5.47],
        0.027,
        materials.rope
      );
    }

    // -------------------------------------------------------------------------
    // Three retractable timber ladders
    // -------------------------------------------------------------------------

    const ladderXs = [-7, 0, 7];
    const ladders = [];
    const ladderLength = 5.7;
    const deployedAngle = -0.735;

    for (const x of ladderXs) {
      const ladder = new THREE.Group();
      ladder.position.set(x, 7.32, 1.48);
      ladder.rotation.x = deployedAngle;

      // Rails extend downward in local space.
      addBox([0.14, ladderLength, 0.17], [-0.49, -ladderLength / 2, 0], materials.paleWood, ladder);
      addBox([0.14, ladderLength, 0.17], [0.49, -ladderLength / 2, 0], materials.paleWood, ladder);

      // Rungs.
      for (let y = -0.48; y > -ladderLength + 0.2; y -= 0.54) {
        addBox([1.08, 0.115, 0.15], [0, y, 0], materials.wood, ladder);
      }

      // Reinforcing straps and hinge barrel.
      addBox([1.13, 0.13, 0.2], [0, -0.3, 0], materials.iron, ladder);
      addBox([1.13, 0.13, 0.2], [0, -ladderLength + 0.34, 0], materials.iron, ladder);

      const hinge = new THREE.Mesh(
        new THREE.CylinderGeometry(0.15, 0.15, 1.38, 12),
        materials.iron
      );
      hinge.rotation.z = Math.PI / 2;
      hinge.castShadow = true;
      ladder.add(hinge);

      scene.add(ladder);
      ladders.push(ladder);
    }

    // -------------------------------------------------------------------------
    // Counterweighted plank door across the ledge gap
    // -------------------------------------------------------------------------

    const doorGroup = new THREE.Group();
    doorGroup.position.set(3.12, 3.03, pathZ);
    doorGroup.rotation.y = -1.48;

    const doorWidth = 2.7;
    const doorDepth = 1.55;
    const plankCount = 6;
    const plankWidth = doorWidth / plankCount;

    for (let i = 0; i < plankCount; i++) {
      addBox(
        [plankWidth - 0.035, 0.13, doorDepth],
        [plankWidth * (i + 0.5), 0, 0],
        materials.wood,
        doorGroup
      );
    }

    // Cross braces on both sides of the door.
    for (const z of [-0.53, 0.53]) {
      addBox(
        [doorWidth - 0.12, 0.12, 0.14],
        [doorWidth / 2, 0.095, z],
        materials.darkWood,
        doorGroup
      );
    }

    beamBetween(
      [0.13, 0.13, -0.55],
      [doorWidth - 0.13, 0.13, 0.55],
      0.14,
      materials.paleWood,
      doorGroup
    );
    beamBetween(
      [doorWidth - 0.13, 0.13, -0.55],
      [0.13, 0.13, 0.55],
      0.14,
      materials.paleWood,
      doorGroup
    );

    scene.add(doorGroup);

    // Static hinge post and iron straps.
    addBox([0.22, 1.15, 0.28], [3.08, 3.43, pathZ], materials.darkWood);
    addBox([0.36, 0.13, 0.16], [3.16, 3.18, pathZ], materials.iron);
    addBox([0.36, 0.13, 0.16], [3.16, 3.58, pathZ], materials.iron);

    // Pulley mounted on a timber bracket.
    const pulleyPosition = new THREE.Vector3(3.15, 7.36, 2.35);

    beamBetween(
      [3.15, 7.55, -0.3],
      [3.15, 7.55, 2.35],
      0.19,
      materials.darkWood
    );
    beamBetween(
      [3.15, 7.52, 2.35],
      [3.15, 7.15, 2.35],
      0.18,
      materials.darkWood
    );

    const pulley = new THREE.Mesh(
      new THREE.TorusGeometry(0.25, 0.065, 10, 24),
      materials.iron
    );
    pulley.position.copy(pulleyPosition);
    pulley.castShadow = true;
    scene.add(pulley);

    for (let i = 0; i < 4; i++) {
      const spoke = addBox(
        [0.055, 0.43, 0.055],
        [0, 0, 0],
        materials.darkWood
      );
      spoke.position.copy(pulleyPosition);
      spoke.rotation.z = i * Math.PI / 4;
    }

    // Hanging stone counterweight.
    const weightGroup = new THREE.Group();
    weightGroup.position.set(3.15, 5, 2.35);

    addBox([0.66, 0.9, 0.66], [0, 0, 0], materials.rockDark, weightGroup);
    addBox([0.72, 0.09, 0.72], [0, 0.27, 0], materials.iron, weightGroup);
    addBox([0.72, 0.09, 0.72], [0, -0.27, 0], materials.iron, weightGroup);

    const hook = new THREE.Mesh(
      new THREE.TorusGeometry(0.13, 0.035, 8, 18),
      materials.iron
    );
    hook.position.y = 0.52;
    hook.rotation.x = Math.PI / 2;
    weightGroup.add(hook);

    scene.add(weightGroup);

    const doorCable = new THREE.Mesh(
      new THREE.CylinderGeometry(0.027, 0.027, 1, 8),
      materials.rope
    );
    const weightCable = new THREE.Mesh(
      new THREE.CylinderGeometry(0.027, 0.027, 1, 8),
      materials.rope
    );
    doorCable.castShadow = true;
    weightCable.castShadow = true;
    scene.add(doorCable, weightCable);

    let ropeTotalLength = null;

    function setSegment(mesh, start, end) {
      const direction = end.clone().sub(start);
      const length = direction.length();

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.scale.set(1, length, 1);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
    }

    // -------------------------------------------------------------------------
    // Animation timeline
    // -------------------------------------------------------------------------

    const duration = 8.5;
    const ladderSchedule = [
      { start: 0.65, length: 1.25 },
      { start: 2.0, length: 1.25 },
      { start: 3.35, length: 1.25 }
    ];
    const doorSchedule = { start: 4.85, length: 2.2 };

    let timeline = 0;
    let playing = true;

    const scrub = document.getElementById("scrub");
    const playButton = document.getElementById("play");
    const restartButton = document.getElementById("restart");
    const statusText = document.getElementById("status-text");
    const phaseElements = [...document.querySelectorAll("#phases span")];

    function clamp01(value) {
      return Math.min(1, Math.max(0, value));
    }

    function easeInOutCubic(value) {
      return value < 0.5
        ? 4 * value * value * value
        : 1 - Math.pow(-2 * value + 2, 3) / 2;
    }

    function updateDoorRig() {
      doorGroup.updateMatrixWorld(true);

      const attachment = new THREE.Vector3(doorWidth - 0.12, 0.15, 0);
      doorGroup.localToWorld(attachment);

      const diagonalLength = attachment.distanceTo(pulleyPosition);

      if (ropeTotalLength === null) {
        ropeTotalLength = diagonalLength + 1.8;
      }

      const verticalLength = Math.max(0.45, ropeTotalLength - diagonalLength);
      const weightTop = pulleyPosition.y - verticalLength;

      weightGroup.position.set(
        pulleyPosition.x,
        weightTop - 0.45,
        pulleyPosition.z
      );

      setSegment(doorCable, attachment, pulleyPosition);

      setSegment(
        weightCable,
        pulleyPosition,
        new THREE.Vector3(
          weightGroup.position.x,
          weightGroup.position.y + 0.52,
          weightGroup.position.z
        )
      );
    }

    function applyTimeline() {
      ladders.forEach((ladder, index) => {
        const schedule = ladderSchedule[index];
        const raw = clamp01((timeline - schedule.start) / schedule.length);
        const eased = easeInOutCubic(raw);
        ladder.rotation.x = THREE.MathUtils.lerp(deployedAngle, 0.015, eased);
      });

      const doorProgress = clamp01(
        (timeline - doorSchedule.start) / doorSchedule.length
      );
      const doorEase = easeInOutCubic(doorProgress);
      doorGroup.rotation.y = THREE.MathUtils.lerp(-1.48, 0, doorEase);

      updateDoorRig();

      scrub.value = Math.round((timeline / duration) * 1000);
      scrub.style.setProperty("--progress", `${(timeline / duration) * 100}%`);

      let activePhase = 0;
      let text = "Ledges ready";

      if (timeline >= ladderSchedule[0].start && timeline < ladderSchedule[0].start + ladderSchedule[0].length) {
        activePhase = 1;
        text = "Ladder I lifting to the upper landing";
      } else if (timeline >= ladderSchedule[1].start && timeline < ladderSchedule[1].start + ladderSchedule[1].length) {
        activePhase = 2;
        text = "Ladder II lifting to the upper landing";
      } else if (timeline >= ladderSchedule[2].start && timeline < ladderSchedule[2].start + ladderSchedule[2].length) {
        activePhase = 3;
        text = "Ladder III lifting to the upper landing";
      } else if (timeline >= doorSchedule.start && timeline < doorSchedule.start + doorSchedule.length) {
        activePhase = 4;
        text = "Counterweight descending — door closing";
      } else if (timeline >= doorSchedule.start + doorSchedule.length) {
        activePhase = 4;
        text = "Ledge secured — the door is closed";
      } else if (timeline >= 0.6) {
        activePhase = 0;
        text = "Preparing the first ladder";
      }

      phaseElements.forEach((element, index) => {
        element.classList.toggle("active", index === activePhase);
      });

      statusText.textContent = text;
      playButton.textContent = playing
        ? "Pause"
        : timeline >= duration
          ? "Replay"
          : "Resume";
    }

    playButton.addEventListener("click", () => {
      if (timeline >= duration) {
        timeline = 0;
        ropeTotalLength = null;
        playing = true;
      } else {
        playing = !playing;
      }
      applyTimeline();
    });

    restartButton.addEventListener("click", () => {
      timeline = 0;
      ropeTotalLength = null;
      playing = true;
      applyTimeline();
    });

    scrub.addEventListener("input", () => {
      timeline = (Number(scrub.value) / 1000) * duration;
      playing = false;
      applyTimeline();
    });

    // -------------------------------------------------------------------------
    // Custom orbit controls: no addons required
    // -------------------------------------------------------------------------

    const orbit = {
      target: new THREE.Vector3(0, 5.25, 0),
      theta: 0.16,
      phi: 1.18,
      radius: 25
    };

    const pointer = {
      active: false,
      x: 0,
      y: 0
    };

    function updateCamera() {
      const sinPhi = Math.sin(orbit.phi);
      camera.position.set(
        orbit.target.x + orbit.radius * sinPhi * Math.sin(orbit.theta),
        orbit.target.y + orbit.radius * Math.cos(orbit.phi),
        orbit.target.z + orbit.radius * sinPhi * Math.cos(orbit.theta)
      );
      camera.lookAt(orbit.target);
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      pointer.active = true;
      pointer.x = event.clientX;
      pointer.y = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!pointer.active) return;

      const dx = event.clientX - pointer.x;
      const dy = event.clientY - pointer.y;

      orbit.theta -= dx * 0.005;
      orbit.phi = THREE.MathUtils.clamp(orbit.phi - dy * 0.0045, 0.67, 1.47);

      pointer.x = event.clientX;
      pointer.y = event.clientY;
      updateCamera();
    });

    function stopDragging(event) {
      pointer.active = false;
      if (renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", stopDragging);
    renderer.domElement.addEventListener("pointercancel", stopDragging);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        orbit.radius = THREE.MathUtils.clamp(
          orbit.radius + event.deltaY * 0.012,
          15,
          36
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", () => {
      orbit.target.set(0, 5.25, 0);
      orbit.theta = 0.16;
      orbit.phi = 1.18;
      orbit.radius = 25;
      updateCamera();
    });

    // -------------------------------------------------------------------------
    // Resize and render loop
    // -------------------------------------------------------------------------

    addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    });

    updateCamera();
    applyTimeline();

    const loading = document.getElementById("loading");
    loading.classList.add("hidden");
    setTimeout(() => loading.remove(), 550);

    let previousTime = performance.now();

    function animate(now) {
      requestAnimationFrame(animate);

      const delta = Math.min((now - previousTime) / 1000, 0.05);
      previousTime = now;

      if (playing) {
        timeline = Math.min(duration, timeline + delta);
        if (timeline >= duration) {
          playing = false;
        }
        applyTimeline();
      }

      renderer.render(scene, camera);
    }

    requestAnimationFrame(animate);
  </script>
</body>
</html>
