<body>
  <div id="app"></div>

  <section class="panel">
    <div class="eyebrow">Interactive architectural reconstruction</div>
    <h1>Acropolis of Athena</h1>
    <p class="description">
      Explore a sunlit ancient district featuring a Doric temple, monumental
      gateway, and long colonnaded stoa overlooking the surrounding landscape.
    </p>

    <div class="controls">
      <button id="reset">Reset view</button>
      <button data-mood="morning" class="active">Morning</button>
      <button data-mood="dusk">Dusk</button>
    </div>

    <div class="divider"></div>

    <div class="controls">
      <button id="tour">Start tour</button>
      <button id="overview">Overview</button>
      <button id="templeView">Temple</button>
    </div>

    <p class="instructions">
      Drag to orbit · Shift/right-drag to pan · Scroll or pinch to zoom
    </p>
  </section>

  <div class="hotspot" data-anchor="temple">
    <span class="dot"></span><span class="label">Temple of Athena</span>
  </div>

  <div class="hotspot" data-anchor="gateway">
    <span class="dot"></span><span class="label">Sacred Gateway</span>
  </div>

  <div class="hotspot" data-anchor="stoa">
    <span class="dot"></span><span class="label">Northern Stoa</span>
  </div>

  <div class="footer">Drag to explore the ancient acropolis</div>
  <div id="loading">Raising the ancient city…</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene, camera
    // -------------------------------------------------------------------------

    const app = document.querySelector("#app");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    app.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa8cedd);
    scene.fog = new THREE.FogExp2(0xa8cedd, 0.0092);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      240
    );

    const hemisphere = new THREE.HemisphereLight(0xd7efff, 0x6a5940, 1.65);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xffe4b5, 3.25);
    sun.position.set(-18, 29, 16);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -32;
    sun.shadow.camera.right = 32;
    sun.shadow.camera.top = 32;
    sun.shadow.camera.bottom = -32;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 90;
    sun.shadow.bias = -0.00035;
    sun.shadow.normalBias = 0.025;
    scene.add(sun);

    const fillLight = new THREE.DirectionalLight(0xa8c9e8, 0.6);
    fillLight.position.set(22, 12, -22);
    scene.add(fillLight);

    // -------------------------------------------------------------------------
    // Materials
    // -------------------------------------------------------------------------

    const materials = {
      marble: new THREE.MeshStandardMaterial({
        color: 0xe1d2b4,
        roughness: 0.83,
        metalness: 0.02
      }),
      paleStone: new THREE.MeshStandardMaterial({
