  <main id="scene" aria-label="Interactive three-dimensional Fibonacci phyllotaxis scene"></main>

  <section class="title-card">
    <div class="eyebrow">Botanical Geometry / Study 01</div>
    <h1>Fibonacci<br />Phyllotaxis</h1>
    <p class="description">
