<body>
  <div id="loading">Loading level crossing…</div>

  <div id="interface">
    <section id="information" class="panel" aria-live="polite">
      <div class="eyebrow">Railway Systems · Crossing 07</div>
      <h1>Animated Level Crossing</h1>

      <div id="status-row">
