    // -------------------------------------------------------------------------
    // Direct camera controls: orbit and zoom
    // -------------------------------------------------------------------------

    const cameraState = {
      target: new THREE.Vector3(0, 1.55, 0),
      radius: 43,
      theta: 0.67,
      phi: 0.91,
      dragging: false,
      lastX: 0,
      lastY: 0
    };

    const initialCamera = {
      radius: 43,
      theta: 0.67,
      phi: 0.91
    };

    function updateCamera() {
      const { target, radius, theta, phi } = cameraState;
      const horizontal = radius * Math.sin(phi);

      camera.position.set(
        target.x + horizontal * Math.sin(theta),
        target.y + radius * Math.cos(phi),
        target.z + horizontal * Math.cos(theta)
      );

      camera.lookAt(target);
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      cameraState.dragging = true;
      cameraState.lastX = event.clientX;
      cameraState.lastY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!cameraState.dragging) return;

      const deltaX = event.clientX - cameraState.lastX;
      const deltaY = event.clientY - cameraState.lastY;

      cameraState.theta -= deltaX * 0.006;
      cameraState.phi = THREE.MathUtils.clamp(
        cameraState.phi - deltaY * 0.005,
        0.38,
        1.38
      );

      cameraState.lastX = event.clientX;
      cameraState.lastY = event.clientY;
      updateCamera();
    });

    function endCameraDrag(event) {
      cameraState.dragging = false;
      if (renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endCameraDrag);
    renderer.domElement.addEventListener("pointercancel", endCameraDrag);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraState.radius = THREE.MathUtils.clamp(
          cameraState.radius * Math.exp(event.deltaY * 0.001),
          18,
          82
        );
        updateCamera();
      },
      { passive: false }
    );

    updateCamera();

    // -------------------------------------------------------------------------
    // Optional synthesized bell
    // -------------------------------------------------------------------------

    let audioEnabled = false;
    let audioContext = null;

    function ringBell() {
      if (!audioEnabled) return;

      if (!audioContext) {
        const AudioContextClass =
          window.AudioContext || window.webkitAudioContext;

        if (!AudioContextClass) return;
        audioContext = new AudioContextClass();
      }

      if (audioContext.state === "suspended") {
        audioContext.resume();
      }

      const now = audioContext.currentTime;

      for (const frequency of [720, 1080]) {
        const oscillator = audioContext.createOscillator();
        const gain = audioContext.createGain();

        oscillator.type = "sine";
        oscillator.frequency.setValueAtTime(frequency, now);
        oscillator.frequency.exponentialRampToValueAtTime(
          frequency * 0.96,
          now + 0.55
        );

        gain.gain.setValueAtTime(0.0001, now);
        gain.gain.exponentialRampToValueAtTime(
          frequency === 720 ? 0.13 : 0.055,
          now + 0.012
        );
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.7);

        oscillator.connect(gain);
        gain.connect(audioContext.destination);

        oscillator.start(now);
        oscillator.stop(now + 0.72);
      }
    }

    // -------------------------------------------------------------------------
    // UI and crossing state
    // -------------------------------------------------------------------------

    const statusElement = document.querySelector("#status");
    const detailsElement = document.querySelector("#details");
    const statusDot = document.querySelector("#status-dot");
    const barrierState = document.querySelector("#barrier-state");
    const progressElement = document.querySelector("#cycle-progress");

    const testButton = document.querySelector("#test-crossing");
    const bellButton = document.querySelector("#bell-button");
    const pauseButton = document.querySelector("#pause-button");
    const cameraButton = document.querySelector("#camera-button");

    const CYCLE_DURATION = 24;
    let cycleTime = 0;
    let paused = false;
    let lastBellIndex = -1;

    testButton.addEventListener("click", () => {
      cycleTime = 3.65;
      lastBellIndex = -1;
      if (audioEnabled) ringBell();
    });

    bellButton.addEventListener("click", () => {
      audioEnabled = !audioEnabled;

      bellButton.textContent = audioEnabled ? "Bell enabled" : "Enable bell";
      bellButton.classList.toggle("active", audioEnabled);
      bellButton.setAttribute("aria-pressed", String(audioEnabled));

      if (audioEnabled) ringBell();
    });

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
      pauseButton.classList.toggle("active", paused);
    });

    cameraButton.addEventListener("click", () => {
      cameraState.radius = initialCamera.radius;
      cameraState.theta = initialCamera.theta;
      cameraState.phi = initialCamera.phi;
      updateCamera();
    });

    function smoothStep(min, max, value) {
      const x = THREE.MathUtils.clamp((value - min) / (max - min), 0, 1);
      return x * x * (3 - 2 * x);
    }

    function updateCrossing(delta) {
      if (!paused) {
        cycleTime = (cycleTime + delta) % CYCLE_DURATION;
      }

      const t = cycleTime;
      let barrierAmount = 0;
      let warning = false;
      let title = "CLEAR";
      let detail = "Road traffic may proceed.";

      if (t >= 3.8 && t < 19.2) {
        warning = true;
      }

      if (t < 4) {
        barrierAmount = 0;
      } else if (t < 7) {
        barrierAmount = smoothStep(4, 7, t);
        title = "BARRIERS CLOSING";
        detail = "Warning lamps and bell are active.";
      } else if (t < 15) {
        barrierAmount = 1;
        title = t < 10.5 ? "TRAIN APPROACHING" : "TRAIN CROSSING";
        detail = "Keep the crossing clear. Gates remain locked down.";
      } else if (t < 19) {
        barrierAmount = 1 - smoothStep(15, 19, t);
        title = "BARRIERS OPENING";
        detail = "The train has passed. Half-barriers are rising.";
      } else {
        barrierAmount = 0;
        title = "CLEAR";
        detail = "Road traffic may proceed.";
      }

      // Smooth, mechanically convincing barrier rotation.
      for (const arm of barrierArms) {
        arm.rotation.z = barrierAmount * Math.PI * 0.5;
      }

      // Train movement.
      if (t >= 6.7 && t < 14.8) {
        const progress = (t - 6.7) / (14.8 - 6.7);
        train.position.x = THREE.MathUtils.lerp(-42, 45, progress);
        train.visible = true;
      } else {
        train.visible = false;
      }

      for (const wheel of trainWheels) {
        wheel.rotation.y -= delta * 12;
      }

      // Alternating red lamps. Every mast uses the same synchronized pair.
      const flashIndex = Math.floor(Math.max(0, t - 3.8) / 0.43) % 2;

      for (const lamp of signalLamps) {
        const isOn = warning && lamp.index === flashIndex;

        lamp.material.emissiveIntensity = isOn ? 5.5 : 0.025;
        lamp.material.color.setHex(isOn ? 0xff1717 : 0x4b0909);
        lamp.haloMaterial.opacity = isOn ? 0.88 : 0;
        lamp.halo.scale.setScalar(isOn ? 1.45 : 0.8);

        if (lamp.warningLight) {
          lamp.warningLight.intensity = isOn ? 5.5 : 0;
        }
      }

      // Bell housing vibration.
      const bellPhase = warning ? (t - 3.8) % 1.15 : 0;
      const bellMotion = warning
        ? Math.sin(bellPhase * Math.PI * 12) * Math.exp(-bellPhase * 5)
        : 0;

      for (const bell of bellHousings) {
        bell.rotation.z = bellMotion * 0.055;
        bell.position.y = 5.02 + Math.abs(bellMotion) * 0.025;
      }

      // Audio bell pulses.
      if (warning) {
        const bellIndex = Math.floor((t - 3.8) / 1.15);
        if (bellIndex !== lastBellIndex) {
          lastBellIndex = bellIndex;
          ringBell();
        }
      } else {
        lastBellIndex = -1;
      }

      // UI.
      statusElement.textContent = title;
      detailsElement.textContent = detail;

      const warningColor = warning ? "#ef4444" : "#4ade80";
      statusDot.style.background = warningColor;
      statusDot.style.boxShadow = `0 0 13px ${warningColor}`;

      barrierState.textContent =
        barrierAmount > 0.985
          ? "Barriers lowered"
          : barrierAmount < 0.015
            ? "Barriers raised"
            : "Barriers moving";

      progressElement.style.width = `${(t / CYCLE_DURATION) * 100}%`;
    }

    // -------------------------------------------------------------------------
    // Resize and animation loop
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    const clock = new THREE.Clock();

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      updateCrossing(delta);
      renderer.render(scene, camera);
    }

    renderer.setAnimationLoop(animate);

    loading.classList.add("hidden");
    setTimeout(() => loading.remove(), 350);
  </script>
</body>
</html>
