      <h1>Automated Welding Workcell</h1>
      <div class="subtitle">6-axis robot · dual positioners · fume extraction</div>
    </section>

    <section class="status-card">
      <div class="status-row">
        <span class="status-label">Process state</span>
        <span id="statusValue" class="status-value ready">SYSTEM READY</span>
      </div>
