    </div>

    <div class="help">Drag to orbit · Wheel to zoom · Double-click to reset view</div>

    <div class="controls">
      <button id="orbitButton" class="active" title="Toggle automatic camera orbit">Orbit</button>
      <button id="pauseButton" title="Pause or resume the workcell">Pause</button>
      <button id="resetButton" title="Reset camera view">Reset</button>
    </div>
  </div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // ---------------------------------------------------------------------
    // Renderer and scene
    // ---------------------------------------------------------------------

    const canvas = document.querySelector("#scene");
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.18;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x091016);
    scene.fog = new THREE.Fog(0x091016, 15, 31);

    const camera = new THREE.PerspectiveCamera(
      44,
      window.innerWidth / window.innerHeight,
      0.1,
      70
    );

    const clock = new THREE.Clock();
    const Y_AXIS = new THREE.Vector3(0, 1, 0);
    const Z_AXIS = new THREE.Vector3(0, 0, 1);

    // ---------------------------------------------------------------------
    // Materials and geometry helpers
    // ---------------------------------------------------------------------

    const material = (color, roughness = 0.6, metalness = 0.15, extra = {}) =>
      new THREE.MeshStandardMaterial({
        color,
        roughness,
        metalness,
        ...extra
      });

    const M = {
      floor: material(0x172029, 0.88, 0.18),
      platform: material(0x202b34, 0.75, 0.32),
      wall: material(0x17212a, 0.86, 0.12),
      wallInset: material(0x101820, 0.8, 0.22),
      steel: material(0x9aabb6, 0.3, 0.82),
      brushed: material(0x60717c, 0.42, 0.72),
      darkSteel: material(0x27333c, 0.42, 0.75),
      black: material(0x10161b, 0.56, 0.5),
      rubber: material(0x080b0d, 0.9, 0.05),
      orange: material(0xf16b24, 0.34, 0.42),
      orangeLight: material(0xff8b38, 0.28, 0.4),
      yellow: material(0xf1b92e, 0.48, 0.3),
      white: material(0xd5dde0, 0.42, 0.35),
      copper: material(0xc77736, 0.28, 0.78),
      cyan: material(0x4bc9ef, 0.24, 0.5, {
        emissive: 0x167b99,
        emissiveIntensity: 1.4
      }),
      amber: material(0xff9a31, 0.2, 0.15, {
        emissive: 0xff6b12,
        emissiveIntensity: 2.4
      }),
      green: material(0x44dc9a, 0.25, 0.2, {
        emissive: 0x16885b,
        emissiveIntensity: 1.8
      }),
      glass: material(0x628a8c, 0.25, 0.12, {
        transparent: true,
        opacity: 0.2,
        side: THREE.DoubleSide,
        depthWrite: false
      })
    };

    function addMesh(geometry, mat, parent = scene) {
      const mesh = new THREE.Mesh(geometry, mat);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function box(w, h, d, mat, x = 0, y = 0, z = 0, parent = scene) {
      const mesh = addMesh(new THREE.BoxGeometry(w, h, d), mat, parent);
      mesh.position.set(x, y, z);
      return mesh;
    }

    function cylinder(rt, rb, h, mat, x = 0, y = 0, z = 0, parent = scene, segments = 32) {
      const mesh = addMesh(
        new THREE.CylinderGeometry(rt, rb, h, segments),
        mat,
        parent
      );
      mesh.position.set(x, y, z);
      return mesh;
    }

    function torus(radius, tube, mat, x = 0, y = 0, z = 0, parent = scene) {
      const mesh = addMesh(
        new THREE.TorusGeometry(radius, tube, 10, 48),
        mat,
        parent
      );
      mesh.position.set(x, y, z);
      return mesh;
    }

    function cylinderBetween(a, b, radius, mat, parent = scene, segments = 20) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = addMesh(
        new THREE.CylinderGeometry(radius, radius, length, segments),
        mat,
        parent
      );

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.normalize());
      return mesh;
    }

    function beamBetween(a, b, width, depth, mat, parent = scene) {
      const start = new THREE.Vector3(...a);
      const end = new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = addMesh(
        new THREE.BoxGeometry(width, length, depth),
        mat,
        parent
      );

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.normalize());
      return mesh;
    }

    function makeLabelTexture(title, subtitle = "", accent = "#58d7ff") {
      const c = document.createElement("canvas");
      c.width = 1024;
      c.height = 192;

      const ctx = c.getContext("2d");
      const gradient = ctx.createLinearGradient(0, 0, c.width, c.height);
      gradient.addColorStop(0, "#101b24");
      gradient.addColorStop(1, "#071017");

      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, c.width, c.height);

      ctx.fillStyle = accent;
      ctx.fillRect(0, 0, 12, c.height);
      ctx.fillRect(48, 35, 6, 122);

      ctx.textBaseline = "middle";
      ctx.fillStyle = "#dceaf2";
      ctx.font = "700 54px system-ui, sans-serif";
      ctx.fillText(title, 84, 72);

      if (subtitle) {
        ctx.fillStyle = "#7893a4";
        ctx.font = "600 26px system-ui, sans-serif";
        ctx.fillText(subtitle, 85, 132);
      }

      const texture = new THREE.CanvasTexture(c);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    // ---------------------------------------------------------------------
    // Lighting
    // ---------------------------------------------------------------------

    scene.add(new THREE.HemisphereLight(0xb8dcf4, 0x171b1e, 1.45));

    const keyLight = new THREE.DirectionalLight(0xfff0dc, 3.2);
    keyLight.position.set(5, 10, 7);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -11;
    keyLight.shadow.camera.right = 11;
    keyLight.shadow.camera.top = 10;
    keyLight.shadow.camera.bottom = -8;
    keyLight.shadow.camera.near = 1;
    keyLight.shadow.camera.far = 28;
    keyLight.shadow.bias = -0.00025;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x56c8ff, 1.3);
    rimLight.position.set(-8, 5, -6);
    scene.add(rimLight);

    const hoodLight = new THREE.SpotLight(0xd8edff, 95, 14, Math.PI / 3.4, 0.48, 1.5);
    hoodLight.position.set(0, 4.05, 0.6);
    hoodLight.target.position.set(0, 0, 0);
    hoodLight.castShadow = true;
    hoodLight.shadow.mapSize.set(1024, 1024);
    scene.add(hoodLight, hoodLight.target);

    const cyanFill = new THREE.PointLight(0x38c6ff, 24, 9, 2);
    cyanFill.position.set(-3.8, 2.2, 2.2);
    scene.add(cyanFill);

    // ---------------------------------------------------------------------
    // Building shell, floor markings, wall and safety fencing
    // ---------------------------------------------------------------------

    box(28, 0.18, 20, M.floor, 0, -0.2, 0);

    const platform = box(12.2, 0.18, 7.1, M.platform, 0, -0.08, 0);
    platform.receiveShadow = true;

    const grid = new THREE.GridHelper(24, 48, 0x456475, 0x2a3b47);
    grid.position.y = -0.095;
    grid.material.transparent = true;
    grid.material.opacity = 0.18;
    scene.add(grid);

    // Cell boundary.
    box(12.0, 0.025, 0.12, M.yellow, 0, 0.025, 3.45);
    box(0.12, 0.025, 6.8, M.yellow, -6.0, 0.025, 0);
    box(0.12, 0.025, 6.8, M.yellow, 6.0, 0.025, 0);

    for (let i = 0; i < 24; i++) {
      box(
        0.19,
        0.031,
        0.13,
        M.black,
        -5.6 + i * 0.48,
        0.042,
        3.45
      );
    }

    // Rear wall panels.
    box(15.5, 6.2, 0.22, M.wall, 0, 3.0, -4.95);

    for (let i = -3; i <= 3; i++) {
