    // Inverse kinematics for the shoulder, elbow and base yaw.
    function solveRobotIK(target) {
      const dx = target.x - robotRoot.position.x;
      const dz = target.z - robotRoot.position.z;
      const radial = Math.max(0.001, Math.hypot(dx, dz));

      const wristY = target.y + TORCH_LENGTH;
      const vertical = wristY - SHOULDER_Y;
      const distance = Math.hypot(radial, vertical);

      const elbowCos = THREE.MathUtils.clamp(
        (distance * distance - L1 * L1 - L2 * L2) / (2 * L1 * L2),
        -1,
        1
      );

      const elbowAngle = Math.acos(elbowCos);
      const targetPhi = Math.atan2(vertical, radial);
      const angleOffset = Math.atan2(
        L2 * Math.sin(elbowAngle),
        L1 + L2 * Math.cos(elbowAngle)
      );
      const shoulderAngle = Math.PI / 2 - targetPhi - angleOffset;

      yawGroup.rotation.y = -Math.atan2(dz, dx);
      shoulderPivot.rotation.z = -shoulderAngle;
      elbowPivot.rotation.z = -elbowAngle;

      // Counter-rotate the wrist so the torch remains vertical.
      wristPivot.rotation.z = shoulderAngle + elbowAngle;
    }

