    const currentTip = new THREE.Vector3();

    function spawnSpark(origin) {
      for (let i = 0; i < SPARK_COUNT; i++) {
        if (sparkLife[i] > 0) continue;

        sparkLife[i] = 0.3 + Math.random() * 0.75;
        const index = i * 3;

        sparkPositions[index] = origin.x;
        sparkPositions[index + 1] = origin.y;
        sparkPositions[index + 2] = origin.z;

        sparkVelocities[i].set(
          (Math.random() - 0.5) * 3.2,
          0.8 + Math.random() * 2.9,
          (Math.random() - 0.5) * 3.2
        );

        return;
      }
    }

    function updateSparks(dt, welding) {
      let spawnBudget = welding ? dt * 135 : 0;

      while (spawnBudget >= 1) {
        spawnSpark(currentTip);
        spawnBudget--;
      }

      for (let i = 0; i < SPARK_COUNT; i++) {
        const index = i * 3;

        if (sparkLife[i] <= 0) {
          sparkPositions[index] = 999;
          sparkPositions[index + 1] = 999;
          sparkPositions[index + 2] = 999;
          continue;
        }

        sparkLife[i] -= dt;

        const velocity = sparkVelocities[i];
        velocity.y -= 6.4 * dt;
        velocity.multiplyScalar(1 - dt * 0.7);

        sparkPositions[index] += velocity.x * dt;
        sparkPositions[index + 1] += velocity.y * dt;
        sparkPositions[index + 2] += velocity.z * dt;

        if (sparkPositions[index + 1] < 0.035) {
          sparkPositions[index + 1] = 0.035;
          velocity.y = Math.abs(velocity.y) * 0.28;
          velocity.x *= 0.65;
          velocity.z *= 0.65;
        }

        const intensity = Math.max(0, sparkLife[i]);
        sparkColors[index] = 1;
        sparkColors[index + 1] = 0.25 + intensity * 0.65;
        sparkColors[index + 2] = Math.max(0, intensity - 0.55) * 0.45;
      }

      sparkGeometry.attributes.position.needsUpdate = true;
      sparkGeometry.attributes.color.needsUpdate = true;
    }

    function updateSmoke(dt, welding, origin) {
      for (const particle of smokeParticles) {
        particle.life -= dt;

        if (particle.life <= 0) {
          if (welding && Math.random() < 0.16) {
            particle.life = particle.maxLife = 1.4 + Math.random() * 1.4;
            particle.sprite.position.copy(origin);
            particle.sprite.position.x += (Math.random() - 0.5) * 0.16;
            particle.sprite.position.z += (Math.random() - 0.5) * 0.16;

            particle.velocity.set(
              (Math.random() - 0.5) * 0.16,
              0.5 + Math.random() * 0.3,
              (Math.random() - 0.5) * 0.13
            );
          } else {
            particle.sprite.material.opacity = 0;
            continue;
          }
        }

        const age = 1 - particle.life / particle.maxLife;
        particle.sprite.position.addScaledVector(particle.velocity, dt);
        particle.velocity.y += dt * 0.035;

        const scale = 0.2 + age * 0.95;
        particle.sprite.scale.set(scale, scale, scale);
        particle.sprite.material.opacity = Math.sin(age * Math.PI) * 0.105;
      }
    }

    // ---------------------------------------------------------------------
    // Process cycle
    // ---------------------------------------------------------------------

    const statusValue = document.querySelector("#statusValue");
    const progressFill = document.querySelector("#progressFill");

    const CYCLE_LENGTH = 14;

    function getCycle(time) {
      const cycle = time % CYCLE_LENGTH;

      if (cycle < 4.5) {
        return {
          mode: "weldA",
          progress: cycle / CYCLE_LENGTH,
          label: "WELDING / POSITIONER A"
        };
      }

      if (cycle < 6.2) {
        const t = (cycle - 4.5) / 1.7;
        return {
          mode: "toB",
          progress: cycle / CYCLE_LENGTH,
          transfer: t,
          label: "TRANSFER / APPROACH B"
        };
      }

      if (cycle < 10.7) {
        return {
          mode: "weldB",
          progress: cycle / CYCLE_LENGTH,
          label: "WELDING / POSITIONER B"
        };
      }

      if (cycle < 12.4) {
        const t = (cycle - 10.7) / 1.7;
        return {
          mode: "toA",
          progress: cycle / CYCLE_LENGTH,
          transfer: t,
          label: "TRANSFER / APPROACH A"
        };
      }

      return {
        mode: "weldA",
        progress: cycle / CYCLE_LENGTH,
        label: "WELDING / POSITIONER A"
      };
    }

    const smoothstep = (t) => t * t * (3 - 2 * t);
    const robotTarget = new THREE.Vector3();

    function updateWorkcell(time) {
      positionerA.rotor.rotation.y = time * 0.58;
      positionerB.rotor.rotation.y = -time * 0.52;

      positionerA.rotor.updateWorldMatrix(true, false);
      positionerB.rotor.updateWorldMatrix(true, false);

      const targetA = positionerA.getTarget(time);
      const targetB = positionerB.getTarget(time);
      const cycle = getCycle(time);

      let welding = false;

      if (cycle.mode === "weldA") {
        robotTarget.copy(targetA);
        welding = true;
      } else if (cycle.mode === "weldB") {
        robotTarget.copy(targetB);
        welding = true;
      } else {
        const t = smoothstep(cycle.transfer);
        robotTarget.lerpVectors(targetA, targetB, t);
        robotTarget.y += Math.sin(t * Math.PI) * 0.45;
        robotTarget.z += Math.sin(t * Math.PI) * 0.2;
      }

      solveRobotIK(robotTarget);

      scene.updateMatrixWorld(true);
      torchTip.getWorldPosition(currentTip);

      arcSprite.visible = welding;
      arcLight.intensity = welding ? 22 + Math.random() * 12 : 0;

      if (welding) {
        const pulse = 0.38 + Math.random() * 0.27;
        arcSprite.scale.setScalar(pulse);
        arcSprite.material.opacity = 0.65 + Math.random() * 0.35;
      }

      updateSparks(1 / 60, welding);
      updateSmoke(1 / 60, welding, currentTip);

      statusValue.textContent = cycle.label;
      statusValue.className = "status-value";

      if (cycle.mode.startsWith("weld")) {
        statusValue.classList.add("ready");
      } else {
        statusValue.classList.add("transfer");
      }

      progressFill.style.width = `${cycle.progress * 100}%`;
    }

    // ---------------------------------------------------------------------
    // Custom camera controls: orbit, zoom, reset and optional auto orbit
    // ---------------------------------------------------------------------

    const cameraState = {
      theta: 0.69,
      phi: 0.96,
      radius: 11.4,
      target: new THREE.Vector3(0, 1.65, 0.05)
    };

    let autoOrbit = true;
    let paused = false;
    let dragging = false;
    let lastPointerX = 0;
    let lastPointerY = 0;

    const orbitButton = document.querySelector("#orbitButton");
    const pauseButton = document.querySelector("#pauseButton");

    function updateCamera(dt) {
      if (autoOrbit && !dragging) {
        cameraState.theta += dt * 0.045;
      }

      const sinPhi = Math.sin(cameraState.phi);

      camera.position.set(
        cameraState.target.x + cameraState.radius * sinPhi * Math.sin(cameraState.theta),
        cameraState.target.y + cameraState.radius * Math.cos(cameraState.phi),
        cameraState.target.z + cameraState.radius * sinPhi * Math.cos(cameraState.theta)
      );

      camera.lookAt(cameraState.target);
    }

    function resetCamera() {
      cameraState.theta = 0.69;
      cameraState.phi = 0.96;
      cameraState.radius = 11.4;
      cameraState.target.set(0, 1.65, 0.05);
    }

    function setAutoOrbit(value) {
      autoOrbit = value;
      orbitButton.classList.toggle("active", value);
    }

    function setPaused(value) {
      paused = value;
      pauseButton.textContent = value ? "Resume" : "Pause";
      pauseButton.classList.toggle("active", value);
    }

    orbitButton.addEventListener("click", () => {
      setAutoOrbit(!autoOrbit);
    });

    pauseButton.addEventListener("click", () => {
      setPaused(!paused);
    });

    document.querySelector("#resetButton").addEventListener("click", resetCamera);

    canvas.addEventListener("pointerdown", (event) => {
      dragging = true;
      lastPointerX = event.clientX;
      lastPointerY = event.clientY;
      canvas.setPointerCapture(event.pointerId);
      setAutoOrbit(false);
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const dx = event.clientX - lastPointerX;
      const dy = event.clientY - lastPointerY;

      lastPointerX = event.clientX;
      lastPointerY = event.clientY;

      cameraState.theta -= dx * 0.006;
      cameraState.phi = THREE.MathUtils.clamp(
        cameraState.phi - dy * 0.005,
        0.34,
        1.38
      );
    });

    function endDrag(event) {
      dragging = false;
      if (canvas.hasPointerCapture(event.pointerId)) {
        canvas.releasePointerCapture(event.pointerId);
      }
    }

    canvas.addEventListener("pointerup", endDrag);
    canvas.addEventListener("pointercancel", endDrag);
    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraState.radius = THREE.MathUtils.clamp(
          cameraState.radius * Math.exp(event.deltaY * 0.001),
          7.1,
          18
        );
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetCamera);

    window.addEventListener("keydown", (event) => {
      if (event.code === "Space") {
        event.preventDefault();
        setPaused(!paused);
      }

      if (event.key.toLowerCase() === "r") {
        resetCamera();
      }

      if (event.key.toLowerCase() === "o") {
        setAutoOrbit(!autoOrbit);
      }
    });

    // ---------------------------------------------------------------------
    // Resize and animation loop
    // ---------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    let simulationTime = 0;
    let firstFrame = true;

    function animate() {
      requestAnimationFrame(animate);

      const realDelta = Math.min(clock.getDelta(), 0.05);
      const simulationDelta = paused ? 0 : realDelta;
      simulationTime += simulationDelta;

      updateWorkcell(simulationTime);
      updateCamera(realDelta);
      renderer.render(scene, camera);

      if (firstFrame) {
        firstFrame = false;
        document.querySelector("#loading").classList.add("hide");
      }
    }

    updateCamera(0);
    animate();
  </script>
</body>
</html>
