    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05080d);
    scene.fog = new THREE.Fog(0x05080d, 34, 110);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      220
    );

    // Custom camera controls; no examples/addons are used.
    const view = {
      theta: 0.88,
      phi: 1.08,
      radius: 20.5,
      target: new THREE.Vector3(1.7, 2.15, 0),
      dragging: false,
      panning: false,
      lastX: 0,
      lastY: 0,
      pointerId: null
    };

    function updateCamera() {
      const sinPhi = Math.sin(view.phi);
      const cosPhi = Math.cos(view.phi);

      camera.position.set(
        view.target.x + view.radius * sinPhi * Math.sin(view.theta),
        view.target.y + view.radius * cosPhi,
        view.target.z + view.radius * sinPhi * Math.cos(view.theta)
      );

      camera.lookAt(view.target);
    }

    function resetCamera() {
      view.theta = 0.88;
      view.phi = 1.08;
      view.radius = 20.5;
      view.target.set(1.7, 2.15, 0);
      updateCamera();
    }

    updateCamera();

    const canvas = renderer.domElement;

    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    canvas.addEventListener("pointerdown", (event) => {
      view.dragging = true;
      view.panning = event.button === 2 || event.shiftKey;
      view.lastX = event.clientX;
      view.lastY = event.clientY;
      view.pointerId = event.pointerId;
      canvas.setPointerCapture(event.pointerId);
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!view.dragging || event.pointerId !== view.pointerId) return;

      const dx = event.clientX - view.lastX;
      const dy = event.clientY - view.lastY;

      view.lastX = event.clientX;
      view.lastY = event.clientY;

      if (view.panning) {
        const forward = new THREE.Vector3()
          .subVectors(view.target, camera.position)
          .normalize();

        const right = new THREE.Vector3()
          .crossVectors(forward, new THREE.Vector3(0, 1, 0))
          .normalize();

        const up = new THREE.Vector3()
          .crossVectors(right, forward)
          .normalize();

        const panScale = view.radius * 0.00135;

        view.target.addScaledVector(right, -dx * panScale);
        view.target.addScaledVector(up, dy * panScale);
      } else {
        view.theta -= dx * 0.006;
        view.phi = THREE.MathUtils.clamp(view.phi - dy * 0.005, 0.22, 1.48);
      }

      updateCamera();
    });

    function endPointer(event) {
      if (event.pointerId !== view.pointerId) return;

      view.dragging = false;
      view.panning = false;
      view.pointerId = null;

      if (canvas.hasPointerCapture(event.pointerId)) {
        canvas.releasePointerCapture(event.pointerId);
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        view.radius = THREE.MathUtils.clamp(
          view.radius * Math.exp(event.deltaY * 0.001),
          8,
          42
        );
        updateCamera();
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetCamera);

    // -------------------------------------------------------------------------
    // Materials and reusable geometry helpers
    // -------------------------------------------------------------------------

    const materials = {
      hull: new THREE.MeshStandardMaterial({
        color: 0x8e9ca2,
        metalness: 0.62,
        roughness: 0.4
      }),
      paleHull: new THREE.MeshStandardMaterial({
        color: 0xc4ced1,
        metalness: 0.58,
        roughness: 0.33
      }),
      dark: new THREE.MeshStandardMaterial({
        color: 0x202a31,
        metalness: 0.72,
        roughness: 0.4
      }),
      black: new THREE.MeshStandardMaterial({
        color: 0x0b1014,
        metalness: 0.45,
        roughness: 0.65
      }),
      orange: new THREE.MeshStandardMaterial({
        color: 0xe4942e,
        metalness: 0.42,
        roughness: 0.36
      }),
      yellow: new THREE.MeshStandardMaterial({
        color: 0xf0c451,
        metalness: 0.38,
        roughness: 0.34
      }),
      silver: new THREE.MeshStandardMaterial({
        color: 0xbfc9cd,
        metalness: 0.8,
        roughness: 0.25
      }),
      cable: new THREE.MeshStandardMaterial({
        color: 0xaab7bd,
        metalness: 0.85,
        roughness: 0.28
      }),
      leadCable: new THREE.MeshStandardMaterial({
        color: 0x39464d,
        metalness: 0.6,
        roughness: 0.45
      }),
      cargo: new THREE.MeshStandardMaterial({
        color: 0x435c54,
        metalness: 0.3,
        roughness: 0.62
      })
    };

    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const UP = V(0, 1, 0);

    function addBox(parent, size, position, material) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(size[0], size[1], size[2]),
        material
      );

      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);

      return mesh;
    }

    function addCylinder(
      parent,
      radiusTop,
      radiusBottom,
      height,
      position,
      material,
      segments = 24
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          height,
          segments
        ),
        material
      );

      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);

      return mesh;
    }

    function setRod(mesh, a, b, radius) {
      const direction = new THREE.Vector3().subVectors(b, a);
      const length = direction.length();

      mesh.position.copy(a).add(b).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(UP, direction.normalize());
      mesh.scale.set(radius, length, radius);
    }

    function addRod(parent, a, b, radius, material, segments = 10) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(1, 1, 1, segments),
        material
      );

      setRod(mesh, a, b, radius);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);

      return mesh;
    }

    function addSphere(parent, radius, position, material) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(radius, 18, 12),
        material
      );

      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);

      return mesh;
    }

    function addEdges(mesh, color = 0x1b252a, opacity = 0.62) {
      const edgeMaterial = new THREE.LineBasicMaterial({
        color,
        transparent: true,
        opacity
      });

      const edges = new THREE.LineSegments(
        new THREE.EdgesGeometry(mesh.geometry, 25),
        edgeMaterial
      );

      edges.position.copy(mesh.position);
      edges.rotation.copy(mesh.rotation);
      edges.scale.copy(mesh.scale);
      mesh.parent.add(edges);

      return edges;
    }

    // -------------------------------------------------------------------------
    // Lunar environment
    // -------------------------------------------------------------------------

    let randomSeed = 74621;

    function random() {
      randomSeed = (randomSeed * 1664525 + 1013904223) >>> 0;
      return randomSeed / 4294967296;
    }

    const terrainGeometry = new THREE.PlaneGeometry(110, 110, 70, 70);
    const terrainPosition = terrainGeometry.attributes.position;
    const terrainColors = [];

    const lowColor = new THREE.Color(0x555c60);
    const highColor = new THREE.Color(0x85898a);

    for (let i = 0; i < terrainPosition.count; i++) {
      const x = terrainPosition.getX(i);
      const y = terrainPosition.getY(i);

      const height =
        Math.sin(x * 0.13) * 0.07 +
        Math.cos(y * 0.16) * 0.06 +
        Math.sin((x + y) * 0.07) * 0.055 +
        (random() - 0.5) * 0.025;

      terrainPosition.setZ(i, height);

      const color = lowColor.clone().lerp(highColor, THREE.MathUtils.clamp(
        height * 4.2 + 0.45,
        0,
        1
      ));

      terrainColors.push(color.r, color.g, color.b);
    }

    terrainGeometry.setAttribute(
      "color",
      new THREE.Float32BufferAttribute(terrainColors, 3)
    );

    terrainGeometry.rotateX(-Math.PI / 2);
    terrainGeometry.computeVertexNormals();

    const terrain = new THREE.Mesh(
      terrainGeometry,
      new THREE.MeshStandardMaterial({
        vertexColors: true,
        roughness: 1,
        metalness: 0,
        flatShading: true
      })
    );

    terrain.receiveShadow = true;
    scene.add(terrain);

    function addCrater(x, z, radius) {
      const crater = new THREE.Group();
      crater.position.set(x, 0.09, z);

      const floor = new THREE.Mesh(
        new THREE.CircleGeometry(radius * 0.87, 48),
        new THREE.MeshStandardMaterial({
          color: 0x353b3e,
          roughness: 1
        })
      );

      floor.rotation.x = -Math.PI / 2;
      floor.receiveShadow = true;
      crater.add(floor);

      const rim = new THREE.Mesh(
        new THREE.TorusGeometry(radius, radius * 0.09, 8, 48),
        new THREE.MeshStandardMaterial({
          color: 0x747a7c,
          roughness: 1
        })
      );

      rim.rotation.x = Math.PI / 2;
      rim.position.y = 0.025;
      rim.receiveShadow = true;
      crater.add(rim);

      scene.add(crater);
    }

    addCrater(8.5, -6.5, 1.7);
    addCrater(-7.5, 5.5, 1.15);
    addCrater(12, 8, 2.3);
    addCrater(-13, -8, 2.8);

    const rockMaterial = new THREE.MeshStandardMaterial({
      color: 0x666c6e,
      roughness: 1,
      metalness: 0,
      flatShading: true
    });

    for (let i = 0; i < 42; i++) {
      const angle = random() * Math.PI * 2;
      const distance = 6 + random() * 35;
      const size = 0.09 + random() * 0.48;

      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(size, 0),
        rockMaterial
      );

      rock.position.set(
        Math.cos(angle) * distance,
        size * 0.4,
        Math.sin(angle) * distance
      );

      rock.rotation.set(random() * 3, random() * 3, random() * 3);
      rock.scale.set(1, 0.65 + random() * 0.55, 0.8 + random() * 0.6);
      rock.castShadow = true;
      rock.receiveShadow = true;
      scene.add(rock);
    }

    // Star field.
    const starPositions = [];

    for (let i = 0; i < 1000; i++) {
      const theta = random() * Math.PI * 2;
      const phi = Math.acos(random() * 0.92 + 0.04);
      const radius = 55 + random() * 40;

      starPositions.push(
        radius * Math.sin(phi) * Math.cos(theta),
        radius * Math.cos(phi),
        radius * Math.sin(phi) * Math.sin(theta)
      );
    }

    const starGeometry = new THREE.BufferGeometry();
    starGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(starPositions, 3)
    );

    const stars = new THREE.Points(
      starGeometry,
      new THREE.PointsMaterial({
        color: 0xdde9f4,
        size: 0.13,
        sizeAttenuation: true,
        transparent: true,
        opacity: 0.88
      })
    );

    scene.add(stars);

    // Procedural Earth texture.
    const earthCanvas = document.createElement("canvas");
    earthCanvas.width = 1024;
    earthCanvas.height = 512;

    const earthContext = earthCanvas.getContext("2d");
    const oceanGradient = earthContext.createLinearGradient(
      0,
      0,
      0,
      512
    );

    oceanGradient.addColorStop(0, "#2d6ea8");
    oceanGradient.addColorStop(0.55, "#174f82");
    oceanGradient.addColorStop(1, "#123d67");

    earthContext.fillStyle = oceanGradient;
    earthContext.fillRect(0, 0, 1024, 512);

    earthContext.fillStyle = "#718967";

    for (let i = 0; i < 28; i++) {
      const x = random() * 1024;
      const y = random() * 512;
      const radius = 12 + random() * 50;

      earthContext.beginPath();

      for (let p = 0; p < 9; p++) {
        const a = (p / 9) * Math.PI * 2;
        const r = radius * (0.45 + random() * 0.55);
        const px = x + Math.cos(a) * r;
        const py = y + Math.sin(a) * r * 0.62;

        if (p === 0) earthContext.moveTo(px, py);
        else earthContext.lineTo(px, py);
      }

      earthContext.closePath();
      earthContext.fill();
    }

    earthContext.fillStyle = "rgba(255,255,255,0.62)";

    for (let i = 0; i < 50; i++) {
      earthContext.beginPath();
      earthContext.ellipse(
        random() * 1024,
        random() * 512,
        5 + random() * 25,
        2 + random() * 8,
        random() * 0.5,
        0,
        Math.PI * 2
      );
      earthContext.fill();
    }

    const earthTexture = new THREE.CanvasTexture(earthCanvas);
    earthTexture.colorSpace = THREE.SRGBColorSpace;

    const earth = new THREE.Mesh(
      new THREE.SphereGeometry(3.25, 48, 32),
      new THREE.MeshStandardMaterial({
        map: earthTexture,
        roughness: 0.95,
        metalness: 0,
