      48
    );

    // -------------------------------------------------------------------------
    // Slewing upper assembly
    // -------------------------------------------------------------------------

    const slew = new THREE.Group();
    slew.position.y = 1.48;
    crane.add(slew);

    addCylinder(
      slew,
      1.17,
      1.17,
