    );
    weightEye.position.set(-1.08, 1.48, 0);
    weightEye.rotation.y = Math.PI / 2;
    weightEye.castShadow = true;
    slew.add(weightEye);

    // A-frame pivot supports.
    for (const side of [-1, 1]) {
      addRod(
        slew,
        V(-0.02, 0.32, side * 0.58),
        V(0.7, 0.82, side * 0.36),
