      );
      flange.rotation.x = Math.PI / 2;
    }

    // Helical winding makes the drum rotation easy to see.
    const coilPoints = [];

    for (let i = 0; i <= 190; i++) {
      const u = i / 190;
      const angle = u * Math.PI * 2 * 12;
      coilPoints.push(
