        0.022,
        6,
        false
      ),
      materials.leadCable
    );

    coil.castShadow = true;
    drum.add(coil);

    // A colored flange marker makes the drum rotation visible.
    addBox(
      drum,
      [0.68, 0.075, 0.035],
      [0.19, 0, 0.555],
      materials.orange
    );

    addSphere(
      drum,
