      [0.44, 0, 0.565],
      materials.yellow
    );

    const winchAnchor = new THREE.Object3D();
    winchAnchor.position.set(-0.2, 1.18, 0.68);
    slew.add(winchAnchor);

    // -------------------------------------------------------------------------
    // Three nested telescoping boom sections
    // -------------------------------------------------------------------------

    const boomMount = new THREE.Group();
    boomMount.position.set(0.7, 0.82, 0);
    slew.add(boomMount);

    // Fixed guide housing around the first sliding section.
    addBox(
      boomMount,
      [1.2, 0.79, 0.8],
      [0.25, 0, 0],
