    );

    const pivotAxle = addCylinder(
      boomMount,
      0.18,
      0.18,
      1.18,
      [0, 0, 0],
      materials.dark,
      24
    );
    pivotAxle.rotation.x = Math.PI / 2;

    function makeBoomSection(parent, length, height, width, material) {
      const section = new THREE.Group();
      parent.add(section);

      const beam = addBox(
        section,
        [length, height, width],
        [length * 0.5, 0, 0],
        material
      );
      addEdges(beam);

      addBox(
        section,
        [length - 0.08, 0.065, width + 0.035],
        [length * 0.5, height * 0.5 + 0.033, 0],
        materials.yellow
      );

      addBox(
        section,
        [0.15, height + 0.12, width + 0.12],
        [length - 0.075, 0, 0],
        materials.dark
      );

      addBox(
        section,
        [0.07, height + 0.14, width + 0.14],
        [0.035, 0, 0],
        materials.silver
      );

      return section;
    }

