    leadPoints[4].position.set(3.65, 0.28, 0);
    boom3.add(leadPoints[4]);

    leadPoints[5].position.set(4.84, 0.2, 0);
    boom3.add(leadPoints[5]);

    const leadSegments = Array.from({ length: leadPoints.length - 1 }, () =>
      createDynamicCable(materials.leadCable)
    );

    const worldA = new THREE.Vector3();
    const worldB = new THREE.Vector3();
    const midpoint = new THREE.Vector3();
    const direction = new THREE.Vector3();

    function updateCable(mesh, a, b, radius) {
      direction.subVectors(b, a);
      const length = direction.length();

      midpoint.copy(a).add(b).multiplyScalar(0.5);
      mesh.position.copy(midpoint);
      mesh.quaternion.setFromUnitVectors(UP, direction.normalize());
      mesh.scale.set(radius, length, radius);
    }

    // -------------------------------------------------------------------------
    // Animation timeline
    // -------------------------------------------------------------------------

    const DURATION = 16;
    let elapsed = 0;
    let paused = false;
    let simulationSpeed = 1;
    let drumAngle = 0;
    let previousPayout = null;
    let palletInitialized = false;

    const statusElement = document.getElementById("status");
    const progressElement = document.getElementById("progress");

    function clamp01(value) {
      return Math.max(0, Math.min(1, value));
    }

    function smoothRange(time, start, end) {
      const t = clamp01((time - start) / (end - start));
      return t * t * (3 - 2 * t);
    }

    function mix(a, b, t) {
      return a + (b - a) * t;
    }

    function getAnimationState(time) {
      let boom1Amount;
      let boom2Amount;
      let boom3Amount;

      if (time < 13.6) {
        boom1Amount = smoothRange(time, 1.0, 2.4);
        boom2Amount = smoothRange(time, 2.4, 3.8);
        boom3Amount = smoothRange(time, 3.8, 5.2);
      } else {
        boom3Amount = 1 - smoothRange(time, 13.6, 14.7);
        boom2Amount = 1 - smoothRange(time, 14.7, 15.4);
        boom1Amount = 1 - smoothRange(time, 15.4, 16.0);
      }

      let slewAngle;

      if (time < 5.2) {
        slewAngle = -0.68;
      } else if (time < 7.8) {
        slewAngle = mix(
          -0.68,
          0.88,
          smoothRange(time, 5.2, 7.8)
        );
      } else if (time < 11.2) {
        slewAngle = 0.88;
      } else if (time < 13.6) {
        slewAngle = mix(
          0.88,
          -0.68,
          smoothRange(time, 11.2, 13.6)
        );
      } else {
        slewAngle = -0.68;
      }

      let liftAmount;

      if (time < 5.2) {
        liftAmount = 0;
      } else if (time < 7.8) {
        liftAmount = mix(
          0,
          0.42,
          smoothRange(time, 5.2, 7.8)
        );
      } else if (time < 9.2) {
        liftAmount = mix(
          0.42,
          1,
          smoothRange(time, 7.8, 9.2)
        );
      } else if (time < 11.2) {
        liftAmount = 1;
      } else if (time < 13.6) {
        liftAmount = 1 - smoothRange(time, 11.2, 13.6);
      } else {
        liftAmount = 0;
      }

      return {
        boom1Amount,
        boom2Amount,
        boom3Amount,
        slewAngle,
        liftAmount
      };
    }

    function getStatus(time) {
      if (time < 1.0) return "STOWED · SYSTEM HOLD";
      if (time < 2.4) return "BOOM 01 · FIRST-STAGE DEPLOY";
      if (time < 3.8) return "BOOM 02 · SECOND-STAGE DEPLOY";
      if (time < 5.2) return "BOOM 03 · INNER SECTION DEPLOY";
      if (time < 7.8) return "SLEW DRIVE · CROSS-BASE TRAVERSE";
      if (time < 9.2) return "WINCH · PALLET ASCENT";
      if (time < 11.2) return "HOIST · LOAD HOLD";
      if (time < 13.6) return "RETURN · SLEW AND LOWER";
      if (time < 14.7) return "BOOM 03 · RETRACTION";
      if (time < 15.4) return "BOOM 02 · RETRACTION";
      return "BOOM 01 · STOWING";
    }

    function updateCrane(time, delta) {
      const state = getAnimationState(time);

      boom1.position.x = mix(0, 0.75, state.boom1Amount);
      boom2.position.x = mix(0.35, 2.35, state.boom2Amount);
      boom3.position.x = mix(0.3, 1.7, state.boom3Amount);

      slew.rotation.y = state.slewAngle;
      boomMount.rotation.z = 0.2 + state.liftAmount * 0.12;

      // The pallet follows beneath the slewing tip with a small inertial lag.
      scene.updateMatrixWorld(true);

      const tipPosition = new THREE.Vector3();
      tipReference.getWorldPosition(tipPosition);

      const followAmount = 1 - Math.exp(-delta * 5.5);

      if (!palletInitialized) {
        pallet.position.x = tipPosition.x;
        pallet.position.z = tipPosition.z;
        pallet.rotation.y = state.slewAngle;
        palletInitialized = true;
      } else {
        pallet.position.x = THREE.MathUtils.lerp(
          pallet.position.x,
          tipPosition.x,
          followAmount
        );

        pallet.position.z = THREE.MathUtils.lerp(
          pallet.position.z,
          tipPosition.z,
          followAmount
        );

        let angleDifference =
          state.slewAngle - pallet.rotation.y;

        angleDifference = Math.atan2(
          Math.sin(angleDifference),
          Math.cos(angleDifference)
        );

        pallet.rotation.y += angleDifference * followAmount;
      }

      pallet.position.y = 0.025 + state.liftAmount * 3.05;

      pallet.rotation.z =
        Math.sin(elapsed * 1.7) * 0.022 * state.liftAmount;

      pallet.rotation.x =
        Math.cos(elapsed * 1.35) * 0.014 * state.liftAmount;

      scene.updateMatrixWorld(true);

      // Update the four pallet hoist cables.
      let totalPayout = 0;

      for (let i = 0; i < 4; i++) {
        tipAnchors[i].getWorldPosition(worldA);
        palletAnchors[i].getWorldPosition(worldB);

        updateCable(hoistCables[i], worldA, worldB, 0.023);
        totalPayout += worldA.distanceTo(worldB);
      }

      const payout = totalPayout / 4;

      if (previousPayout !== null) {
        drumAngle += (payout - previousPayout) * 2.8;
      }

      previousPayout = payout;
      drum.rotation.z = drumAngle;

      // Update the routed drum-to-tip lead line.
      for (let i = 0; i < leadSegments.length; i++) {
        leadPoints[i].getWorldPosition(worldA);
        leadPoints[i + 1].getWorldPosition(worldB);
        updateCable(leadSegments[i], worldA, worldB, 0.022);
      }

      statusElement.textContent = getStatus(time);
      progressElement.style.width = `${(time / DURATION) * 100}%`;
    }

    // -------------------------------------------------------------------------
    // Interface controls
    // -------------------------------------------------------------------------

    const pauseButton = document.getElementById("pause");
    const speedInput = document.getElementById("speed");
    const speedValue = document.getElementById("speed-value");

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
    });

    document
      .getElementById("reset-view")
      .addEventListener("click", resetCamera);

    speedInput.addEventListener("input", () => {
      simulationSpeed = Number(speedInput.value);
      speedValue.textContent = `${simulationSpeed.toFixed(2).replace(/0$/, "")}×`;
    });

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    // -------------------------------------------------------------------------
    // Render loop
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();
    let firstFrame = true;

    renderer.setAnimationLoop(() => {
      const delta = Math.min(clock.getDelta(), 0.05);

      if (!paused) {
        elapsed = (elapsed + delta * simulationSpeed) % DURATION;
      }

      updateCrane(elapsed, delta);
      renderer.render(scene, camera);

      if (firstFrame) {
        firstFrame = false;
        boot.classList.add("hidden");
        setTimeout(() => boot.remove(), 500);
      }
    });
  </script>
</body>
</html>
