      color: rgba(234, 239, 229, 0.8);
      background: rgba(13, 24, 23, 0.5);
      backdrop-filter: blur(10px);
      font: inherit;
      font-size: 11px;
      cursor: pointer;
      transition:
        border-color 160ms ease,
        background 160ms ease,
        transform 160ms ease;
    }

    button:hover {
      border-color: rgba(218, 225, 215, 0.46);
      background: rgba(27, 43, 41, 0.75);
    }

    button:active {
      transform: translateY(1px);
    }

    @media (max-width: 640px) {
      .subtitle {
        max-width: 220px;
        line-height: 1.5;
      }

      .footer {
        left: 20px;
        justify-content: space-between;
      }
    }
  </style>
</head>

<body>
  <div id="stage"></div>
  <div id="vignette"></div>

  <div id="hud">
    <div class="title">
      <div class="eyebrow">Specimen 01 · Hemiptera</div>
      <h1>Cicada forewing</h1>
      <p class="subtitle">Translucent membrane and branching vein network</p>
    </div>

    <div class="footer">
      <span>Drag to orbit · Scroll to zoom · Double-click to reset</span>
      <button id="reset" type="button">Reset view</button>
    </div>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const stage = document.getElementById("stage");
    const hud = document.getElementById("hud");
    const resetButton = document.getElementById("reset");

    // -------------------------------------------------------------------------
    // Renderer, scene, and camera
    // -------------------------------------------------------------------------

    let renderer;

    try {
      renderer = new THREE.WebGLRenderer({
        antialias: true,
        powerPreference: "high-performance"
      });
    } catch (error) {
      stage.innerHTML = `
        <div style="padding:2rem;color:#eee;font:14px system-ui">
          WebGL could not be initialized in this browser.
        </div>
      `;
      throw error;
    }

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional cicada forewing"
    );
    renderer.domElement.tabIndex = 0;
    stage.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a1212);
    scene.fog = new THREE.FogExp2(0x0a1212, 0.034);

    const camera = new THREE.PerspectiveCamera(
      32,
      window.innerWidth / window.innerHeight,
      0.05,
      80
    );

    // -------------------------------------------------------------------------
    // Procedural textures
    // -------------------------------------------------------------------------

    function makeGroundTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 1024;

      const context = canvas.getContext("2d");
      const gradient = context.createRadialGradient(
        512,
        512,
        20,
        512,
        512,
        510
      );

      gradient.addColorStop(0, "#34433e");
      gradient.addColorStop(0.38, "#23312f");
      gradient.addColorStop(0.72, "#13201f");
      gradient.addColorStop(1, "#080f0f");

      context.fillStyle = gradient;
      context.fillRect(0, 0, 1024, 1024);

      for (let i = 0; i < 7000; i++) {
        const value = Math.random() > 0.5 ? 255 : 0;
        context.fillStyle = `rgba(${value},${value},${value},0.018)`;
        context.fillRect(
          Math.random() * 1024,
          Math.random() * 1024,
          1,
          1
        );
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.offset.x = -0.1;
      texture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );

      return texture;
    }

    function makeMembraneTextures() {
      const width = 1024;
      const height = 256;

      const colorCanvas = document.createElement("canvas");
      colorCanvas.width = width;
      colorCanvas.height = height;

      const colorContext = colorCanvas.getContext("2d");
      const colorImage = colorContext.createImageData(width, height);

      const alphaCanvas = document.createElement("canvas");
      alphaCanvas.width = 512;
      alphaCanvas.height = 256;

      const alphaContext = alphaCanvas.getContext("2d");
      const alphaImage = alphaContext.createImageData(512, 256);

      for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
          const index = (y * width + x) * 4;

          const grain = (Math.random() - 0.5) * 12;
          const fiber = Math.sin(x * 0.16 + Math.sin(y * 0.035) * 1.6) * 3.0;
          const cloud =
            Math.sin(x * 0.018 + y * 0.027) * 3.5 +
            Math.sin(x * 0.006 - y * 0.052) * 2.5;

          const value = THREE.MathUtils.clamp(
            232 + grain + fiber + cloud,
            202,
            255
          );

          colorImage.data[index] = value;
          colorImage.data[index + 1] = value * 0.982;
          colorImage.data[index + 2] = value * 0.928;
          colorImage.data[index + 3] = 255;
        }
      }

      for (let y = 0; y < 256; y++) {
        for (let x = 0; x < 512; x++) {
          const index = (y * 512 + x) * 4;

          const mottling =
            Math.sin(x * 0.022 + Math.sin(y * 0.031) * 2.0) * 15 +
            (Math.random() - 0.5) * 17;

          const value = THREE.MathUtils.clamp(
            224 + mottling,
            182,
            255
          );

          alphaImage.data[index] = value;
          alphaImage.data[index + 1] = value;
          alphaImage.data[index + 2] = value;
          alphaImage.data[index + 3] = 255;
        }
      }

      colorContext.putImageData(colorImage, 0, 0);
      alphaContext.putImageData(alphaImage, 0, 0);

      const colorTexture = new THREE.CanvasTexture(colorCanvas);
      colorTexture.colorSpace = THREE.SRGBColorSpace;
      colorTexture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );

      const alphaTexture = new THREE.CanvasTexture(alphaCanvas);
      alphaTexture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );

      return { colorTexture, alphaTexture };
    }

    // -------------------------------------------------------------------------
    // Ground and lighting
    // -------------------------------------------------------------------------

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(30, 30),
      new THREE.MeshStandardMaterial({
        map: makeGroundTexture(),
        color: 0xffffff,
        roughness: 1,
        metalness: 0
      })
    );

    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.055;
    ground.receiveShadow = true;
    scene.add(ground);

    scene.add(
      new THREE.HemisphereLight(0xdce7df, 0x24150d, 1.75)
    );

    const keyLight = new THREE.DirectionalLight(0xffdfa8, 3.15);
    keyLight.position.set(-2.5, 8, 4.5);
    keyLight.target.position.set(3, 0, 0);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -7;
    keyLight.shadow.camera.right = 7;
    keyLight.shadow.camera.top = 7;
    keyLight.shadow.camera.bottom = -7;
    keyLight.shadow.camera.near = 1;
    keyLight.shadow.camera.far = 22;
    keyLight.shadow.bias = -0.0007;
    keyLight.shadow.normalBias = 0.012;
    keyLight.shadow.radius = 4;
    scene.add(keyLight, keyLight.target);

    const fillLight = new THREE.DirectionalLight(0x76aaa2, 1.35);
    fillLight.position.set(7, 4, -5);
    scene.add(fillLight);

    const rimLight = new THREE.PointLight(0xffbd67, 10, 13, 2);
    rimLight.position.set(4.2, 1.5, -2.5);
    scene.add(rimLight);

    // -------------------------------------------------------------------------
    // Wing outline and membrane
    // Local XY is the wing plane; local +Z becomes world +Y after rotation.
    // -------------------------------------------------------------------------

    const wingGroup = new THREE.Group();
    wingGroup.rotation.x = -Math.PI / 2;
    scene.add(wingGroup);

    const wingShape = new THREE.Shape();
    wingShape.moveTo(0, 0);

    wingShape.bezierCurveTo(
      0.23, 0.24,
      0.72, 0.55,
      1.35, 0.77
    );

    wingShape.bezierCurveTo(
      2.16, 1.04,
      3.38, 1.13,
      4.42, 0.96
    );

    wingShape.bezierCurveTo(
      5.15, 0.83,
      5.78, 0.49,
      6.25, 0.08
    );

    wingShape.bezierCurveTo(
      5.91, -0.25,
      5.58, -0.55,
      5.12, -0.73
    );

    wingShape.bezierCurveTo(
      4.35, -1.01,
      3.18, -1.10,
      2.05, -0.91
    );

    wingShape.bezierCurveTo(
      1.04, -0.74,
      0.36, -0.39,
      0, -0.02
    );

    wingShape.closePath();

    const membraneGeometry = new THREE.ShapeGeometry(wingShape, 64);
    const membranePositions = membraneGeometry.getAttribute("position");

    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;

    for (let i = 0; i < membranePositions.count; i++) {
      minX = Math.min(minX, membranePositions.getX(i));
      maxX = Math.max(maxX, membranePositions.getX(i));
      minY = Math.min(minY, membranePositions.getY(i));
      maxY = Math.max(maxY, membranePositions.getY(i));
    }

    const membraneUV = new Float32Array(
      membranePositions.count * 2
    );

    for (let i = 0; i < membranePositions.count; i++) {
      membraneUV[i * 2] =
        (membranePositions.getX(i) - minX) / (maxX - minX);
      membraneUV[i * 2 + 1] =
        (membranePositions.getY(i) - minY) / (maxY - minY);
    }

    membraneGeometry.setAttribute(
      "uv",
      new THREE.BufferAttribute(membraneUV, 2)
    );

    const membraneTextures = makeMembraneTextures();

    const membraneMaterial = new THREE.MeshPhysicalMaterial({
      color: 0xd8b97b,
      map: membraneTextures.colorTexture,
      alphaMap: membraneTextures.alphaTexture,
      transparent: true,
      opacity: 0.56,
      roughness: 0.43,
      metalness: 0,
      side: THREE.DoubleSide,
      depthWrite: false,
      clearcoat: 0.18,
      clearcoatRoughness: 0.55,
      sheen: 0.32,
      sheenColor: new THREE.Color(0xffd99b),
      sheenRoughness: 0.6,
      specularIntensity: 0.65,
      emissive: new THREE.Color(0x2b190b),
      emissiveIntensity: 0.12
    });

    const membrane = new THREE.Mesh(
      membraneGeometry,
      membraneMaterial
    );

    membrane.receiveShadow = true;
    membrane.renderOrder = 1;
    wingGroup.add(membrane);

    // -------------------------------------------------------------------------
    // Curve helpers
    // -------------------------------------------------------------------------

    function makeCurve(points) {
      return new THREE.CatmullRomCurve3(
        points.map(
          (point) => new THREE.Vector3(point[0], point[1], 0)
        ),
        false,
        "centripetal",
        0.5
      );
    }

    function pointAtX(curve, targetX) {
      const samples = 600;
      let previous = curve.getPointAt(0);

      if (Math.abs(previous.x - targetX) < 0.00001) {
        return previous.clone();
      }

      for (let i = 1; i <= samples; i++) {
        const current = curve.getPointAt(i / samples);

        const crosses =
          (targetX >= previous.x && targetX <= current.x) ||
          (targetX <= previous.x && targetX >= current.x);

        if (crosses) {
          const denominator = current.x - previous.x;

          if (Math.abs(denominator) < 0.000001) {
            return current.clone();
          }

          const amount = (targetX - previous.x) / denominator;
          return previous.clone().lerp(current, amount);
        }

        previous = current;
      }

      return curve.getPointAt(1).clone();
    }

    function organicBridge(
      curveA,
      xA,
      curveB,
      xB,
      variation = 0
    ) {
      const a = pointAtX(curveA, xA);
      const b = pointAtX(curveB, xB);

      const first = a.clone().lerp(b, 0.32);
      first.x += 0.026 * Math.sin(variation * 1.71);
      first.y += 0.014 * Math.cos(variation * 1.23);

      const second = a.clone().lerp(b, 0.69);
      second.x -= 0.022 * Math.cos(variation * 1.41);
      second.y += 0.011 * Math.sin(variation * 1.93);

      return makeCurve([
        [a.x, a.y],
        [first.x, first.y],
        [second.x, second.y],
        [b.x, b.y]
      ]);
    }

    // -------------------------------------------------------------------------
    // Flat, subtly raised vein ribbons
    // -------------------------------------------------------------------------

    const veinMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      vertexColors: true,
      roughness: 0.39,
      metalness: 0.035,
      emissive: new THREE.Color(0x130702),
      emissiveIntensity: 0.18,
      side: THREE.DoubleSide
    });

    function makeRibbon(
      curve,
      widthStart,
      widthEnd,
      z,
      edgeColor,
      centerColor,
      ridge = 0.006,
      segments = 72
    ) {
      const positions = [];
      const colors = [];
      const indices = [];
      const uvs = [];

      const profile = [
        { offset: -1, height: 0, mix: 0 },
        { offset: -0.55, height: 0.48, mix: 0.55 },
        { offset: 0, height: 1, mix: 1 },
        { offset: 0.55, height: 0.48, mix: 0.55 },
        { offset: 1, height: 0, mix: 0 }
      ];

      const edge = new THREE.Color(edgeColor);
      const center = new THREE.Color(centerColor);

      for (let i = 0; i <= segments; i++) {
        const t = i / segments;
        const smoothT = t * t * (3 - 2 * t);
        const centerPoint = curve.getPointAt(t);
        const tangent = curve.getTangentAt(t).normalize();

        const side = new THREE.Vector3(
          -tangent.y,
          tangent.x,
          0
        ).normalize();

        const width = THREE.MathUtils.lerp(
          widthStart,
          widthEnd,
          smoothT
        );

        for (let j = 0; j < profile.length; j++) {
          const row = profile[j];

          const position = centerPoint
            .clone()
            .addScaledVector(side, row.offset * width * 0.5);

          position.z = z + row.height * ridge;

          positions.push(
            position.x,
            position.y,
            position.z
          );

          const color = edge.clone().lerp(center, row.mix);
          colors.push(color.r, color.g, color.b);
          uvs.push(t, row.offset * 0.5 + 0.5);
        }
      }

      for (let i = 0; i < segments; i++) {
        for (let j = 0; j < profile.length - 1; j++) {
          const a = i * profile.length + j;
          const b = (i + 1) * profile.length + j;
          const c = (i + 1) * profile.length + j + 1;
          const d = i * profile.length + j + 1;

          indices.push(a, b, d);
          indices.push(b, c, d);
        }
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(positions, 3)
      );
      geometry.setAttribute(
        "color",
        new THREE.Float32BufferAttribute(colors, 3)
      );
      geometry.setAttribute(
        "uv",
        new THREE.Float32BufferAttribute(uvs, 2)
      );
      geometry.setIndex(indices);
      geometry.computeVertexNormals();

      const mesh = new THREE.Mesh(geometry, veinMaterial);
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      return mesh;
    }

    // -------------------------------------------------------------------------
    // Main radial veins
    // -------------------------------------------------------------------------

    const primaryDefinitions = [
      {
        points: [
          [0.00, 0.00],
          [0.30, 0.13],
          [0.78, 0.31],
          [1.40, 0.49],
          [2.25, 0.62],
          [3.25, 0.67],
          [4.25, 0.58],
          [5.15, 0.37],
          [5.95, 0.06]
        ]
      },
      {
        points: [
          [0.02, 0.00],
          [0.34, 0.05],
          [0.90, 0.12],
          [1.65, 0.16],
          [2.55, 0.15],
          [3.50, 0.08],
          [4.50, -0.02],
          [5.35, -0.22],
          [5.75, -0.14]
        ]
      },
      {
        points: [
          [0.01, -0.01],
          [0.35, -0.08],
          [0.88, -0.19],
          [1.60, -0.28],
          [2.45, -0.36],
          [3.40, -0.45],
          [4.40, -0.54],
          [5.25, -0.57],
          [5.75, -0.37]
        ]
      },
      {
        points: [
          [0.00, -0.02],
          [0.33, -0.17],
          [0.85, -0.30],
          [1.55, -0.43],
          [2.40, -0.58],
          [3.35, -0.70],
          [4.35, -0.77],
          [5.18, -0.64],
          [5.72, -0.36]
        ]
      },
      {
        points: [
          [0.00, -0.03],
          [0.28, -0.26],
          [0.78, -0.42],
          [1.45, -0.61],
          [2.30, -0.78],
          [3.25, -0.90],
          [4.15, -0.92],
          [4.85, -0.78],
          [5.30, -0.57]
        ]
      }
    ];

    const primaryCurves = primaryDefinitions.map(
      (definition) => makeCurve(definition.points)
    );

    primaryCurves.forEach((curve, index) => {
      const widthStart = 0.034 - index * 0.0012;
      const widthEnd = 0.012 - index * 0.0006;

      const vein = makeRibbon(
        curve,
        widthStart,
        widthEnd,
        0.010 + index * 0.001,
        0x301408,
        0x814b29,
        0.008,
        96
      );

      wingGroup.add(vein);
    });

    // -------------------------------------------------------------------------
    // Irregular cross-veins
    // More cross-veins occur near the leading edge, producing larger,
    // more open cells toward the trailing edge.
    // -------------------------------------------------------------------------

    const crossVeinRows = [
      [
        [0.25, 0.34],
        [0.52, 0.70],
        [1.08, 1.28],
        [1.95, 2.15],
        [2.92, 3.10],
        [3.88, 4.02],
        [4.72, 4.86],
        [5.38, 5.50]
      ],
      [
        [0.27, 0.36],
        [0.62, 0.80],
        [1.18, 1.45],
        [2.02, 2.28],
        [2.94, 3.20],
        [3.90, 4.12],
        [4.74, 4.96]
      ],
      [
        [0.28, 0.38],
        [0.70, 0.92],
        [1.30, 1.58],
        [2.18, 2.48],
        [3.08, 3.38],
        [3.98, 4.28],
        [4.84, 5.02]
      ],
      [
        [0.24, 0.35],
        [0.92, 1.12],
        [1.88, 2.18],
        [2.90, 3.25],
        [3.98, 4.38]
      ]
    ];

    let bridgeIndex = 0;

    crossVeinRows.forEach((row, rowIndex) => {
      row.forEach(([xA, xB]) => {
        const bridge = organicBridge(
          primaryCurves[rowIndex],
          xA,
          primaryCurves[rowIndex + 1],
          xB,
          bridgeIndex++
        );

        const width = 0.0145 - rowIndex * 0.0007;

        const crossVein = makeRibbon(
          bridge,
          width,
          width * 0.68,
          0.018,
          0x3d1c0e,
          0x7b4827,
          0.0045,
          42
        );

        wingGroup.add(crossVein);
      });
    });

    // -------------------------------------------------------------------------
    // Leading and trailing margins
    // -------------------------------------------------------------------------

    const leadingCurve = makeCurve([
      [0.00, 0.00],
      [0.20, 0.21],
      [0.72, 0.52],
      [1.35, 0.77],
      [2.18, 0.99],
      [3.35, 1.10],
      [4.42, 0.96],
      [5.12, 0.79],
      [5.78, 0.46],
      [6.25, 0.08]
    ]);

    const trailingCurve = makeCurve([
      [0.00, -0.01],
      [0.35, -0.37],
      [1.05, -0.70],
      [2.05, -0.91],
      [3.18, -1.10],
      [4.35, -1.01],
      [5.12, -0.73],
      [5.60, -0.47],
      [6.25, 0.08]
    ]);

    // Short costal and marginal veinlets.
    [0.82, 1.48, 2.28, 3.12, 4.00, 5.05].forEach(
      (x, index) => {
        const bridge = organicBridge(
          primaryCurves[0],
          x,
          leadingCurve,
          x,
          20 + index
        );

        wingGroup.add(
          makeRibbon(
            bridge,
            0.009,
            0.006,
            0.021,
            0x45200f,
            0x89512d,
            0.003,
            30
          )
        );
      }
    );

    [0.95, 1.90, 2.90, 4.05].forEach((x, index) => {
      const bridge = organicBridge(
        primaryCurves[4],
        x,
        trailingCurve,
        x,
        40 + index
      );

      wingGroup.add(
        makeRibbon(
          bridge,
          0.009,
          0.006,
          0.021,
          0x421d0e,
          0x7e4927,
          0.003,
          30
        )
      );
    });

    // Small forks break up the otherwise longitudinal cells.
    [
      [0, 1.95, 2, 2.28],
      [1, 2.94, 3, 3.38],
      [2, 1.30, 4, 2.18]
    ].forEach(([aIndex, xA, bIndex, xB], index) => {
      const branch = organicBridge(
        primaryCurves[aIndex],
        xA,
        primaryCurves[bIndex],
        xB,
        70 + index
      );

      wingGroup.add(
        makeRibbon(
          branch,
          0.008,
          0.006,
          0.024,
          0x4a230f,
          0x88502b,
          0.003,
          40
        )
      );
    });

    // A very fine trailing rim, deliberately much thinner than the costa.
    wingGroup.add(
      makeRibbon(
        trailingCurve,
        0.013,
        0.006,
        0.006,
        0x4a2615,
        0x754225,
        0.003,
        120
      )
    );

    // -------------------------------------------------------------------------
    // Tapered, thickened leading edge
    // -------------------------------------------------------------------------

    function makeTaperedTube(
      curve,
      radiusAt,
      tubularSegments = 120,
      radialSegments = 10,
      zOffset = 0.012
    ) {
      const frames = curve.computeFrenetFrames(
        tubularSegments,
        false
      );

      const positions = [];
      const normals = [];
      const uvs = [];
      const indices = [];

      for (let i = 0; i <= tubularSegments; i++) {
        const t = i / tubularSegments;
        const center = curve.getPointAt(t);
        const radius = radiusAt(t);

        const normal = frames.normals[i];
        const binormal = frames.binormals[i];

        for (let j = 0; j <= radialSegments; j++) {
          const angle = (j / radialSegments) * Math.PI * 2;
          const cosine = Math.cos(angle);
          const sine = Math.sin(angle);

          const radial = normal
            .clone()
            .multiplyScalar(cosine)
            .addScaledVector(binormal, sine)
            .normalize();

          const position = center
            .clone()
            .addScaledVector(radial, radius);

          position.z += zOffset;

          positions.push(
            position.x,
            position.y,
            position.z
          );

          normals.push(
            radial.x,
            radial.y,
            radial.z
          );

          uvs.push(j / radialSegments, t);
        }
      }

      for (let i = 0; i < tubularSegments; i++) {
        for (let j = 0; j < radialSegments; j++) {
          const a = i * (radialSegments + 1) + j;
          const b = (i + 1) * (radialSegments + 1) + j;
          const c = (i + 1) * (radialSegments + 1) + j + 1;
          const d = i * (radialSegments + 1) + j + 1;

          indices.push(a, b, d);
          indices.push(b, c, d);
        }
      }

      const startCenterIndex = positions.length / 3;
      const start = curve.getPointAt(0);
      const startTangent = curve.getTangentAt(0).multiplyScalar(-1);

      positions.push(
        start.x,
        start.y,
        start.z + zOffset
      );
      normals.push(
        startTangent.x,
        startTangent.y,
        startTangent.z
      );
      uvs.push(0.5, 0);

      for (let j = 0; j < radialSegments; j++) {
        indices.push(
          startCenterIndex,
          (j + 1) % radialSegments,
          j
        );
      }

      const endCenterIndex = positions.length / 3;
      const end = curve.getPointAt(1);
      const endTangent = curve.getTangentAt(1);

      positions.push(
        end.x,
        end.y,
        end.z + zOffset
      );
      normals.push(
        endTangent.x,
        endTangent.y,
        endTangent.z
      );
      uvs.push(0.5, 1);

      const endRingStart = tubularSegments * (radialSegments + 1);

      for (let j = 0; j < radialSegments; j++) {
        indices.push(
          endCenterIndex,
          endRingStart + j,
          endRingStart + j + 1
        );
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(positions, 3)
      );
      geometry.setAttribute(
        "normal",
        new THREE.Float32BufferAttribute(normals, 3)
      );
      geometry.setAttribute(
        "uv",
        new THREE.Float32BufferAttribute(uvs, 2)
      );
      geometry.setIndex(indices);
      geometry.computeBoundingSphere();

      return geometry;
    }

    const edgeMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x704323,
      roughness: 0.33,
      metalness: 0.025,
      clearcoat: 0.58,
      clearcoatRoughness: 0.27,
      emissive: new THREE.Color(0x180802),
      emissiveIntensity: 0.12,
      side: THREE.DoubleSide
    });

    const leadingEdge = new THREE.Mesh(
      makeTaperedTube(
        leadingCurve,
        (t) => THREE.MathUtils.lerp(
          0.060,
          0.018,
          Math.pow(t, 0.82)
        ),
        140,
        10,
        0.012
      ),
      edgeMaterial
    );

    leadingEdge.castShadow = true;
    leadingEdge.receiveShadow = true;
    wingGroup.add(leadingEdge);

    // A small flattened basal node visually gathers the radial veins.
    const baseNode = new THREE.Mesh(
      new THREE.SphereGeometry(1, 20, 14),
      edgeMaterial
    );

    baseNode.position.set(0.015, -0.008, 0.012);
    baseNode.scale.set(0.055, 0.045, 0.027);
    baseNode.castShadow = true;
    wingGroup.add(baseNode);

    // -------------------------------------------------------------------------
    // Custom camera controls: orbit, zoom, touch pinch, and reset
    // -------------------------------------------------------------------------

    const desired = {
      theta: -1.30,
      phi: 0.55,
      radius: 9.2,
      target: new THREE.Vector3(3.0, 0, 0)
    };

    const current = {
      theta: desired.theta,
      phi: desired.phi,
      radius: desired.radius,
      target: desired.target.clone()
    };

    function resetView() {
      desired.theta = -1.30;
      desired.phi = 0.55;
      desired.radius = 9.2;
      desired.target.set(3.0, 0, 0);
    }

    resetButton.addEventListener("click", resetView);

    renderer.domElement.addEventListener("dblclick", resetView);

    renderer.domElement.addEventListener(
      "contextmenu",
      (event) => event.preventDefault()
    );

    const pointers = new Map();
    let pinchDistance = 0;

    function getPinchDistance() {
      const values = [...pointers.values()];

      if (values.length < 2) {
        return 0;
      }

      return Math.hypot(
        values[0].x - values[1].x,
        values[0].y - values[1].y
      );
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      if (event.pointerType === "mouse" && event.button !== 0) {
        return;
      }

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      renderer.domElement.setPointerCapture(event.pointerId);
      renderer.domElement.classList.add("dragging");

      if (pointers.size >= 2) {
        pinchDistance = getPinchDistance();
      }
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      const previous = pointers.get(event.pointerId);

      if (!previous) {
        return;
      }

      if (pointers.size === 1) {
        const deltaX = event.clientX - previous.x;
        const deltaY = event.clientY - previous.y;

        desired.theta -= deltaX * 0.006;
        desired.phi = THREE.MathUtils.clamp(
          desired.phi - deltaY * 0.005,
          0.18,
          1.38
        );

        pointers.set(event.pointerId, {
          x: event.clientX,
          y: event.clientY
        });
      } else {
        const oldPinchDistance = pinchDistance;

        pointers.set(event.pointerId, {
          x: event.clientX,
          y: event.clientY
        });

        const newPinchDistance = getPinchDistance();

        if (
          oldPinchDistance > 0 &&
          newPinchDistance > 0
        ) {
          desired.radius = THREE.MathUtils.clamp(
            desired.radius *
              (oldPinchDistance / newPinchDistance),
            5,
            16
          );
        }

        pinchDistance = newPinchDistance;
      }
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);

      if (
        renderer.domElement.hasPointerCapture(event.pointerId)
      ) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }

      if (pointers.size < 2) {
        pinchDistance = 0;
      }

      if (pointers.size === 0) {
        renderer.domElement.classList.remove("dragging");
      }
    }

    renderer.domElement.addEventListener(
      "pointerup",
      releasePointer
    );

    renderer.domElement.addEventListener(
      "pointercancel",
      releasePointer
    );

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();

        desired.radius = THREE.MathUtils.clamp(
          desired.radius * Math.exp(event.deltaY * 0.001),
          5,
          16
        );
      },
      { passive: false }
    );

    document.addEventListener("keydown", (event) => {
      const key = event.key.toLowerCase();

      if (key === "r") {
        resetView();
      }

      if (key === "h") {
        hud.classList.toggle("hidden");
      }
    });

    // -------------------------------------------------------------------------
    // Resize and render loop
    // -------------------------------------------------------------------------

    function resize() {
      const width = window.innerWidth;
      const height = window.innerHeight;

      renderer.setPixelRatio(
        Math.min(window.devicePixelRatio, 2)
      );
      renderer.setSize(width, height, false);

      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    }

    window.addEventListener("resize", resize);
    resize();

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);
      const smoothing = 1 - Math.pow(0.0008, delta);

      current.theta = THREE.MathUtils.lerp(
        current.theta,
        desired.theta,
        smoothing
      );

      current.phi = THREE.MathUtils.lerp(
        current.phi,
        desired.phi,
        smoothing
      );

      current.radius = THREE.MathUtils.lerp(
        current.radius,
        desired.radius,
        smoothing
      );

      current.target.lerp(
        desired.target,
        smoothing
      );

      // Keep the full specimen visible in narrow portrait displays.
      const portraitScale = Math.max(
        1,
        1.25 / camera.aspect
      );

      const radius = current.radius * portraitScale;
      const sinPhi = Math.sin(current.phi);
      const cosPhi = Math.cos(current.phi);

      camera.position.set(
        current.target.x +
          radius * sinPhi * Math.cos(current.theta),
        current.target.y + radius * cosPhi,
        current.target.z +
          radius * sinPhi * Math.sin(current.theta)
      );

      camera.lookAt(current.target);
      renderer.render(scene, camera);
    }

    animate();
  </script>
</body>
</html>
