  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x237f89);
    scene.fog = new THREE.FogExp2(0x287f87, 0.027);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.08,
      80
    );

    const cameraTarget = new THREE.Vector3(0, 1.05, 0);
    const desired = {
      theta: 0.25,
      phi: 1.20,
      radius: 9.1
    };

    const current = {
      theta: desired.theta,
      phi: desired.phi,
      radius: desired.radius
    };

    // -------------------------------------------------------------------------
    // Utilities and deterministic random generator
    // -------------------------------------------------------------------------

    let randomSeed = 0x4d595df4;

    function random() {
      randomSeed =
        (Math.imul(randomSeed, 1664525) + 1013904223) >>> 0;
      return randomSeed / 4294967296;
    }

    function randomRange(min, max) {
      return min + (max - min) * random();
    }

    const up = new THREE.Vector3(0, 1, 0);

    function cylinderBetween(a, b, radiusTop, radiusBottom, material, radialSegments = 8) {
      const direction = new THREE.Vector3().subVectors(b, a);
      const length = direction.length();

      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          length,
          radialSegments,
          1,
          false
        ),
        material
      );

      mesh.position.copy(a).add(b).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(up, direction.normalize());
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      return mesh;
    }

    function makeCanvasTexture(canvas, repeatX = 1, repeatY = 1) {
      const texture = new THREE.CanvasTexture(canvas);
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(repeatX, repeatY);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );
      return texture;
    }

    // -------------------------------------------------------------------------
    // Procedural underwater background
    // -------------------------------------------------------------------------

    const background = new THREE.Mesh(
      new THREE.SphereGeometry(35, 48, 32),
      new THREE.ShaderMaterial({
        side: THREE.BackSide,
        depthWrite: false,
        uniforms: {
          topColor: { value: new THREE.Color(0x62c8c3) },
          middleColor: { value: new THREE.Color(0x248d98) },
          bottomColor: { value: new THREE.Color(0x075263) }
        },
        vertexShader: `
          varying vec3 vWorldPosition;

          void main() {
            vec4 worldPosition = modelMatrix * vec4(position, 1.0);
            vWorldPosition = worldPosition.xyz;
            gl_Position = projectionMatrix * viewMatrix * worldPosition;
          }
        `,
        fragmentShader: `
          uniform vec3 topColor;
          uniform vec3 middleColor;
          uniform vec3 bottomColor;
          varying vec3 vWorldPosition;

          void main() {
            float h = normalize(vWorldPosition).y * 0.5 + 0.5;
            vec3 lower = mix(bottomColor, middleColor, smoothstep(0.05, 0.55, h));
            vec3 color = mix(lower, topColor, smoothstep(0.48, 1.0, h));

            float sunGlow = pow(
              max(dot(normalize(vWorldPosition), normalize(vec3(-0.35, 0.82, 0.45))), 0.0),
              18.0
            );

            color += vec3(0.34, 0.43, 0.30) * sunGlow;
            gl_FragColor = vec4(color, 1.0);
          }
