      const b = new THREE.Vector3(...end);
      const direction = b.clone().sub(a);
      const length = direction.length();
      const mesh = addMesh(
        parent,
        new THREE.BoxGeometry(width, length, depth),
        material
      );

      mesh.position.copy(a).add(b).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        Y_AXIS,
        direction.normalize()
      );

      return mesh;
    }

    function addTube(parent, points, radius, material, tubularSegments = 60) {
      const vectors = points.map(
        point => point.isVector3
          ? point.clone()
          : new THREE.Vector3(...point)
      );

      const curve = new THREE.CatmullRomCurve3(vectors);
      return addMesh(
        parent,
        new THREE.TubeGeometry(
          curve,
          tubularSegments,
          radius,
          8,
          false
        ),
        material
      );
    }

    function addTextSprite(
      parent,
      text,
      x,
      y,
      z,
      width = 4,
      height = 0.8,
      accent = "#f4b63e"
    ) {
      const canvas = document.createElement("canvas");
      canvas.width = 1024;
      canvas.height = 192;

      const context = canvas.getContext("2d");
      context.clearRect(0, 0, canvas.width, canvas.height);
      context.fillStyle = "rgba(7, 13, 19, 0.86)";
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.fillStyle = accent;
      context.fillRect(0, 0, 13, canvas.height);
      context.strokeStyle = "rgba(180, 215, 231, 0.4)";
      context.lineWidth = 4;
      context.strokeRect(2, 2, canvas.width - 4, canvas.height - 4);

      context.fillStyle = "#e7f0f4";
      context.font = "700 58px system-ui, sans-serif";
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillText(text, canvas.width / 2, canvas.height / 2);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;

      const sprite = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: texture,
          transparent: true,
          depthTest: false,
          depthWrite: false,
          toneMapped: false
        })
      );

      sprite.position.set(x, y, z);
      sprite.scale.set(width, height, 1);
      parent.add(sprite);
      return sprite;
    }

    function addWallPlaque(parent, title, subtitle, x, y, z, width = 9) {
      const canvas = document.createElement("canvas");
