      context.fillStyle = "rgba(8, 16, 23, 0.95)";
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.strokeStyle = "#d5a536";
      context.lineWidth = 12;
      context.strokeRect(8, 8, canvas.width - 16, canvas.height - 16);
      context.fillStyle = "#f0b83c";
      context.fillRect(8, 8, canvas.width - 16, 16);

      context.textAlign = "center";
      context.fillStyle = "#eef5f7";
      context.font = "800 78px system-ui, sans-serif";
      context.fillText(title, canvas.width / 2, 130);

      context.fillStyle = "#8fb0bf";
      context.font = "500 35px system-ui, sans-serif";
      context.fillText(subtitle, canvas.width / 2, 215);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;

      const plaque = addMesh(
        parent,
        new THREE.PlaneGeometry(width, width / 4),
        new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          toneMapped: false
