    );
    beamBetween(
      generator,
      [frameHalfWidth, 0.4, -frameHalfDepth],
      [-frameHalfWidth, 6.5, -frameHalfDepth],
      0.09,
      0.09,
      materials.steelDark
    );
    beamBetween(
      generator,
      [-frameHalfWidth, 0.4, frameHalfDepth],
      [frameHalfWidth, 12.5, frameHalfDepth],
      0.075,
      0.075,
      materials.steelDark
    );

    function addCapacitorStage(stageIndex, y) {
      // Perimeter shelf for the stage.
      beamBetween(
        generator,
        [-frameHalfWidth, y, -frameHalfDepth],
        [frameHalfWidth, y, -frameHalfDepth],
        0.13,
        0.13,
        materials.steelDark
      );
      beamBetween(
        generator,
        [-frameHalfWidth, y, frameHalfDepth],
        [frameHalfWidth, y, frameHalfDepth],
        0.13,
        0.13,
        materials.steelDark
      );

      for (const x of [-frameHalfWidth, frameHalfWidth]) {
        beamBetween(
          generator,
          [x, y, -frameHalfDepth],
          [x, y, frameHalfDepth],
          0.13,
          0.13,
          materials.steelDark
        );
      }

      // Three horizontal capacitor cans per Marx stage.
      const capacitorX = [-2.55, 0, 2.55];
      const bodyY = y + 0.47;

      for (const x of capacitorX) {
        const body = addCylinder(
          generator,
          0.34,
          1.55,
          materials.aluminum,
          x,
          bodyY,
          0
        );
        body.rotation.z = Math.PI / 2;

        for (const side of [-1, 1]) {
          const cap = addCylinder(
            generator,
            0.38,
            0.19,
            materials.blue,
            x + side * 0.86,
            bodyY,
            0
          );
          cap.rotation.z = Math.PI / 2;

          const band = addMesh(
            generator,
            new THREE.TorusGeometry(0.35, 0.035, 8, 24),
            materials.steelDark,
            x + side * 0.7,
            bodyY,
            0
          );
          band.rotation.y = Math.PI / 2;
        }

        // HV terminal rising from each capacitor.
        cylinderBetween(
          generator,
          [x, bodyY + 0.3, 0],
          [x, y + 0.94, 0],
          0.055,
          materials.copper,
          12
        );

        addMesh(
          generator,
          new THREE.SphereGeometry(0.09, 12, 8),
          materials.copper,
          x,
          y + 0.94,
          0
        );
      }

      // Series links between the three capacitor cans.
      beamBetween(
        generator,
        [-1.61, bodyY, 0],
        [-0.94, bodyY, 0],
        0.095,
        0.095,
        materials.copper
      );
      beamBetween(
        generator,
        [0.94, bodyY, 0],
        [1.61, bodyY, 0],
        0.095,
        0.095,
        materials.copper
      );

      // Curved high-voltage busbar in front of the stage.
      addTube(
        generator,
        [
          [-3.18, y + 0.2, 1.02],
          [-2.72, y + 0.77, 1.25],
          [0, y + 1.08, 1.43],
          [2.72, y + 0.77, 1.25],
          [3.18, y + 0.2, 1.02]
        ],
        0.073,
        materials.copper,
        72
      );

      // Blue insulated lower bus.
      addTube(
        generator,
        [
          [-3.3, y + 0.07, 0.78],
          [-1.5, y + 0.01, 0.89],
          [1.5, y + 0.01, 0.89],
          [3.3, y + 0.07, 0.78]
        ],
        0.058,
        materials.blue,
        60
      );

      // Branch from the capacitor terminals to the upper busbar.
      for (const x of capacitorX) {
        addTube(
          generator,
          [
            [x, y + 0.94, 0],
            [x, y + 1.16, 0.36],
            [x, y + 0.98, 0.93],
            [x, y + 0.77, 1.26]
          ],
          0.028,
          materials.copper,
          24
        );
      }

      // Vertical curved interstage links along the right side.
      if (stageIndex < 7) {
        const nextY = y + 1.4;
        addTube(
          generator,
          [
            [3.18, y + 0.2, 1.02],
            [3.62, y + 0.48, 1.13],
            [3.65, y + 0.95, 1.12],
            [3.18, nextY + 0.2, 1.02]
          ],
          0.06,
          materials.copper,
          40
        );
