      // Small stage marker.
      addTextSprite(
        generator,
        String(stageIndex + 1).padStart(2, "0"),
        -3.85,
        y + 0.16,
        2.05,
        0.58,
        0.34,
        "#72c9ec"
      );
    }

    function addChargingResistor(x, z, y, side) {
      const resistor = new THREE.Group();
