      gapCable = addTube(
        scene,
        [
          [-1.45, 12.1, -1.55],
          [-0.25, 10.2, -0.5],
          [0.9, 5.1, 0.55],
          [2.25, 0.7, 0.8],
          [leftX - 0.4, 0.38, gapZ]
        ],
        0.105,
        materials.rubber,
        90
      );
    }

    // Ground conductor from the right stand to a floor bonding point.
    addTube(
      scene,
      [
        [8.25, 0.42, 0.5],
        [9.2, 0.25, 0.4],
        [11.4, 0.18, -1],
        [14.8, 0.18, -8]
      ],
      0.055,
      materials.blue,
      80
    );

    // -------------------------------------------------------------------------
    // Impulse arc
    // -------------------------------------------------------------------------

    const arcGroup = new THREE.Group();
    scene.add(arcGroup);

    const arcSegments = 22;
    const arcLines = [];

    for (let lineIndex = 0; lineIndex < 4; lineIndex++) {
      const positions = new Float32Array(arcSegments * 3);
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute(
        "position",
        new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage)
      );

      const material = new THREE.LineBasicMaterial({
        color: lineIndex === 0 ? 0xffffff : 0x8bdfff,
        transparent: true,
        opacity: lineIndex === 0 ? 1 : 0.78,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false
      });

      const line = new THREE.Line(geometry, material);
      line.frustumCulled = false;
      line.visible = false;
      line.renderOrder = 8;
      arcGroup.add(line);
      arcLines.push(line);
    }

    // Soft radial glow texture.
    const glowCanvas = document.createElement("canvas");
    glowCanvas.width = 128;
    glowCanvas.height = 128;
    const glowContext = glowCanvas.getContext("2d");
    const glowGradient = glowContext.createRadialGradient(
      64,
      64,
      0,
      64,
      64,
      64
    );
    glowGradient.addColorStop(0, "rgba(235,250,255,1)");
    glowGradient.addColorStop(0.16, "rgba(120,220,255,0.9)");
    glowGradient.addColorStop(0.48, "rgba(50,140,255,0.28)");
    glowGradient.addColorStop(1, "rgba(20,80,255,0)");
    glowContext.fillStyle = glowGradient;
    glowContext.fillRect(0, 0, 128, 128);

    const glowTexture = new THREE.CanvasTexture(glowCanvas);
    glowTexture.colorSpace = THREE.SRGBColorSpace;

    const arcGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: glowTexture,
        color: 0x7cd7ff,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false
      })
    );
    arcGlow.visible = false;
    arcGlow.renderOrder = 7;
    scene.add(arcGlow);

    const arcLight = new THREE.PointLight(0x8edaff, 0, 12, 2);
    scene.add(arcLight);

    let surfaceGap = 0.6;
    let pulseEnd = 0;
    let nextAutomaticPulse = performance.now() + 1800;

    function updateGap() {
      const gapRange = document.getElementById("gap-range");
      surfaceGap = Number(gapRange.value);
      document.getElementById("gap-value").textContent =
        `${surfaceGap.toFixed(2)} m`;

      const centerSeparation = sphereRadius * 2 + surfaceGap;
      const leftX = gapCenterX - centerSeparation / 2;
      const rightX = gapCenterX + centerSeparation / 2;

      leftElectrode.position.x = leftX;
      rightElectrode.position.x = rightX;

      updateGapCable(leftX);
    }

    function fireImpulse() {
      pulseEnd = performance.now() + 430;
    }

    function updateArc(active, time) {
      arcLines.forEach(line => {
        line.visible = active;
      });

      arcGlow.visible = active;
      arcLight.intensity = active ? 32 : 0;

      if (!active) {
        arcGlow.material.opacity = 0;
        return;
      }

      const startX = leftElectrode.position.x + sphereRadius * 0.99;
      const endX = rightElectrode.position.x - sphereRadius * 0.99;
      const centerX = (startX + endX) / 2;
      const flicker = 0.82 + Math.sin(time * 0.075) * 0.16;

      arcGlow.position.set(centerX, sphereY, gapZ);
      arcGlow.scale.set(Math.max(1.2, surfaceGap + 1.15), 1.65, 1);
      arcGlow.material.opacity = 0.62 * flicker;
      arcLight.position.set(centerX, sphereY, gapZ + 0.1);
      arcLight.intensity = 32 * flicker;

      arcLines.forEach((line, lineIndex) => {
        const attribute = line.geometry.getAttribute("position");

        for (let i = 0; i < arcSegments; i++) {
          const t = i / (arcSegments - 1);
          const envelope = Math.sin(Math.PI * t);
          const amplitude = Math.min(0.42, 0.1 + surfaceGap * 0.22);
          const randomY = (Math.random() - 0.5) * amplitude * envelope;
          const randomZ = (Math.random() - 0.5) * amplitude * envelope;
          const branch = lineIndex === 0
            ? 0
            : Math.sin(t * Math.PI * (lineIndex + 1) + time * 0.03) *
              0.055 *
              envelope;

          attribute.setXYZ(
            i,
            THREE.MathUtils.lerp(startX, endX, t),
            sphereY + randomY + branch,
            gapZ + randomZ
          );
        }

        attribute.needsUpdate = true;
      });
    }

    document.getElementById("gap-range").addEventListener("input", updateGap);
    document.getElementById("fire").addEventListener("click", fireImpulse);

    // -------------------------------------------------------------------------
    // Custom camera controls: orbit, zoom and pan
    // -------------------------------------------------------------------------

    const cameraState = {
      target: new THREE.Vector3(-1, 5.2, -1),
      radius: 28,
      theta: 0.28,
      phi: 1.17
    };

    const defaultCamera = {
      target: new THREE.Vector3(-1, 5.2, -1),
      radius: 28,
      theta: 0.28,
      phi: 1.17
    };

    function updateCamera() {
      const sinPhi = Math.sin(cameraState.phi);
      camera.position.set(
        cameraState.target.x +
          cameraState.radius * sinPhi * Math.sin(cameraState.theta),
        cameraState.target.y + cameraState.radius * Math.cos(cameraState.phi),
        cameraState.target.z +
          cameraState.radius * sinPhi * Math.cos(cameraState.theta)
      );

      camera.lookAt(cameraState.target);
    }

    function resetCamera() {
      cameraState.target.copy(defaultCamera.target);
      cameraState.radius = defaultCamera.radius;
      cameraState.theta = defaultCamera.theta;
      cameraState.phi = defaultCamera.phi;
      updateCamera();
    }

    document.getElementById("reset-view").addEventListener("click", resetCamera);

    let dragging = false;
    let dragMode = "orbit";
    let previousX = 0;
    let previousY = 0;
    let activePointer = null;

    const canvas = renderer.domElement;

    canvas.addEventListener("contextmenu", event => event.preventDefault());

    canvas.addEventListener("pointerdown", event => {
      dragging = true;
      activePointer = event.pointerId;
      dragMode =
        event.button === 2 || event.button === 1 || event.shiftKey
          ? "pan"
          : "orbit";

      previousX = event.clientX;
      previousY = event.clientY;
      canvas.setPointerCapture(event.pointerId);
    });

    canvas.addEventListener("pointermove", event => {
      if (!dragging || event.pointerId !== activePointer) return;

      const dx = event.clientX - previousX;
      const dy = event.clientY - previousY;
      previousX = event.clientX;
      previousY = event.clientY;

      if (dragMode === "orbit") {
        cameraState.theta -= dx * 0.005;
        cameraState.phi = THREE.MathUtils.clamp(
          cameraState.phi - dy * 0.0045,
          0.22,
          1.49
        );
      } else {
        const forward = new THREE.Vector3();
        camera.getWorldDirection(forward);
        forward.y = 0;
        forward.normalize();

        const right = new THREE.Vector3()
          .crossVectors(forward, Y_AXIS)
          .normalize();
        const up = new THREE.Vector3()
          .crossVectors(right, forward)
          .normalize();

        const panScale = cameraState.radius * 0.00145;
        cameraState.target.addScaledVector(right, -dx * panScale);
        cameraState.target.addScaledVector(up, dy * panScale);
        cameraState.target.y = THREE.MathUtils.clamp(
          cameraState.target.y,
          0.5,
          13
        );
      }

      updateCamera();
    });

    function endDrag(event) {
      if (event.pointerId !== activePointer) return;
      dragging = false;
      activePointer = null;
    }

    canvas.addEventListener("pointerup", endDrag);
    canvas.addEventListener("pointercancel", endDrag);

    canvas.addEventListener(
      "wheel",
      event => {
        event.preventDefault();
        cameraState.radius = THREE.MathUtils.clamp(
          cameraState.radius * Math.exp(event.deltaY * 0.001),
          9,
          52
        );
        updateCamera();
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetCamera);

    window.addEventListener("keydown", event => {
      if (event.key.toLowerCase() === "r") {
        resetCamera();
      }

      if (event.key === "+" || event.key === "=") {
        cameraState.radius = Math.max(9, cameraState.radius - 1.5);
        updateCamera();
      }

      if (event.key === "-" || event.key === "_") {
        cameraState.radius = Math.min(52, cameraState.radius + 1.5);
        updateCamera();
      }
    });

    window.addEventListener("resize", () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    });

    // -------------------------------------------------------------------------
    // Initialization and render loop
    // -------------------------------------------------------------------------

    updateGap();
    updateCamera();

    function animate() {
      requestAnimationFrame(animate);

      const now = performance.now();
      const elapsed = clock.getElapsedTime();

      if (
        document.getElementById("auto-pulse").checked &&
        now >= nextAutomaticPulse
      ) {
        fireImpulse();
        nextAutomaticPulse = now + 6500;
      }

      updateArc(now < pulseEnd, elapsed);

      // Subtle fluorescent lighting variation.
      blueFill.intensity = 21 + Math.sin(elapsed * 0.7) * 1.2;
      warmFill.intensity = 15 + Math.sin(elapsed * 0.43 + 1.4) * 0.8;

      renderer.render(scene, camera);
    }

    animate();
  </script>
</body>
</html>
