    function createWorldLabel(text, accent, width = 3.8) {
      const canvas = document.createElement("canvas");
      canvas.width = 768;
      canvas.height = 160;

      const ctx = canvas.getContext("2d");
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      roundedRect(ctx, 6, 12, 756, 132, 25);
      ctx.fillStyle = "rgba(8, 24, 28, 0.88)";
      ctx.fill();

      ctx.strokeStyle = "rgba(255,255,255,0.2)";
      ctx.lineWidth = 2;
      ctx.stroke();

      roundedRect(ctx, 25, 44, 14, 68, 7);
      ctx.fillStyle = accent;
      ctx.fill();

      ctx.fillStyle = "#f7fffb";
      ctx.font = "800 45px system-ui, sans-serif";
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";
      ctx.fillText(text.toUpperCase(), 64, 79);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.anisotropy = Math.min(
        4,
        renderer.capabilities.getMaxAnisotropy()
      );

      const material = new THREE.SpriteMaterial({
        map: texture,
        transparent: true,
        depthTest: false,
        depthWrite: false,
        toneMapped: false
      });

      const sprite = new THREE.Sprite(material);
      sprite.scale.set(width, width * 160 / 768, 1);
      sprite.renderOrder = 20;
      labelsGroup.add(sprite);
      return sprite;
    }

    function makeDeckBadge(number, accent) {
      const canvas = document.createElement("canvas");
      canvas.width = 256;
      canvas.height = 256;

      const ctx = canvas.getContext("2d");
      ctx.clearRect(0, 0, 256, 256);

      ctx.beginPath();
      ctx.arc(128, 128, 105, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(9,25,29,0.9)";
      ctx.fill();

      ctx.lineWidth = 14;
      ctx.strokeStyle = accent;
      ctx.stroke();

      ctx.fillStyle = "#ffffff";
      ctx.font = "900 104px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(String(number), 128, 135);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;

      const badge = new THREE.Mesh(
        new THREE.PlaneGeometry(0.85, 0.85),
        new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          depthWrite: false,
          toneMapped: false
        })
      );

      badge.rotation.x = -Math.PI / 2;
      return badge;
    }

