    function makeTree(x, z, scale = 1) {
      const group = new THREE.Group();
      group.position.set(x, 0, z);
      group.rotation.y = random() * Math.PI * 2;

      const trunkHeight = 1.65 * scale;
      const trunk = new THREE.Mesh(
        new THREE.CylinderGeometry(
          0.12 * scale,
          0.2 * scale,
          trunkHeight,
          7
        ),
        M.bark
      );
      trunk.position.y = trunkHeight / 2;
      trunk.castShadow = true;
      trunk.receiveShadow = true;
      group.add(trunk);

      const isPine = random() > 0.32;

      if (isPine) {
        for (let layer = 0; layer < 3; layer++) {
          const foliage = new THREE.Mesh(
            new THREE.ConeGeometry(
              (1.15 - layer * 0.18) * scale,
              1.7 * scale,
              8
            ),
            layer === 1 ? M.pineLight : M.pine
          );
          foliage.position.y =
            trunkHeight * 0.7 + layer * 0.72 * scale;
          foliage.rotation.y = layer * 0.43;
          foliage.castShadow = true;
          foliage.receiveShadow = true;
          group.add(foliage);
        }
      } else {
        const crown = new THREE.Mesh(
          new THREE.IcosahedronGeometry(1.25 * scale, 1),
          M.leaves
        );
        crown.position.y = trunkHeight + 0.55 * scale;
        crown.scale.set(1, 0.92, 0.88);
        crown.rotation.set(random(), random(), random());
        crown.castShadow = true;
        crown.receiveShadow = true;
        group.add(crown);
      }

      scene.add(group);
    }

