    function addRailSide(group, a, b, isGate) {
      const direction = b.clone().sub(a);
      const length = direction.length();
      direction.normalize();

      const sections = isGate
        ? [
            [-length / 2, -0.76],
            [0.76, length / 2]
          ]
        : [[-length / 2, length / 2]];

      sections.forEach(([from, to]) => {
        const sectionLength = to - from;
        if (sectionLength <= 0.05) return;

        const p0 = a.clone().addScaledVector(direction, from);
        const p1 = a.clone().addScaledVector(direction, to);

        cylinderBetween(
          group,
          new THREE.Vector3(p0.x, 1.12, p0.y),
          new THREE.Vector3(p1.x, 1.12, p1.y),
          0.045,
          M.steel,
          8
        );

        cylinderBetween(
          group,
          new THREE.Vector3(p0.x, 0.58, p0.y),
          new THREE.Vector3(p1.x, 0.58, p1.y),
          0.019,
          M.rope,
          6
        );

        const postCount = Math.max(1, Math.ceil(sectionLength / 1.65));

        for (let i = 0; i <= postCount; i++) {
          const t = i / postCount;
          const p = p0.clone().lerp(p1, t);
          cylinderBetween(
            group,
            new THREE.Vector3(p.x, 0.01, p.y),
            new THREE.Vector3(p.x, 1.13, p.y),
            0.04,
            M.steel,
            7
          );
        }
      });
    }

    function createPlatform(config) {
      const {
        x,
        y,
        z,
        w,
        d,
        number,
        accent,
        gates = []
      } = config;

      const group = new THREE.Group();
      group.position.set(x, y, z);
      scene.add(group);

      const accentMaterial = new THREE.MeshStandardMaterial({
        color: accent,
        roughness: 0.55,
        metalness: 0.18
      });

      // Individual deck boards.
      const slatCount = Math.max(7, Math.round(d / 0.46));
      const slatPitch = d / slatCount;

      for (let i = 0; i < slatCount; i++) {
        box(
          group,
          [w - 0.08, 0.12, slatPitch - 0.055],
          [0, -0.06, -d / 2 + slatPitch * (i + 0.5)],
          i % 3 === 0 ? M.plankLight : M.plank
        );
      }

      // Structural perimeter beams.
      box(group, [w + 0.12, 0.2, 0.18], [0, -0.22, -d / 2], M.frame);
      box(group, [w + 0.12, 0.2, 0.18], [0, -0.22, d / 2], M.frame);
      box(group, [0.18, 0.2, d], [-w / 2, -0.22, 0], M.frame);
      box(group, [0.18, 0.2, d], [w / 2, -0.22, 0], M.frame);

      // Tall support poles.
      const poleInsetX = Math.min(0.62, w * 0.18);
      const poleInsetZ = Math.min(0.58, d * 0.17);

      [
        [-w / 2 + poleInsetX, -d / 2 + poleInsetZ],
        [w / 2 - poleInsetX, -d / 2 + poleInsetZ],
        [-w / 2 + poleInsetX, d / 2 - poleInsetZ],
        [w / 2 - poleInsetX, d / 2 - poleInsetZ]
      ].forEach(([px, pz]) => {
        cylinderBetween(
          group,
          new THREE.Vector3(px, -y, pz),
          new THREE.Vector3(px, -0.3, pz),
          0.135,
          M.steel,
          10
        );
      });

      // Diagonal support braces.
      [-d / 2 + poleInsetZ, d / 2 - poleInsetZ].forEach((pz) => {
        cylinderBetween(
          group,
          new THREE.Vector3(-w / 2 + 0.45, -y + 0.45, pz),
          new THREE.Vector3(w / 2 - 0.45, -0.32, pz),
          0.06,
          M.frame,
          7
        );
      });

      // Safety rails with gate openings.
      const gateSet = new Set(gates);

      addRailSide(
        group,
        new THREE.Vector2(-w / 2, -d / 2),
        new THREE.Vector2(w / 2, -d / 2),
        gateSet.has("north")
      );

      addRailSide(
        group,
        new THREE.Vector2(-w / 2, d / 2),
        new THREE.Vector2(w / 2, d / 2),
        gateSet.has("south")
      );

      addRailSide(
        group,
        new THREE.Vector2(-w / 2, -d / 2),
        new THREE.Vector2(-w / 2, d / 2),
        gateSet.has("west")
      );

      addRailSide(
        group,
        new THREE.Vector2(w / 2, -d / 2),
        new THREE.Vector2(w / 2, d / 2),
        gateSet.has("east")
      );

      // Colored deck corner caps.
      [
        [-w / 2 + 0.16, -d / 2 + 0.16],
        [w / 2 - 0.16, -d / 2 + 0.16],
        [-w / 2 + 0.16, d / 2 - 0.16],
        [w / 2 - 0.16, d / 2 - 0.16]
      ].forEach(([px, pz]) => {
        box(group, [0.28, 0.16, 0.28], [px, 0.01, pz], accentMaterial);
      });

      // Belay anchor: base, steel post, large ring, and small carabiner.
      const ax = -w / 2 + 0.58;
      const az = -d / 2 + 0.58;

      box(group, [0.34, 0.1, 0.32], [ax, 0.05, az], M.darkSteel);
      cylinderBetween(
        group,
        new THREE.Vector3(ax, 0.08, az),
        new THREE.Vector3(ax, 1.31, az),
        0.045,
        M.steel,
        8
      );

      const anchorRing = new THREE.Mesh(
        new THREE.TorusGeometry(0.18, 0.04, 8, 20),
        M.orange
      );
      anchorRing.position.set(ax, 1.13, az + 0.06);
      anchorRing.rotation.y = 0.22;
      anchorRing.castShadow = true;
      group.add(anchorRing);

      const carabiner = new THREE.Mesh(
        new THREE.TorusGeometry(0.105, 0.026, 7, 16),
        M.yellow
      );
      carabiner.position.set(ax, 0.82, az + 0.06);
      carabiner.rotation.y = 0.22;
      carabiner.scale.y = 1.25;
      carabiner.castShadow = true;
      group.add(carabiner);

      const badge = makeDeckBadge(number, accent);
      badge.position.set(0, 0.016, d * 0.16);
      group.add(badge);

      group.userData.platform = {
        number,
        x,
        y,
        z,
        w,
        d
      };

      return group;
    }

