    // -------------------------------------------------------------------------
    // Suspended plank bridges
    // -------------------------------------------------------------------------

    function createPlankBridge(start, end, width = 1.5, sag = 0.42) {
      const curve = makeSaggingCurve(start, end, sag, 30);
      const right = horizontalRight(start, end);
      const length = start.distanceTo(end);
      const boardCount = Math.max(9, Math.ceil(length / 0.42));
      const boardLength = (length / boardCount) * 0.76;

      for (let i = 0; i < boardCount; i++) {
        const t = (i + 0.5) / boardCount;
        const point = curve.getPoint(t);
        const tangent = curve.getTangent(t).normalize();

        const plank = box(
          scene,
          [width, 0.12, boardLength],
          [point.x, point.y - 0.05, point.z],
          i % 4 === 0 ? M.plankLight : M.plank
        );

        plank.quaternion.setFromUnitVectors(AXIS_Z, tangent);
      }

      [-1, 1].forEach((side) => {
        const upperPoints = [];
        const lowerPoints = [];

        for (let i = 0; i <= 32; i++) {
          const point = curve.getPoint(i / 32);
          const upper = point.clone().addScaledVector(
            right,
            side * width * 0.52
          );
          upper.y += 1.04;
          upperPoints.push(upper);

          const lower = point.clone().addScaledVector(
            right,
            side * width * 0.52
          );
          lower.y += 0.23;
          lowerPoints.push(lower);
        }

        tube(scene, upperPoints, 0.035, M.rope, 64, 7);
        tube(scene, lowerPoints, 0.021, M.rope, 64, 6);

        for (let i = 0; i < boardCount; i += 3) {
          const t = i / (boardCount - 1);
          const point = curve.getPoint(t);
          const edge = point.clone().addScaledVector(
            right,
            side * width * 0.49
          );

          cylinderBetween(
            scene,
            new THREE.Vector3(edge.x, edge.y + 0.02, edge.z),
            new THREE.Vector3(edge.x, edge.y + 1.04, edge.z),
            0.021,
            M.rope,
            6
          );
        }
      });
    }

    const bridge1Start = new THREE.Vector3(
      P0.userData.platform.x + P0.userData.platform.w / 2,
      P0.userData.platform.y,
      P0.userData.platform.z
    );

    const bridge1End = new THREE.Vector3(
      P1.userData.platform.x - P1.userData.platform.w / 2,
      P1.userData.platform.y,
      P1.userData.platform.z
    );

    createPlankBridge(bridge1Start, bridge1End, 1.55, 0.4);

    const bridge2Start = new THREE.Vector3(
      P2.userData.platform.x + P2.userData.platform.w / 2,
      P2.userData.platform.y,
      P2.userData.platform.z
    );

    const bridge2End = new THREE.Vector3(
      P3.userData.platform.x - P3.userData.platform.w / 2,
      P3.userData.platform.y,
      P3.userData.platform.z
    );

    createPlankBridge(bridge2Start, bridge2End, 1.5, 0.3);

    // -------------------------------------------------------------------------
    // Suspended net tunnel
    // -------------------------------------------------------------------------

    function createNetTunnel(start, end, width = 1.35, height = 1.6) {
      const right = horizontalRight(start, end);
      const hoopCount = 9;
      const thetaSteps = 12;

      function centerAt(t) {
        return start.clone().lerp(end, t);
      }

      function archPoint(t, theta) {
        const center = centerAt(t);
        const point = center.clone().addScaledVector(
          right,
          width * Math.sin(theta)
        );
        point.y += height * Math.cos(theta);
        return point;
      }

      // Structural hoops.
      for (let i = 0; i < hoopCount; i++) {
        const t = i / (hoopCount - 1);
        const points = [];

        for (let j = 0; j <= thetaSteps; j++) {
          const theta = -Math.PI / 2 + (j / thetaSteps) * Math.PI;
          points.push(archPoint(t, theta));
        }

        const hoopCurve = new THREE.CatmullRomCurve3(
          points,
          false,
          "centripetal"
        );

        const hoop = new THREE.Mesh(
          new THREE.TubeGeometry(hoopCurve, 26, 0.036, 6, false),
          M.netFrame
        );
        hoop.castShadow = true;
        scene.add(hoop);
      }

      // Longitudinal net ropes.
      for (let j = 0; j <= 8; j++) {
        const theta = -Math.PI / 2 + (j / 8) * Math.PI;
        const points = [];

        for (let i = 0; i <= 24; i++) {
          points.push(archPoint(i / 24, theta));
        }

        tube(scene, points, 0.019, M.net, 52, 5);
      }

      // Fine diagonal mesh, batched into one LineSegments object.
      const vertices = [];

      for (let i = 0; i < hoopCount - 1; i++) {
        const t0 = i / (hoopCount - 1);
        const t1 = (i + 1) / (hoopCount - 1);

        for (let j = 0; j < thetaSteps; j++) {
          const theta0 = -Math.PI / 2 + (j / thetaSteps) * Math.PI;
          const theta1 =
            -Math.PI / 2 + ((j + 1) / thetaSteps) * Math.PI;

          const a = archPoint(t0, theta0);
          const b = archPoint(t1, theta1);
          const c = archPoint(t0, theta1);
          const d = archPoint(t1, theta0);

          vertices.push(
            a.x, a.y, a.z,
            b.x, b.y, b.z,
            c.x, c.y, c.z,
            d.x, d.y, d.z
          );
        }
      }

      const meshGeometry = new THREE.BufferGeometry();
      meshGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(vertices, 3)
      );

      const meshLines = new THREE.LineSegments(
        meshGeometry,
        new THREE.LineBasicMaterial({
          color: 0x58d2c6,
          transparent: true,
          opacity: 0.72
        })
      );
      scene.add(meshLines);
    }

    const netStart = new THREE.Vector3(
      P1.userData.platform.x + P1.userData.platform.w / 2,
      P1.userData.platform.y,
      P1.userData.platform.z
    );

    const netEnd = new THREE.Vector3(
      P2.userData.platform.x - P2.userData.platform.w / 2,
      P2.userData.platform.y,
      P2.userData.platform.z
    );

    createNetTunnel(netStart, netEnd);

    // -------------------------------------------------------------------------
    // Pair of slackline cables
    // -------------------------------------------------------------------------

    function createSlacklines(start, end) {
      const right = horizontalRight(start, end);
      const separation = 0.68;
      const sag = 0.5;

      [-1, 1].forEach((side, index) => {
        const points = [];

        for (let i = 0; i <= 32; i++) {
          const t = i / 32;
          const point = start.clone().lerp(end, t);
          point.addScaledVector(right, side * separation / 2);
          point.y -= Math.sin(Math.PI * t) * sag;
          points.push(point);
        }

        tube(
          scene,
          points,
          0.031,
          index === 0 ? M.slackA : M.slackB,
          64,
          7
        );

        [0.18, 0.82].forEach((t) => {
          const point = start.clone().lerp(end, t);
          point.addScaledVector(right, side * separation / 2);
          point.y -= Math.sin(Math.PI * t) * sag;

          const tangent = end.clone().sub(start).normalize();
          const wrapStart = point.clone().addScaledVector(tangent, -0.055);
          const wrapEnd = point.clone().addScaledVector(tangent, 0.055);

          cylinderBetween(
            scene,
            wrapStart,
            wrapEnd,
            0.047,
            M.yellow,
            8
          );
        });
      });

      // Small hanging balance slings.
      [0.34, 0.66].forEach((t) => {
        const point = start.clone().lerp(end, t);
        point.y -= Math.sin(Math.PI * t) * sag;

        cylinderBetween(
          scene,
          point,
          new THREE.Vector3(point.x, point.y - 0.24, point.z),
          0.016,
          M.rope,
          6
        );
      });

      [start, end].forEach((point) => {
        const ring = new THREE.Mesh(
          new THREE.TorusGeometry(0.12, 0.025, 7, 16),
          M.steel
        );
        ring.position.copy(point);
        ring.rotation.y = Math.PI / 2;
        ring.castShadow = true;
        scene.add(ring);
      });
    }

    const slackStart = new THREE.Vector3(
      P0.userData.platform.x,
      P0.userData.platform.y + 0.08,
      P0.userData.platform.z + P0.userData.platform.d / 2
    );

    const slackEnd = new THREE.Vector3(
      SLACK.userData.platform.x - SLACK.userData.platform.w / 2,
      SLACK.userData.platform.y + 0.08,
      SLACK.userData.platform.z
    );

    createSlacklines(slackStart, slackEnd);

    // -------------------------------------------------------------------------
    // Landing mound
    // -------------------------------------------------------------------------

    const mound = new THREE.Mesh(
      new THREE.SphereGeometry(1, 40, 20),
      M.clearing
    );
    mound.position.set(35.2, -0.15, 0);
    mound.scale.set(4.2, 1.7, 3.8);
    mound.castShadow = true;
    mound.receiveShadow = true;
    scene.add(mound);

    const landingDirt = new THREE.Mesh(
      new THREE.CylinderGeometry(2.15, 2.35, 0.12, 32),
      M.dirt
    );
    landingDirt.position.set(35.2, 1.5, 0);
    landingDirt.castShadow = true;
    landingDirt.receiveShadow = true;
    scene.add(landingDirt);

    box(
      scene,
      [2.6, 0.12, 1.8],
      [35.2, 1.63, 0],
      M.landingPad
    );

    // Small landing-mound belay post.
    cylinderBetween(
      scene,
      new THREE.Vector3(36.0, 1.55, 0.35),
      new THREE.Vector3(36.0, 2.7, 0.35),
      0.045,
      M.steel,
      8
    );

    const landingRing = new THREE.Mesh(
      new THREE.TorusGeometry(0.16, 0.035, 8, 18),
      M.orange
    );
    landingRing.position.set(36.0, 2.5, 0.42);
    landingRing.castShadow = true;
    scene.add(landingRing);

    // -------------------------------------------------------------------------
    // Zip line and animated trolley
    // -------------------------------------------------------------------------

    const zipStart = new THREE.Vector3(
      P3.userData.platform.x + P3.userData.platform.w / 2 + 0.05,
      P3.userData.platform.y + 1.55,
      0
    );

    const zipEnd = new THREE.Vector3(34.65, 2.15, 0);
    const zipCurve = makeSaggingCurve(zipStart, zipEnd, 0.18, 40);

    const zipPoints = [];
    const safetyPoints = [];

    for (let i = 0; i <= 40; i++) {
      const point = zipCurve.getPoint(i / 40);
      zipPoints.push(point);

      const safety = point.clone();
      safety.y -= 0.26;
      safetyPoints.push(safety);
    }

    tube(scene, zipPoints, 0.056, M.orange, 90, 8);
    tube(scene, safetyPoints, 0.019, M.darkRope, 90, 6);

    // Summit-side mast and arm.
    const zipMastX = P3.userData.platform.x + P3.userData.platform.w / 2 - 0.35;
    const zipMastTop = new THREE.Vector3(
      zipMastX,
      zipStart.y + 0.08,
      0
    );

    cylinderBetween(
      scene,
      new THREE.Vector3(zipMastX, P3.userData.platform.y, 0),
      zipMastTop,
      0.075,
      M.orange,
      10
    );

    cylinderBetween(
      scene,
      new THREE.Vector3(zipMastX - 0.8, P3.userData.platform.y, 0),
      zipMastTop,
      0.045,
      M.steel,
      8
    );

    cylinderBetween(
      scene,
      zipMastTop,
      zipStart,
      0.06,
      M.orange,
      8
    );

    // Landing-side support.
    const landingPostTop = new THREE.Vector3(35.25, 2.38, 0);

    cylinderBetween(
      scene,
      new THREE.Vector3(35.25, 1.48, 0),
      landingPostTop,
      0.07,
      M.orange,
      10
    );

    cylinderBetween(
      scene,
      landingPostTop,
      zipEnd,
      0.055,
      M.orange,
      8
    );

    const trolley = new THREE.Group();
    scene.add(trolley);

    box(trolley, [0.34, 0.18, 0.48], [0, -0.24, 0], M.darkSteel);

    const wheel = new THREE.Mesh(
      new THREE.TorusGeometry(0.145, 0.038, 8, 18),
      M.steel
    );
    wheel.position.set(0, 0.01, 0);
    wheel.castShadow = true;
    trolley.add(wheel);

    cylinderBetween(
      trolley,
      new THREE.Vector3(-0.12, -0.1, 0),
      new THREE.Vector3(-0.12, -0.55, 0),
      0.015,
      M.darkRope,
      6
    );

    cylinderBetween(
      trolley,
      new THREE.Vector3(0.12, -0.1, 0),
      new THREE.Vector3(0.12, -0.55, 0),
      0.015,
      M.darkRope,
      6
    );

    box(
      trolley,
      [0.34, 0.09, 0.1],
      [0, -0.56, 0],
      M.red
    );

    // -------------------------------------------------------------------------
    // Access ladder and base sign
    // -------------------------------------------------------------------------

    const ladderX = P0.userData.platform.x - P0.userData.platform.w / 2 - 0.06;
    const ladderZ = P0.userData.platform.z;

    cylinderBetween(
      scene,
      new THREE.Vector3(ladderX, 0.05, ladderZ - 0.48),
      new THREE.Vector3(ladderX, P0.userData.platform.y + 0.1, ladderZ - 0.48),
      0.05,
      M.steel,
      8
    );

    cylinderBetween(
      scene,
      new THREE.Vector3(ladderX, 0.05, ladderZ + 0.48),
      new THREE.Vector3(ladderX, P0.userData.platform.y + 0.1, ladderZ + 0.48),
      0.05,
      M.steel,
      8
    );

    for (let y = 0.3; y < P0.userData.platform.y; y += 0.32) {
      cylinderBetween(
        scene,
        new THREE.Vector3(ladderX, y, ladderZ - 0.48),
        new THREE.Vector3(ladderX, y, ladderZ + 0.48),
        0.035,
        M.steel,
        7
      );
    }

    cylinderBetween(
      scene,
      new THREE.Vector3(-10.5, 0, 6.7),
      new THREE.Vector3(-10.5, 2.4, 6.7),
      0.09,
      M.wood,
      8
    );

    // -------------------------------------------------------------------------
    // Labels
    // -------------------------------------------------------------------------

    const startLabel = createWorldLabel("01  Start", "#54b8d1", 3.1);
    startLabel.position.set(-5, 6.15, 5);

    const bridgeLabel = createWorldLabel("02  Plank Bridge", "#efbd58", 4.0);
    bridgeLabel.position.copy(bridge1Start).lerp(bridge1End, 0.5);
    bridgeLabel.position.y += 1.65;

    const netLabel = createWorldLabel("03  Net Tunnel", "#39c8bd", 3.7);
    netLabel.position.copy(netStart).lerp(netEnd, 0.5);
    netLabel.position.y += 2.35;

    const summitLabel = createWorldLabel("04  Summit", "#ff7849", 3.2);
    summitLabel.position.set(23.5, 13.35, 0);

    const slackLabel = createWorldLabel("Twin Slacklines", "#9a8cff", 3.6);
    slackLabel.position.copy(slackStart).lerp(slackEnd, 0.5);
    slackLabel.position.y += 1.25;

    const zipLabel = createWorldLabel("Zip Line", "#ff7849", 3.2);
    zipLabel.position.copy(zipCurve.getPoint(0.56));
    zipLabel.position.y += 1.2;

    const landingLabel = createWorldLabel("Landing", "#ff7849", 2.7);
    landingLabel.position.set(35.2, 3.1, 0);

    const baseLabel = createWorldLabel("Summit Ropes", "#54b8d1", 3.4);
    baseLabel.position.set(-10.5, 2.75, 6.7);

    // -------------------------------------------------------------------------
    // Custom camera controls — no addon imports
    // -------------------------------------------------------------------------

    const controls = {
      target: new THREE.Vector3(12.5, 4.8, 1.2),
      radius: 40,
      theta: 0.72,
      phi: 1.08,
      minRadius: 11,
      maxRadius: 78
    };

    function updateCamera() {
      controls.target.x = THREE.MathUtils.clamp(
        controls.target.x,
        -12,
        42
      );
      controls.target.y = THREE.MathUtils.clamp(
        controls.target.y,
        1.5,
        15
      );
      controls.target.z = THREE.MathUtils.clamp(
        controls.target.z,
        -18,
        20
      );

      const offset = new THREE.Vector3().setFromSphericalCoords(
        controls.radius,
        controls.phi,
        controls.theta
      );

      camera.position.copy(controls.target).add(offset);
      camera.lookAt(controls.target);
    }

    function resetView() {
      controls.target.set(12.5, 4.8, 1.2);
      controls.radius = 40;
      controls.theta = 0.72;
      controls.phi = 1.08;
      updateCamera();
    }

    const canvas = renderer.domElement;
    const pointers = new Map();

    let gestureMode = "orbit";
    let previousPointer = null;
    let pinchDistance = 0;

    function pointerDistance() {
      const values = [...pointers.values()];
      if (values.length < 2) return 0;
      return Math.hypot(
        values[0].x - values[1].x,
        values[0].y - values[1].y
      );
    }

    canvas.addEventListener("contextmenu", (event) => {
      event.preventDefault();
    });

    canvas.addEventListener("pointerdown", (event) => {
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        gestureMode =
          event.button === 2 || event.shiftKey ? "pan" : "orbit";
        previousPointer = {
          x: event.clientX,
          y: event.clientY
        };
      } else if (pointers.size === 2) {
        gestureMode = "pinch";
        pinchDistance = pointerDistance();
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (gestureMode === "pinch" && pointers.size >= 2) {
        const newDistance = pointerDistance();

        if (pinchDistance > 0 && newDistance > 0) {
          controls.radius = THREE.MathUtils.clamp(
            controls.radius * (pinchDistance / newDistance),
            controls.minRadius,
            controls.maxRadius
          );
        }

        pinchDistance = newDistance;
        return;
      }

      if (!previousPointer) return;

      const dx = event.clientX - previousPointer.x;
      const dy = event.clientY - previousPointer.y;
      previousPointer = {
        x: event.clientX,
        y: event.clientY
      };

      if (gestureMode === "orbit") {
        controls.theta -= dx * 0.005;
        controls.phi = THREE.MathUtils.clamp(
          controls.phi - dy * 0.0045,
          0.28,
          1.47
        );
      } else if (gestureMode === "pan") {
        const right = new THREE.Vector3();
        const up = new THREE.Vector3();
        camera.matrixWorld.extractBasis(right, up, new THREE.Vector3());

        const panScale = controls.radius * 0.0012;
        controls.target.addScaledVector(right, -dx * panScale);
        controls.target.addScaledVector(up, dy * panScale);
      }
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);

      if (pointers.size === 0) {
        previousPointer = null;
        gestureMode = "orbit";
      } else if (pointers.size === 1) {
        const remaining = [...pointers.values()][0];
        previousPointer = {
          x: remaining.x,
          y: remaining.y
        };
        gestureMode = "orbit";
      }
    }

    canvas.addEventListener("pointerup", releasePointer);
    canvas.addEventListener("pointercancel", releasePointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        const factor = Math.exp(event.deltaY * 0.001);
        controls.radius = THREE.MathUtils.clamp(
          controls.radius * factor,
          controls.minRadius,
          controls.maxRadius
        );
      },
      { passive: false }
    );

    window.addEventListener("keydown", (event) => {
      const key = event.key.toLowerCase();

      if (key === "r") {
        resetView();
        return;
      }

      if (key === "arrowleft") {
        controls.theta -= 0.1;
      } else if (key === "arrowright") {
        controls.theta += 0.1;
      } else if (key === "arrowup") {
        controls.phi = THREE.MathUtils.clamp(
          controls.phi - 0.08,
          0.28,
          1.47
        );
      } else if (key === "arrowdown") {
        controls.phi = THREE.MathUtils.clamp(
          controls.phi + 0.08,
          0.28,
          1.47
        );
      } else if (key === "+" || key === "=") {
        controls.radius = Math.max(
          controls.minRadius,
          controls.radius * 0.9
        );
      } else if (key === "-") {
        controls.radius = Math.min(
          controls.maxRadius,
          controls.radius * 1.1
        );
      } else {
        return;
      }

      event.preventDefault();
    });

    document.getElementById("resetButton").addEventListener(
      "click",
      resetView
    );

    const labelsButton = document.getElementById("labelsButton");
    let labelsVisible = true;

    labelsButton.addEventListener("click", () => {
      labelsVisible = !labelsVisible;
      labelsGroup.visible = labelsVisible;
      labelsButton.textContent = labelsVisible ? "Labels on" : "Labels off";
    });

    // -------------------------------------------------------------------------
    // Resize and animation
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      // Animate the zip trolley along the descending line.
      const trolleyT = reducedMotion
        ? 0.57
        : 0.53 + Math.sin(elapsed * 0.24) * 0.44;

      const trolleyPosition = zipCurve.getPoint(trolleyT);
      const trolleyTangent = zipCurve.getTangent(trolleyT);

      trolley.position.copy(trolleyPosition);
      trolley.rotation.y = Math.atan2(
        trolleyTangent.x,
        trolleyTangent.z
      );

      // Gentle cloud drift.
      clouds.forEach((cloud) => {
        cloud.position.x =
          cloud.userData.baseX +
          Math.sin(elapsed * 0.055 + cloud.userData.phase) * 2.2;
      });

      updateCamera();
      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    updateCamera();
    renderer.render(scene, camera);
    loading.classList.add("ready");
    animate();
  </script>
</body>
</html>
```

Save as `index.html` and open it in a browser. The scene includes custom camera controls, so no Three.js addons are required.

