  .38
);

box(dryingYard, M.stone, 0, wallHeight + .06, -yardDepth / 2, yardWidth + .25, .16, .52);
box(dryingYard, M.stone, -yardWidth / 2, wallHeight + .06, 0, .52, .16, yardDepth);
box(dryingYard, M.stone,  yardWidth / 2, wallHeight + .06, 0, .52, .16, yardDepth);

for (const side of [-1, 1]) {
  box(
    dryingYard,
