}

makeSign(dryingYard, 'NET DRYING YARD', 0, 2.15, yardDepth / 2 + .22, 4.0);

/* ---------- Shore props ---------- */

function makeBarrel(x, y, z, scale = 1) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  group.scale.setScalar(scale);

  cylinder(group, M.wood, 0, .55, 0, .37, .43, 1.1, 12);
  for (const yy of [.18, .55, .92]) {
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(.405, .035, 6, 16),
      M.iron
    );
    ring.position.y = yy;
    ring.rotation.x = Math.PI / 2;
    group.add(ring);
  }
  scene.add(group);
}

function makeCrate(x, y, z, scale = 1, rotation = 0) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  group.rotation.y = rotation;
  group.scale.setScalar(scale);

  box(group, M.wood, 0, .43, 0, .95, .82, .95);
  for (const side of [-1, 1]) {
    box(group, M.darkWood, 0, .43, side * .49, 1.03, .10, .06);
    box(group, M.darkWood, side * .49, .43, 0, .06, .10, 1.03);
  }
  scene.add(group);
}

function makeLobsterPot(x, y, z, rotation = 0) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  group.rotation.y = rotation;

  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(.48, .56, .38, 8, 1, true),
    M.beam
  );
  group.add(pot);

  for (let i = 0; i < 8; i++) {
    const a = i / 8 * Math.PI * 2;
    box(group, M.iron, Math.cos(a) * .48, 0, Math.sin(a) * .48, .035, .4, .035, false);
  }
  box(group, M.iron, 0, .20, 0, .9, .035, .06, false);
  box(group, M.iron, 0, -.20, 0, .9, .035, .06, false);
  scene.add(group);
}

function makeBollard(x, y, z) {
  cylinder(scene, M.beam, x, y + .55, z, .16, .22, 1.1, 9);
  cylinder(scene, M.iron, x, y + 1.1, z, .25, .19, .12, 9);
}

function makeLamp(x, z) {
  const y = terrainHeight(x, z);
  cylinder(scene, M.iron, x, y + 1.8, z, .055, .085, 3.6, 8);
  box(scene, M.iron, x, y + 3.55, z, .42, .12, .42);

  const lamp = new THREE.Mesh(
    new THREE.SphereGeometry(.16, 10, 8),
    new THREE.MeshStandardMaterial({
      color: 0xffd58a,
      emissive: 0xffa62c,
      emissiveIntensity: 1.4
    })
  );
  lamp.position.set(x, y + 3.38, z);
  scene.add(lamp);
}

makeBarrel(-7.7, .83, -.3, 1.1);
makeBarrel(-8.6, .83, -.6, .9);
makeBarrel(7.4, .83, -.8, 1.05);
makeCrate(8.5, .84, -1.5, .9, .16);
makeCrate(-16.2, .78, 2.3, 1.0, -.12);
makeCrate(-15.4, .78, 2.5, .78, .22);
makeCrate(17.1, .82, 1.0, .95, .2);

for (let i = 0; i < 5; i++) {
  makeLobsterPot(18.3 + i * .72, .84, 4.8 + (i % 2) * .15, range(-.2, .2));
}
makeLobsterPot(-18.3, .78, 3.4, .3);
makeLobsterPot(-18.1, 1.15, 3.4, .1);

