const ropeCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(-4.5, 1.65, 4.5),
  new THREE.Vector3(-3.2, 1.1, 6.4),
  new THREE.Vector3(-3.8, .8, 8.2),
