/* ---------- Distant landscape ---------- */

const distantMaterial = new THREE.MeshStandardMaterial({
  color: 0x65756e,
  roughness: 1,
  flatShading: true
});

for (let i = 0; i < 15; i++) {
  const hill = new THREE.Mesh(
