    );
    puff.position.set(j * 2.1, range(-.3, .55), range(-.8, .8));
    puff.scale.y = range(.45, .7);
    cloud.add(puff);
  }

  cloud.position.set(range(-70, 55), range(17, 27), range(-55, -18));
  cloud.scale.setScalar(range(.7, 1.5));
