/* ---------- Gulls ---------- */

const gulls = [];
const gullWhite = new THREE.MeshStandardMaterial({
  color: 0xf4f0df,
  roughness: .9
});
const gullDark = new THREE.MeshStandardMaterial({
  color: 0x4a5353,
  roughness: .9
});

for (let i = 0; i < 7; i++) {
  const gull = new THREE.Group();

  const body = new THREE.Mesh(
    new THREE.SphereGeometry(.18, 8, 6),
    gullWhite
  );
