    new THREE.ConeGeometry(.045, .17, 6),
    gullDark
  );
  beak.rotation.x = Math.PI / 2;
  beak.position.set(0, .04, .48);
  gull.add(beak);

  const leftWing = box(gull, gullWhite, -.25, .03, 0, .56, .045, .22);
  const rightWing = box(gull, gullWhite, .25, .03, 0, .56, .045, .22);
  leftWing.userData.wing = true;
  rightWing.userData.wing = true;

  gull.position.set(range(-28, 28), range(9, 18), range(-12, 25));
  gull.rotation.y = range(0, Math.PI * 2);
  gull.userData.speed = range(.7, 1.2);
  gull.userData.phase = range(0, 6.2);
  gulls.push(gull);
