}

/* ---------- Custom camera controls ---------- */

const pointer = new THREE.Vector2();
let dragging = false;
let panning = false;
let previousX = 0;
let previousY = 0;

function updateCamera() {
  spherical.makeSafe();
  camera.position.copy(target).add(
    new THREE.Vector3().setFromSpherical(spherical)
  );
  camera.lookAt(target);
}

canvas.addEventListener('pointerdown', event => {
  dragging = true;
  panning = event.button === 2 || event.shiftKey;
  previousX = event.clientX;
  previousY = event.clientY;
  canvas.setPointerCapture(event.pointerId);
});

canvas.addEventListener('pointermove', event => {
  if (!dragging) return;

  const dx = event.clientX - previousX;
  const dy = event.clientY - previousY;
  previousX = event.clientX;
  previousY = event.clientY;

  if (panning) {
    const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
    const scale = spherical.radius * .00135;
    target.addScaledVector(right, -dx * scale);
    target.y = THREE.MathUtils.clamp(target.y + dy * scale, -2, 18);
  } else {
    spherical.theta -= dx * .0048;
    spherical.phi = THREE.MathUtils.clamp(
      spherical.phi - dy * .0042,
      .28,
      1.48
    );
  }

  updateCamera();
});

function stopDragging() {
  dragging = false;
  panning = false;
}
canvas.addEventListener('pointerup', stopDragging);
canvas.addEventListener('pointercancel', stopDragging);
canvas.addEventListener('contextmenu', event => event.preventDefault());

canvas.addEventListener('wheel', event => {
  event.preventDefault();
  spherical.radius = THREE.MathUtils.clamp(
    spherical.radius * Math.exp(event.deltaY * .001),
    28,
    115
  );
  updateCamera();
}, { passive: false });

window.addEventListener('keydown', event => {
  const step = .09;
  if (event.key === 'ArrowLeft') spherical.theta += step;
  if (event.key === 'ArrowRight') spherical.theta -= step;
  if (event.key === 'ArrowUp') spherical.phi -= step * .65;
  if (event.key === 'ArrowDown') spherical.phi += step * .65;
  if (event.key === '+' || event.key === '=') spherical.radius *= .92;
  if (event.key === '-' || event.key === '_') spherical.radius *= 1.08;

  spherical.phi = THREE.MathUtils.clamp(spherical.phi, .28, 1.48);
  spherical.radius = THREE.MathUtils.clamp(spherical.radius, 28, 115);
  updateCamera();
});

function resetView() {
  target.set(0, 2.2, -3.5);
  camera.position.set(49, 31, 56);
  spherical.setFromVector3(camera.position.clone().sub(target));
  updateCamera();
}
document.querySelector('#reset').addEventListener('click', resetView);
canvas.addEventListener('dblclick', resetView);

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

/* ---------- Animation ---------- */

const clock = new THREE.Clock();
let frame = 0;

function animate() {
  requestAnimationFrame(animate);
  const elapsed = clock.getElapsedTime();

  const waterPosition = waterGeometry.attributes.position;
  for (let i = 0; i < waterPosition.count; i++) {
    const { x, z } = waterData[i];
    const wave =
      Math.sin(x * .16 + elapsed * .78 + z * .08) * .075 +
      Math.sin(z * .21 - elapsed * .63 + x * .045) * .045;
    waterPosition.setY(i, wave);
  }
  waterPosition.needsUpdate = true;
  if (frame % 2 === 0) waterGeometry.computeVertexNormals();

  for (const gull of gulls) {
    const phase = gull.userData.phase + elapsed * gull.userData.speed;
    gull.position.y += Math.sin(phase * 1.7) * .003;
    gull.rotation.z = Math.sin(phase) * .08;

    for (const child of gull.children) {
      if (child.userData.wing) {
        child.rotation.z = child.position.x < 0
          ? Math.sin(phase * 4.2) * .48
          : -Math.sin(phase * 4.2) * .48;
      }
    }
  }

  for (const cloud of clouds) {
    cloud.position.x += cloud.userData.speed * .008;
    if (cloud.position.x > 72) cloud.position.x = -72;
  }

  for (const buoy of buoys) {
    buoy.position.y = buoy.userData.baseY +
      Math.sin(elapsed * 1.4 + buoy.userData.phase) * .08;
    buoy.rotation.z = Math.sin(elapsed + buoy.userData.phase) * .08;
  }

  frame++;
  renderer.render(scene, camera);
}

updateCamera();
animate();
