    function smoothstep(value) {
      const x = THREE.MathUtils.clamp(value, 0, 1);
      return x * x * (3 - 2 * x);
    }

    function updateSMT(time) {
      const cycle = (time % 8) / 8;
      let x = -6.8;
      let z = -1.95;
      let descend = 0;

      if (cycle < 0.22) {
        x = -6.8;
        z = -1.95;
        descend = smoothstep(cycle / 0.22) * 0.48;
      } else if (cycle < 0.42) {
        const p = smoothstep((cycle - 0.22) / 0.2);
        x = THREE.MathUtils.lerp(-6.8, -5.15, p);
        z = -1.95;
        descend = 0.48 * (1 - p);
      } else if (cycle < 0.65) {
        const p = smoothstep((cycle - 0.42) / 0.23);
        x = -5.15;
        z = THREE.MathUtils.lerp(-1.95, 0, p);
        descend = 0;
      } else if (cycle < 0.78) {
        x = -5.15;
        z = 0;
        descend = smoothstep((cycle - 0.65) / 0.13) * 0.55;
      } else {
        const p = smoothstep((cycle - 0.78) / 0.22);
        x = THREE.MathUtils.lerp(-5.15, -6.8, p);
        z = THREE.MathUtils.lerp(0, -1.95, p);
        descend = 0.55 * (1 - p);
      }

      gantryBridge.position.x = x;
      pickHead.position.z = z;
      pickHead.position.y = -0.05 - descend;
      heldComponent.visible = cycle > 0.15 && cycle < 0.73;
    }

    function updateRobots(time) {
      robots.forEach((robot, index) => {
        const wave = Math.sin(time * 0.85 + robot.phase);
        const wave2 = Math.sin(time * 0.85 + robot.phase + 1.1);

        robot.shoulder.rotation.z = -0.55 + wave * 0.36;
        robot.shoulder.rotation.x = 0.08 * wave2;
        robot.elbow.rotation.z = 1.18 + wave2 * 0.34;
        robot.wrist.rotation.z = -0.55 - wave * 0.18;

        robot.elbow.rotation.y = Math.sin(time * 0.7 + robot.phase + index) * 0.08;
      });
    }

    function updateAGV(time) {
      const progress = (time * 0.075) % 1;
      const segmentProgress = progress * 4;
      const segment = Math.floor(segmentProgress);
      const p = segmentProgress - segment;

      if (segment === 0) {
        agv.position.set(THREE.MathUtils.lerp(-9, 9, p), 0, 7.4);
        agv.rotation.y = 0;
      } else if (segment === 1) {
        agv.position.set(9, 0, THREE.MathUtils.lerp(7.4, 4.8, p));
        agv.rotation.y = -Math.PI / 2;
      } else if (segment === 2) {
        agv.position.set(THREE.MathUtils.lerp(9, -9, p), 0, 4.8);
        agv.rotation.y = Math.PI;
      } else {
        agv.position.set(-9, 0, THREE.MathUtils.lerp(4.8, 7.4, p));
        agv.rotation.y = Math.PI / 2;
      }
    }

    function updateParticles(time) {
      for (let i = 0; i < particleCount; i++) {
        const seed = particleSeeds[i];
        const life = (seed.phase + time * seed.speed) % 1;
        const spread = seed.radius * life * 5;

        particlePositions[i * 3] =
          6.85 + Math.sin(time * 0.7 + i) * spread;
        particlePositions[i * 3 + 1] =
          6.45 + life * 2.2;
        particlePositions[i * 3 + 2] =
          -0.45 + Math.cos(time * 0.6 + i * 1.7) * spread;
      }
      particleGeometry.attributes.position.needsUpdate = true;
    }

    function updateBoards(time) {
      boardGroups.forEach((line, lineIndex) => {
        const direction = lineIndex === 0 ? 1 : -1;
        const speed = lineIndex === 0 ? 1.05 : 0.82;

        line.boards.forEach((board, index) => {
          const phase = index * 3.05 + lineIndex * 1.4;
          const raw = ((phase + time * speed * direction) % 21 + 21) % 21;
          const x = -10.5 + raw;
          board.position.x = x;

          const stage =
            x < -6.3 ? 0 : x < 0.2 ? 1 : 2;

          board.userData.parts.forEach((part) => {
            const requiredStage = part.userData.stage;
            part.visible =
              requiredStage === 0 ||
              (requiredStage === 1 && stage >= 1) ||
              (requiredStage === 2 && stage >= 2);
          });
        });
      });
    }

    function updateHUD() {
      const throughput = Math.round(842 + Math.sin(elapsed * 0.35) * 13);
      const oee = (96.8 + Math.sin(elapsed * 0.17) * 0.3).toFixed(1);

      document.querySelector("#throughput").textContent = throughput;
      document.querySelector("#oee").textContent = `${oee}%`;

      const totalSeconds = Math.floor(8 * 3600 + 42 * 60 + 16 + elapsed);
      const hours = Math.floor(totalSeconds / 3600) % 24;
      const minutes = Math.floor(totalSeconds / 60) % 60;
      const seconds = totalSeconds % 60;

      document.querySelector("#uptime").textContent = [
        hours,
        minutes,
        seconds
      ]
        .map((value) => String(value).padStart(2, "0"))
        .join(":");
    }

    const pauseButton = document.querySelector("#pause");

    function togglePause() {
      paused = !paused;
      pauseButton.textContent = paused ? "RESUME" : "PAUSE";
      document.querySelector("#run-state").textContent = paused
        ? "SYSTEM PAUSED"
        : "SYSTEM RUNNING";
      document.querySelector(".status-dot").style.background = paused
        ? "#ffc65c"
        : "#74f2a8";
      document.querySelector(".status-dot").style.boxShadow = paused
        ? "0 0 12px #ffc65c"
        : "0 0 12px #74f2a8";
    }

    pauseButton.addEventListener("click", togglePause);

    window.addEventListener("keydown", (event) => {
      if (event.code === "Space") {
        event.preventDefault();
        togglePause();
      }

      const keyViews = {
        Digit1: "overview",
        Digit2: "pick",
        Digit3: "inspection",
        Digit4: "oven",
        Digit5: "top"
      };

      if (keyViews[event.code]) {
        setView(keyViews[event.code]);
      }
    });

    function animate() {
      requestAnimationFrame(animate);

      const dt = Math.min(clock.getDelta(), 0.05);
      if (!paused) elapsed += dt;

      updateCamera(dt);

      beltTextures.forEach((texture, index) => {
        texture.offset.x -= dt * (index === 0 ? 0.18 : 0.14);
      });

      updateBoards(elapsed);
      updateSMT(elapsed);
      updateRobots(elapsed);
      updateAGV(elapsed);
      updateParticles(elapsed);

      ovenLight.intensity = 10.5 + Math.sin(elapsed * 2.2) * 1.2;
      scannerLight.intensity = 7.2 + Math.sin(elapsed * 4.8) * 1.1;

      if (elapsed - lastMonitorUpdate > 0.35) {
        drawMonitor(elapsed);
        updateHUD();
        lastMonitorUpdate = elapsed;
      }

      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.75));
    });

    updateCamera(1);
    drawMonitor(0);
    updateHUD();
    animate();

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
      setTimeout(() => loading.remove(), 500);
    });
  </script>
</body>
</html>
